const DB = {};
/*COURSE_DB*/Object.assign(DB, {"sci6~1_1":{"course":"sci6","sem":1,"unitNum":1,"unitTitle":"الوحدة الأولى: جسم الإنسان","unitShort":"جسم الإنسان","code":"1-1","title":"أعضاء الجسم","defaultDuration":45,"objectives":[{"id":"sci6~1_1_o0","code":"6Bh1","text":"يستخدم الأسماء العلمية لبعض أعضاء أجهزة الجسم الرئيسية (الدماغ، القلب، الرئتين، الكليتين، المعدة، الأمعاء، الكبد).","selected":true,"suffix":"","activities":[{"time45":"10 د","time90":"20 د","teacher":"يقدّم الأعضاء بأنها الأجزاء الداخلية للجسم التي تعمل معاً لتشكل أجهزة الجسم، ويعرض الشكل ص 18 ويسمي كل عضو باسمه العلمي.","student":"يشير إلى كل عضو على الشكل وينطق اسمه ويدوّنه في دفتره.","eval":"الشكل ص 18."},{"time45":"12 د","time90":"24 د","teacher":"يوزع ورقة العمل 1-1 (تسمية أعضاء الجسم) والكلمات في الصندوق ثم يراجع التسمية على الشكل.","student":"يسمي الأعضاء في الشكل مستعيناً بالكلمات في الصندوق.","eval":"ورقة العمل 1-1 وتمرين 1-1."}]},{"id":"sci6~1_1_o1","code":"6Bh2","text":"يحدّد مواضع الأعضاء الرئيسية في الجسم (الدماغ، القلب، الرئتين، الكليتين، المعدة، الأمعاء، الكبد).","selected":true,"suffix":"","activities":[{"time45":"14 د","time90":"28 د","teacher":"يشرف على نشاط 1-1: رسم الأعضاء وتلوينها وقصها ولصقها على مخطط الجسم بحجمها وموضعها الصحيحين.","student":"يرسم الأعضاء ويلصقها في مكانها على مخطط جسم زميله.","eval":"نشاط 1-1 ص 19."},{"time45":"8 د","time90":"16 د","teacher":"يربط موضع العضو بحمايته: الجمجمة تحمي الدماغ والأضلاع تحمي القلب والرئتين (من دراسة الصف الرابع).","student":"يحدد على المخطط العظام التي تحمي كل عضو.","eval":"تحدث عن ص 19."}]}],"prior":"الأجزاء الخارجية للجسم؛ الهيكل العظمي يحمي الدماغ والقلب والرئتين (الصف الرابع)؛ ما تعرفه الطلبة عن أجهزة الجسم من الصفوف السابقة","warmup":"فكّر في أكبر عدد ممكن من أجزاء الجسم الداخلية.","resources":"كتاب الطالب (ص 18-19)، الشكل ص 18، نشاط 1-1، تمرين 1-1 وورقة العمل 1-1 في كتاب النشاط، ورق مقوى، ورق أبيض، أقلام تلوين، غراء، مقص، ملصق أو صورة لجسم الإنسان.","strategies":["العصف الذهني","الحوار والمناقشة","التعلم التعاوني","الأسئلة السابرة"],"lab":"نشاط 1-1: تحديد موقع بعض أعضاء الجسم. ورق مقوى على الحائط، ورقة بيضاء لكل مجموعة، أقلام تلوين، غراء ومقص. ينبّه الطلبة إلى استخدام المقص بحذر وإلى أن حجم كل عضو يناسب مخطط الجسم، وتُعدّ الأعضاء مسبقاً إن ضاق الوقت.","misconception":"يظن بعض الطلبة أن الأعضاء كلها تقع في البطن أو أن القلب يقع في الجانب الأيسر وحده. التشخيص: يطلب المعلم من الطالب تأشير موضع القلب والرئتين على مخطط الجسم. المعالجة: يستعين بالشكل ص 18 ونشاط 1-1 ليتبيّن أن القلب في الصدر بين الرئتين وأن الرئتين زوج في الصدر لا في البطن.","exitTicket":"سمِّ ثلاثة أعضاء رئيسية وبيّن موضع كل منها.","homework":"إكمال تمرين 1-1 في كتاب النشاط (تسمية الأعضاء ووصلها بمواضعها) ومراجعة ورقة العمل 1-1 ذاتياً بعد مناقشة الإجابات في الصف.","guideAnswers":"<b>نشاط 1-1:</b> (1) الدماغ. (2) القلب والرئتان. (3) الرئتان والكليتان. (4) المعدة والأمعاء والكليتان. (5) تختلف الإجابات: القلب يضخ الدم، والرئتان للتنفس، والكليتان للإخراج، والمعدة والأمعاء للهضم.<br><b>ورقة العمل 1-1:</b> تسمية الدماغ والرئتين والقلب والمعدة والكليتين والأمعاء في الشكل.<br><b>تحدث عن:</b> الجمجمة تحمي الدماغ والأضلاع تحمي القلب والرئتين."},"sci6~1_2":{"course":"sci6","sem":1,"unitNum":1,"unitTitle":"الوحدة الأولى: جسم الإنسان","unitShort":"جسم الإنسان","code":"1-2","title":"القلب","defaultDuration":45,"objectives":[{"id":"sci6~1_2_o0","code":"6Bh2","text":"يحدّد موضع القلب في الجسم.","selected":true,"suffix":"","activities":[{"time45":"8 د","time90":"16 د","teacher":"يعرض ملصقاً للقلب ويطلب من الطلبة ضم قبضة اليد ليقدروا حجمه، ثم يبين أنه في الصدر جهة اليسار قليلاً وتحيط به الأضلاع.","student":"يضع قبضته على صدره ويحدد موضع القلب ويستمع إلى دقاته بأنبوب الكرتون.","eval":"الشكل ص 20 وبكرة ورق المطبخ."}]},{"id":"sci6~1_2_o1","code":"6Bh3","text":"يصف الوظيفة الأساسية للقلب.","selected":true,"suffix":"","activities":[{"time45":"12 د","time90":"24 د","teacher":"يوضح بنموذج العبوة البلاستيكية الممتلئة بالماء كيف يضخ القلب الدم، ويشرح أن القلب عضلة تنقبض وتنبسط باستمرار.","student":"يضغط على العبوة ويلاحظ خروج الماء بقوة ويربطه بضخ القلب للدم.","eval":"نموذج العبوة وأسئلة 1-3 ص 21."},{"time45":"10 د","time90":"20 د","teacher":"يوضح جانبي القلب على الشكل: الأيسر يضخ الدم المحمّل بالأكسجين إلى الجسم والأيمن يضخ الدم غير المحمّل به إلى الرئتين.","student":"يلوّن جانبي القلب على رسم ويكتب ما يضخه كل جانب.","eval":"الرسم ص 20."}]},{"id":"sci6~1_2_o2","code":"6Bh4","text":"يشرح أهمية القلب والدم والأوعية الدموية في الجسم.","selected":true,"suffix":"","activities":[{"time45":"10 د","time90":"20 د","teacher":"يبين أن الدم يتدفق داخل الأوعية الدموية فيحمل الغذاء والأكسجين إلى أجزاء الجسم ويحمل الفضلات إلى الكليتين والرئتين.","student":"يتتبع مسار الدم على الرسم ويذكر ما يحمله.","eval":"ص 21."},{"time45":"8 د","time90":"16 د","teacher":"يناقش السؤال (3): لماذا يضخ القلب الدم إلى الرئتين قبل بقية الجسم؟ ويصل ذلك بمفهوم الدورة الدموية.","student":"يفسر شفهياً ويكتب إجابته.","eval":"السؤال (3) ص 21."}]},{"id":"sci6~1_2_o3","code":"6Ep1","text":"يدرس كيف جمع العلماء أدلة من الملاحظة والقياس مع التفكير الإبداعي لاقتراح تفسيرات للظواهر.","selected":true,"suffix":"","activities":[{"time45":"12 د","time90":"24 د","teacher":"يعرض اعتقادات الإغريق القديمة عن الدورة الدموية، ثم عمل ابن النفيس (الدورة الدموية الصغرى) وويليام هارفي، ويوزع ورقتي العمل 1-2 (أ) و(ب).","student":"يقرأ الورقتين ويجيب عن أسئلتهما ويقارن بين الأفكار القديمة والحديثة.","eval":"ورقتا العمل 1-2 (أ) و(ب)."}]}],"prior":"العضلات تنقبض وتنبسط (الصف الرابع)؛ موضع القلب في الصدر وحماية الأضلاع له؛ الكلمات: عضو، جهاز","warmup":"ضع يدك على صدرك. هل تشعر بدقات القلب؟ لماذا يدق قلبك؟","resources":"كتاب الطالب (ص 20-22)، الشكلان ص 20 و21، تمرين 1-2 وورقتا العمل 1-2 (أ) و(ب) في كتاب النشاط، أنبوب ورق المطبخ، عبوة سائل تنظيف بلاستيكية ممتلئة بالماء، سماعة طبيب (إن أمكن)، ملصق للقلب.","strategies":["الأسئلة السابرة","الاستقصاء الموجه","النمذجة العلمية","المحاكاة البصرية","الحوار والمناقشة","حل المشكلات"],"lab":"الاستماع إلى دقات القلب بأنبوب ورق المطبخ ونموذج العبوة التي تضخ الماء. يوضع الأنبوب على صدر الزميل بلطف ويطلب الهدوء التام، ويُجرّب النموذج بعيداً عن الأجهزة الكهربائية ويُجفف الماء المنسكب.","misconception":"يظن بعض الطلبة أن الدم في الأوردة أزرق لأن الرسوم تلوّنها بالأزرق. التشخيص: يسأل المعلم عن لون الدم داخل الأوعية. المعالجة: يوضح أن الدم كله أحمر وأن الدم غير المحمّل بالأكسجين أكثر قتامة وأن الألوان في الرسم للتمييز فقط.","exitTicket":"اذكر مكونات الجهاز الدوري الثلاثة.","homework":"تمرين 1-2 في كتاب النشاط (إكمال الجمل) وسؤال التحدي: ما المقصود بالنوبة القلبية وكيف تحدث؟ مع مناقشة الإجابات في الصف.","guideAnswers":"<b>الأسئلة ص 21:</b> (1) أ- يضخ الدم عبر الجسم. ب- ليزوّد جميع أجزاء الجسم بالغذاء والأكسجين ويخرج الفضلات. (2) انقباض عضلة القلب أثناء ضخ الدم. (3) ليأخذ الأكسجين من الرئتين فينقله الدم إلى باقي أجزاء الجسم.<br><b>التحدي:</b> تحدث النوبة القلبية عندما لا تتلقى عضلة القلب ما يكفيها من الأكسجين والغذاء بسبب انسداد الأوعية التي تزودها بالدم.<br><b>تمرين 1-2:</b> الجهاز الدوري، ومكوناه الدم والأوعية الدموية؛ يضخ القلب الدم إلى جميع أجزاء الجسم، والجانب الأيسر يضخ الدم المحمّل بالأكسجين، والأيمن يضخ الدم غير المحمّل به إلى الرئتين.<br><b>ورقة 1-2 (أ):</b> اعتقدوا أن الدم يتولد في الكبد؛ ويحث ابن النفيس على التحرر من الأفكار الخاطئة؛ وظيفة الرئتين نقل الأكسجين إلى الدم والتخلص من ثاني أكسيد الكربون.<br><b>ورقة 1-2 (ب):</b> أجرى هارفي ملاحظات وتجارب للتأكد من دقة نتائجه، ولاحظ أن القلب يضخ في الساعة أكثر من وزن الجسم من الدم."},"sci6~1_3":{"course":"sci6","sem":1,"unitNum":1,"unitTitle":"الوحدة الأولى: جسم الإنسان","unitShort":"جسم الإنسان","code":"1-3","title":"دقات القلب والنبض: أ. قياس معدل النبض","defaultDuration":45,"objectives":[{"id":"sci6~1_3_o0","code":"6Ep6","text":"يحدّد العوامل المرتبطة بموقف محدد (العوامل المؤثرة في معدل النبض).","selected":true,"suffix":"","activities":[{"time45":"10 د","time90":"20 د","teacher":"يسأل الطلبة عن أوقات يتغير فيها نبضهم ويسجل العوامل المقترحة: النشاط البدني، القلق، الوقت من اليوم، المرض أو الحمى، العمر.","student":"يقترح عوامل تغير معدل نبضه ويفسر اقتراحه.","eval":"السؤال (4) ص 23."}]},{"id":"sci6~1_3_o1","code":"6Ep7","text":"يختار الأدوات التي يجب استخدامها لقياس معدل النبض.","selected":true,"suffix":"","activities":[{"time45":"5 د","time90":"10 د","teacher":"يعرض أدوات متنوعة ويطلب اختيار الأنسب لقياس معدل النبض في الدقيقة (ساعة بعقرب ثوانٍ أو ساعة إيقاف).","student":"يختار الأداة المناسبة ويبرر اختياره.","eval":"نشاط 1-3 ص 22."}]},{"id":"sci6~1_3_o2","code":"6Eo1","text":"يقوم بقياس معدل النبض باستخدام أدوات بسيطة بشكل صحيح.","selected":true,"suffix":"","activities":[{"time45":"15 د","time90":"30 د","teacher":"يبين أين يستشعر النبض (المعصم أو العنق) بأصبعين لا بالإبهام، ويقيس نبضه أمامهم ويسجله على السبورة ثم يشرف على عمل المجموعات.","student":"يقيس عدد النبضات في دقيقة ويدونه في جدول.","eval":"نشاط 1-3 ص 22."}]},{"id":"sci6~1_3_o3","code":"6Eo2","text":"يقرر متى تكون هناك ضرورة للتحقق من القياسات عن طريق التكرار.","selected":true,"suffix":"","activities":[{"time45":"8 د","time90":"16 د","teacher":"يطلب تكرار القياس ثلاث مرات ويسأل: هل يتساوى العدد في كل مرة؟ ولماذا نكرر القياس؟","student":"يكرر القياس ثلاث مرات ويقارن نتائجه.","eval":"السؤال (3) ص 23."}]},{"id":"sci6~1_3_o4","code":"6Eo5","text":"يقيّم النتائج المتكررة (يحسب المتوسط ويحدد القياس غير الدقيق).","selected":true,"suffix":"","activities":[{"time45":"10 د","time90":"20 د","teacher":"يبين طريقة حساب المتوسط بجمع القياسات وقسمتها على عددها، ثم يوجه تمرين 1-3 (نتائج مازن وأصدقائه).","student":"يحسب المتوسط ويحدد النتيجة التي لا تناسب النمط ويقترح سببها.","eval":"تمرين 1-3."}]}],"prior":"القلب عضلة تنقبض وتنبسط وتضخ الدم؛ القياس باستخدام الزمن وأدواته؛ ما المقصود بالمتوسط (من الرياضيات)","warmup":"كم مرة تقريباً يدق قلب الطفل في الدقيقة الواحدة؟","resources":"كتاب الطالب (ص 22-23)، نشاط 1-3 والأسئلة 1-4، تمرين 1-3 في كتاب النشاط، ساعة بعقرب ثوانٍ أو ساعة إيقاف، أوراق، سماعة طبيب (إن أمكن).","strategies":["الأسئلة السابرة","الحوار والمناقشة","الاستقصاء الموجه","التعلم التعاوني","حل المشكلات","العصف الذهني"],"lab":"نشاط 1-3: قياس النبض في مجموعات من 4-5 طلبة بساعة إيقاف أو ساعة بعقرب ثوانٍ، يوضع إصبعان (لا الإبهام) على المعصم أو العنق دون ضغط شديد، ويعدّ النبض دقيقة كاملة ويكرر ثلاث مرات. يطلب من الطلبة الجلوس بهدوء قبل القياس.","misconception":"يظن بعض الطلبة أن النبض ودقات القلب شيء واحد. التشخيص: يسأل المعلم عن الفرق بينهما. المعالجة: دقات القلب انقباض عضلته عند ضخ الدم، والنبض موجة ضغط الدم الناتجة عنه والتي نحسها في المعصم أو العنق.","exitTicket":"قيست ثلاث نبضات: 88 و90 و92. ما المتوسط؟","homework":"إكمال تمرين 1-3 في كتاب النشاط، وقياس معدل النبض مساءً وصباحاً وتسجيله ليناقش الطلبة الفرق في الحصة التالية.","guideAnswers":"<b>نشاط 1-3:</b> (1) دقات القلب انقباض عضلة القلب أثناء ضخ الدم، والنبض الضغط الناجم عن ضغط الدم أثناء ضخه من القلب. (2) لا. (3) أ- لا. ب- يتغير معدل النبض قليلاً خلال اليوم ويتأثر بالنشاط والقلق، وربما قيس بشكل غير دقيق. ج- نجمع القياسات ثم نقسم المجموع على عددها. (4) النشاط البدني، القلق، الوقت من اليوم، المرض أو الحمى، العمر.<br><b>تمرين 1-3:</b> (1) نبضة في الدقيقة. (2) المتوسط 93 نبضة في الدقيقة (465 ÷ 5). (3) أ- معظم القياسات حول 90. ب- نتيجة أحمد 110، وسببها قياسها أثناء ممارسة الرياضة. ج- يقاس نبض أحمد وهو يمارس الرياضة أو يقاس نبض المجموعة أثناء ممارسة الرياضة."},"sci6~1_3b":{"course":"sci6","sem":1,"unitNum":1,"unitTitle":"الوحدة الأولى: جسم الإنسان","unitShort":"جسم الإنسان","code":"1-3","title":"دقات القلب والنبض: ب. أثر التمرين والتمثيل البياني","defaultDuration":45,"objectives":[{"id":"sci6~1_3b_o0","code":"6Ep4","text":"يتنبأ بما سيحدث بناءً على المعرفة العلمية والفهم (أثر التمرين في معدل النبض).","selected":true,"suffix":"","activities":[{"time45":"8 د","time90":"16 د","teacher":"يطلب اختيار عامل (التمرين الرياضي) وتسجيل تنبؤهم بتأثيره في معدل النبض مع السبب العلمي.","student":"يكتب تنبؤه ويفسره بحاجة الجسم إلى الغذاء والأكسجين.","eval":"السؤال (4) ص 23."}]},{"id":"sci6~1_3b_o1","code":"6Ep2","text":"يجمع الأدلة والبيانات لاختبار الأفكار بما في ذلك التنبؤات.","selected":true,"suffix":"","activities":[{"time45":"12 د","time90":"24 د","teacher":"يشرف على قياس النبض قبل التمرين وبعد الجري في المكان دقيقة، وتسجل المجموعات نتائجها.","student":"يقيس نبضه قبل التمرين وبعده ويسجل القياسين.","eval":"دليل ص 30."}]},{"id":"sci6~1_3b_o2","code":"6Eo3","text":"يستخدم الجداول والتمثيل البياني بالأعمدة والتمثيل الخطي لعرض النتائج.","selected":true,"suffix":"","activities":[{"time45":"10 د","time90":"20 د","teacher":"يوجه ورقة العمل 1-3 (ب): رسم أعمدة بيانية لمعدلات النبض قبل التمرين وبعده مع كتابة البيانات على الرسم.","student":"يرسم الأعمدة بالمسطرة بعنوان ومحورين وتدرج صحيح.","eval":"ورقة العمل 1-3 (ب)."},{"time45":"10 د","time90":"20 د","teacher":"يوجه ورقة العمل 1-3 (ج): رسم خطي لنبض راشد مع الزمن ويراجع المعايير: العنوان والنقاط والتوصيل.","student":"يرسم الرسم الخطي ويمثل تنبؤه عليه.","eval":"ورقة العمل 1-3 (ج)."}]},{"id":"sci6~1_3b_o3","code":"6Eo4","text":"يعقد مقارنات (بين معدلات دقات القلب في كائنات حية مختلفة).","selected":true,"suffix":"","activities":[{"time45":"8 د","time90":"16 د","teacher":"يوزع ورقة العمل 1-3 (أ) ويطلب ترتيب الكائنات حسب دقات القلب ومقارنتها بحجمها.","student":"يرتب الكائنات ويقارن الأكبر بالأصغر.","eval":"ورقة العمل 1-3 (أ)."}]},{"id":"sci6~1_3b_o4","code":"6Eo6","text":"يحدّد الأنماط في النتائج والنتائج التي لا تبدو ملائمة للنمط.","selected":true,"suffix":"","activities":[{"time45":"6 د","time90":"12 د","teacher":"يسأل عن النمط: تصبح الدقات أسرع كلما كان الحيوان أصغر، ويناقش نتيجة الخفاش في السبات.","student":"يصف النمط ويفسر الخفاش.","eval":"ورقة العمل 1-3 (أ) والتحدي."}]},{"id":"sci6~1_3b_o5","code":"6Eo7","text":"يستخدم النتائج لاستخلاص الاستنتاجات وتقديم المزيد من التنبؤات.","selected":true,"suffix":"","activities":[{"time45":"6 د","time90":"12 د","teacher":"يطلب كتابة استنتاج من الجدول والتنبؤ بدقات قلب الحصان والذبابة.","student":"يكتب الاستنتاج ويتنبأ بالقيم.","eval":"ورقة العمل 1-3 (أ) سؤال 4."}]},{"id":"sci6~1_3b_o6","code":"6Eo9","text":"يحدد ما إذا كانت الأدلة تدعم تنبؤاً ما، مبيناً كيف.","selected":true,"suffix":"","activities":[{"time45":"5 د","time90":"10 د","teacher":"يطلب مقارنة النتائج بتنبؤهم الأول وبيان هل تدعمه الأدلة.","student":"يقارن نتائجه بتنبؤه ويقرر هل تدعمه.","eval":"دليل ص 30."}]}],"prior":"الفرق بين دقات القلب والنبض؛ قياس معدل النبض بالدقيقة وحساب المتوسط؛ رسم الأعمدة البيانية من الرياضيات","warmup":"ماذا يحدث لمعدل نبضك بعد الجري؟ ولماذا؟","resources":"كتاب الطالب (ص 23)، ورقات العمل 1-3 (أ) و(ب) و(ج) في كتاب النشاط، ساعة إيقاف، مساطر، ورق رسم بياني، أقلام ملونة.","strategies":["الأسئلة السابرة","التنبؤ والملاحظة والتفسير (POE)","الاستقصاء الموجه","حل المشكلات","المقارنة والتصنيف"],"lab":"استقصاء أثر التمرين في معدل النبض: يقيس الطلبة نبضهم قبل الجري في المكان دقيقة وبعده. يستثنى الطالب الذي لا يسمح له بالجهد البدني، وتجرى الحصة في مكان واسع آمن.","misconception":"يظن بعض الطلبة أن القلب يدق بالمعدل نفسه دائماً. التشخيص: يسأل المعلم: هل يتغير نبضك إذا جريت؟ المعالجة: يقيس الطلبة النبض قبل التمرين وبعده فيلاحظون الزيادة، ويربطونها بحاجة الجسم إلى مزيد من الغذاء والأكسجين.","exitTicket":"تنبأ: أي الكائنين نبضه أسرع، فأر أم حصان؟ ولماذا؟","homework":"إكمال ورقة العمل 1-3 (ج) للطلبة ذوي التحصيل المرتفع، وإكمال تمرين 1-3 لذوي التحصيل المنخفض (توجيه الدليل).","guideAnswers":"<b>ورقة العمل 1-3 (أ):</b> (1) أ- الطائر الطنان. ب- الحوت الأزرق. (2) أ- الحوت الأزرق. ب- الطائر الطنان. (3) أ- الحوت الأزرق، الفيل، الإنسان، القطة، الفأر، الطائر الطنان. ب- تصبح دقات القلب أسرع كلما كان الحيوان أصغر. (4) أ- الكائنات الكبيرة دقات قلبها أبطأ من الصغيرة. ب- الحصان 45 نبضة في الدقيقة والذبابة نحو 600. <b>التحدي:</b> تصبح العمليات الحيوية في جسم الخفاش بطيئة أثناء السبات فيحتاج قليلاً من الطعام والأكسجين.<br><b>ورقة العمل 1-3 (ب):</b> (1) ساعة إيقاف أو ساعة بعقرب ثوانٍ. (3) أ- ممارسة الرياضة تزيد معدل النبض. ب- يزداد معدل النبض.<br><b>ورقة العمل 1-3 (ج):</b> رسم خطي للنتائج؛ التنبؤ بعد انتهاء التمرين أقل من 140؛ وعند ممارسة الرياضة تحتاج العضلات إلى مزيد من الغذاء والأكسجين فيضخ القلب أسرع ويزداد النبض."},"sci6~1_4":{"course":"sci6","sem":1,"unitNum":1,"unitTitle":"الوحدة الأولى: جسم الإنسان","unitShort":"جسم الإنسان","code":"1-4","title":"الرئتان والتنفس: أ. الرئتان وعملية التنفس","defaultDuration":45,"objectives":[{"id":"sci6~1_4_o0","code":"6Bh1","text":"يستخدم الأسماء العلمية لأعضاء الجهاز التنفسي (الأنف، القصبة الهوائية، الرئتان) ويسمي عمليتي الشهيق والزفير.","selected":true,"suffix":"","activities":[{"time45":"12 د","time90":"24 د","teacher":"يستخدم نموذجاً أو مقطع فيديو للجهاز التنفسي ويتتبع مسار الهواء: الأنف أو الفم، الحلق، الحنجرة، القصبة الهوائية، أنبوبان إلى الرئتين.","student":"يسمي الأجزاء على الرسم ص 25 ويرتب مسار الهواء.","eval":"الشكل ص 25."},{"time45":"10 د","time90":"20 د","teacher":"يوجه تمرين 1-4 (2): إكمال المخطط السهمي لمسار الأكسجين بالكلمات المعطاة.","student":"يكمل المخطط السهمي مستعيناً بالصندوق.","eval":"تمرين 1-4."}]},{"id":"sci6~1_4_o1","code":"6Bh2","text":"يحدّد موضع الرئتين في الجسم.","selected":true,"suffix":"","activities":[{"time45":"8 د","time90":"16 د","teacher":"يبين أن الرئتين داخل الصدر وتحيط بهما الضلوع، وهما كقطعتين من الإسفنج المرن، ويسأل عن حجمهما (بحجم كرة قدم عند البالغ).","student":"يشير إلى موضع رئتيه على صدره ويصف شكلهما.","eval":"ص 24."}]},{"id":"sci6~1_4_o2","code":"6Bh3","text":"يصف عمليتي الشهيق والزفير.","selected":true,"suffix":"","activities":[{"time45":"10 د","time90":"20 د","teacher":"يسأل لماذا نتنفس ويشرح الغرض من الشهيق (دخول الهواء) والزفير (خروجه) مع تغير حجم الرئتين.","student":"يكتب جدول مقارنة بين الشهيق والزفير.","eval":"ماذا تعلمت ص 25."}]},{"id":"sci6~1_4_o3","code":"6Bh4","text":"يشرح أهمية التنفس لتزويد الجسم بالأكسجين والتخلص من ثاني أكسيد الكربون.","selected":true,"suffix":"","activities":[{"time45":"8 د","time90":"16 د","teacher":"يوضح أن الأكسجين ينتقل في الدم إلى القلب ثم إلى الجسم، وأن ثاني أكسيد الكربون فضلات يحملها الدم إلى الرئتين فيطرد بالزفير.","student":"يفسر لماذا لا نستطيع العيش دون أكسجين.","eval":"ص 25."}]},{"id":"sci6~1_4_o4","code":"6Eo1","text":"يقوم بملاحظات متنوعة ذات صلة باستخدام أدوات بسيطة بشكل صحيح.","selected":true,"suffix":"","activities":[{"time45":"12 د","time90":"24 د","teacher":"يشرف على نشاط 1-4: يضع الطالب يديه على قفصه الصدري ويتنفس شهيقاً وزفيراً ثم ينفخ بالوناً، ولا يتشاركون البالونات.","student":"يلاحظ حركة الصدر ويدونها وينفخ البالون.","eval":"نشاط 1-4 ص 24."}]}],"prior":"الرئتان محميتان بالضلوع (الصف الرابع)؛ الدم ينقل الأكسجين من الرئتين إلى الجسم (الدرس 1-2)؛ عملية التنفس بشكل عام","warmup":"ما الشيء الذي نفعله مرات كثيرة في الدقيقة دون أن نفكر فيه؟","resources":"كتاب الطالب (ص 24-25)، الشكل ص 25، نشاط 1-4 والأسئلة 1-4، تمرين 1-4 في كتاب النشاط، بالونات (لكل طالب بالونه) أو أكياس بلاستيكية صغيرة، نموذج أو مقطع فيديو للجهاز التنفسي، بطاقات أسماء.","strategies":["الأسئلة السابرة","الحوار والمناقشة","المحاكاة البصرية","الاستقصاء الموجه","حل المشكلات"],"lab":"نشاط 1-4: يعمل كل طالب فردياً، يضع يديه على القفص الصدري ويتنفس بشكل طبيعي ثم أعمق، وينفخ بالونه الخاص. لا يتشارك الطلبة البالونات منعاً للعدوى، وتستبدل بأكياس بلاستيكية صغيرة إن لم تتوفر. يراعى الطلبة المصابون بالربو أو أمراض الجهاز التنفسي عند الحديث عنها.","misconception":"يظن بعض الطلبة أن الرئتين كيسان مجوفان كالبالون يمتلئان بالهواء ثم ينكمشان. التشخيص: يسأل المعلم عن شكل الرئتين من الداخل. المعالجة: يوضح أن الرئتين إسفنجيتان وتتألفان من حويصلات هوائية صغيرة كثيرة، وأن البالون نموذج مبسط فقط.","exitTicket":"اشرح لماذا نحتاج إلى الأكسجين.","homework":"إكمال تمرين 1-4 في كتاب النشاط (رسم الرئتين عند الشهيق وإكمال المخطط السهمي) ومناقشة الإجابات في الصف.","guideAnswers":"<b>الأسئلة ص 24:</b> (1) يكبر حجم الصدر لامتلاء الرئتين بالهواء. (2) يصغر حجم الصدر لأن الرئتين تطردان الهواء للخارج. (3) الهواء يخرج من أجسامنا عند الزفير فيملأ البالون فينتفخ. (4) عند ممارسة الرياضة يحتاج الجسم إلى مزيد من الأكسجين فنتنفس أسرع.<br><b>تمرين 1-4:</b> (1) رسم الرئتين أكبر عند الشهيق. (2) الأنف، القصبة الهوائية، الرئتان، الدم."},"sci6~1_4b":{"course":"sci6","sem":1,"unitNum":1,"unitTitle":"الوحدة الأولى: جسم الإنسان","unitShort":"جسم الإنسان","code":"1-4","title":"الرئتان والتنفس: ب. معدل التنفس والرياضة","defaultDuration":45,"objectives":[{"id":"sci6~1_4b_o0","code":"6Ep4","text":"يتنبأ بما سيحدث لمعدل التنفس بناءً على المعرفة العلمية والفهم.","selected":true,"suffix":"","activities":[{"time45":"8 د","time90":"16 د","teacher":"يطرح السؤال (4): لماذا نتنفس أسرع عند ممارسة الرياضة؟ ويطلب تنبؤاً بمعدل التنفس بعد الجري مع التفسير.","student":"يكتب تنبؤه ويفسره بحاجة الجسم إلى الأكسجين.","eval":"السؤال (4) ص 24."}]},{"id":"sci6~1_4b_o1","code":"6Eo1","text":"يقوم بقياس معدل التنفس باستخدام أدوات بسيطة بشكل صحيح.","selected":true,"suffix":"","activities":[{"time45":"14 د","time90":"28 د","teacher":"يشرف على ورقة العمل 1-4: عدّ مرات التنفس في الدقيقة أثناء الراحة وبعد الجري دقيقتين وبعد دقيقتين وأربع دقائق أخرى بساعة إيقاف.","student":"يعد أنفاس زميله من حركة صدره ويسجل العدد في الجدول.","eval":"ورقة العمل 1-4."}]},{"id":"sci6~1_4b_o2","code":"6Eo3","text":"يستخدم الجداول والتمثيل الخطي لعرض النتائج.","selected":true,"suffix":"","activities":[{"time45":"8 د","time90":"16 د","teacher":"يوجه تسجيل النتائج في جدول (الزمن، معدل التنفس) ثم رسمها بيانياً خطياً.","student":"يرسم الرسم الخطي لمعدل تنفسه مع الزمن.","eval":"ورقة العمل 1-4 (4)."}]},{"id":"sci6~1_4b_o3","code":"6Eo7","text":"يستخدم النتائج لاستخلاص الاستنتاجات وتقديم المزيد من التنبؤات.","selected":true,"suffix":"","activities":[{"time45":"10 د","time90":"20 د","teacher":"يسأل: متى كان معدل التنفس أقل ومتى كان أعلى؟ وكيف تؤثر الرياضة في معدل التنفس؟ ولماذا؟","student":"يكتب استنتاجه ويفسره.","eval":"ورقة العمل 1-4 (5-6)."}]},{"id":"sci6~1_4b_o4","code":"6Ep6","text":"يحدّد العوامل المرتبطة بمعدل التنفس (مثل اللياقة البدنية).","selected":true,"suffix":"","activities":[{"time45":"10 د","time90":"20 د","teacher":"يطرح سؤال اللاعبين الرياضيين: ما عامل آخر يؤثر في معدل التنفس؟ ويبين أثر اللياقة البدنية.","student":"يقترح عاملاً ويتنبأ بأثره ويفسره.","eval":"ورقة العمل 1-4 (7)."}]},{"id":"sci6~1_4b_o5","code":"6Bh4","text":"يشرح أهمية التنفس الأسرع عند الرياضة لتزويد العضلات بالأكسجين.","selected":true,"suffix":"","activities":[{"time45":"8 د","time90":"16 د","teacher":"يربط بين التنفس والجهاز الدوري: يزداد التنفس فيأخذ الدم مزيداً من الأكسجين إلى العضلات العاملة.","student":"يفسر العلاقة بين معدلي التنفس والنبض.","eval":"ورقة العمل 1-4 (8)."}]}],"prior":"الشهيق والزفير وتبادل الغازات؛ قياس معدل النبض وتأثره بالرياضة؛ رسم الرسوم الخطية وجداول النتائج","warmup":"ماذا يحدث لتنفسك بعد الجري؟ ولماذا؟","resources":"كتاب الطالب (ص 24)، ورقة العمل 1-4 في كتاب النشاط، ساعة إيقاف، ورق رسم بياني ومساطر، أقلام.","strategies":["الأسئلة السابرة","التنبؤ والملاحظة والتفسير (POE)","الاستقصاء الموجه","حل المشكلات","العصف الذهني","الحوار والمناقشة"],"lab":"ورقة العمل 1-4: استقصاء معدل التنفس في ثنائيات، يعد أحد الزميلين أنفاس الآخر بمراقبة صدره (أو بوضع اليد على الضلوع لأبناء الجنس نفسه فقط)، ثم يجري الآخر دقيقتين. يعد الاستقصاء بمكان واسع آمن ويستثنى من لا يسمح له بالجهد البدني.","misconception":"يظن بعض الطلبة أن معدل التنفس ثابت في كل الأوقات. التشخيص: يسأل المعلم: هل تتنفس بالمعدل نفسه وأنت نائم وبعد الجري؟ المعالجة: يقيس الطلبة معدل التنفس أثناء الراحة وبعد الجري ليروا الفرق ويربطوه بحاجة الجسم إلى الأكسجين.","exitTicket":"ما الجهاز الآخر في الجسم الذي يتأثر بممارسة الرياضة مع التنفس؟","homework":"إكمال الرسم الخطي لمعدل التنفس في ورقة العمل 1-4 وكتابة الاستنتاج، مع اقتراح عامل آخر يؤثر في معدل التنفس.","guideAnswers":"<b>ورقة العمل 1-4:</b> (1-3) جدول بالنتائج المحتملة (الراحة نحو 15، وبعد الجري ترتفع ثم تعود إلى الانخفاض). (4) رسم خطي. (5) أ- قبل بدء التمرين. ب- بعد ست دقائق (في جدول النتائج المحتملة). (6) عند ممارسة الرياضة تحتاج أجسامنا إلى مزيد من الأكسجين فنتنفس أسرع. (7) أ- اللياقة البدنية. ب- إذا كنت لائقاً فإن معدل تنفسك لا يزيد كثيراً أثناء الرياضة لأن قلبك أكفأ في ضخ الدم المحمل بالأكسجين إلى العضلات. (8) الجهاز الدوري."},"sci6~1_5":{"course":"sci6","sem":1,"unitNum":1,"unitTitle":"الوحدة الأولى: جسم الإنسان","unitShort":"جسم الإنسان","code":"1-5","title":"الجهاز الهضمي","defaultDuration":45,"objectives":[{"id":"sci6~1_5_o0","code":"6Bh1","text":"يستخدم الأسماء العلمية لأعضاء الجهاز الهضمي (الفم، المريء، المعدة، الأمعاء الدقيقة، الأمعاء الغليظة).","selected":true,"suffix":"","activities":[{"time45":"12 د","time90":"24 د","teacher":"يتتبع مسار الطعام على رسم الجهاز الهضمي: الفم، المريء، المعدة، الأمعاء الدقيقة، الأمعاء الغليظة، ويسمي كل جزء باسمه العلمي.","student":"يسمي الأجزاء على الرسم مستخدماً الكلمات في الصندوق.","eval":"الشكل ص 27 وتمرين 1-5."}]},{"id":"sci6~1_5_o1","code":"6Bh2","text":"يحدّد موضع المعدة والأمعاء في الجسم.","selected":true,"suffix":"","activities":[{"time45":"6 د","time90":"12 د","teacher":"يحدد على الملصق أن المعدة والأمعاء في منطقة البطن، ويستخدم بكرة الخيط لتوضيح طول الأمعاء الدقيقة (نحو 7 أمتار) ومطويّة داخل البطن.","student":"يشير إلى موضعيهما على مخطط الجسم ويقدر طول الأمعاء.","eval":"بكرة خيط (دليل ص 35)."}]},{"id":"sci6~1_5_o2","code":"6Bh3","text":"يصف وظائف أعضاء الجهاز الهضمي (الفم، المريء، المعدة، الأمعاء).","selected":true,"suffix":"","activities":[{"time45":"11 د","time90":"22 د","teacher":"يشرح: الفم يمضغ الطعام ويبدأ الهضم باللعاب، والمريء يدفع الطعام إلى المعدة، والمعدة تمزجه بالعصارة الهضمية، والأمعاء الدقيقة تفتته إلى أجزاء أصغر.","student":"يطابق بطاقات الاسم والصورة والوظيفة لكل جزء.","eval":"ورقة المصادر 1-5."},{"time45":"15 د","time90":"30 د","teacher":"يشرف على صنع نموذج للجهاز الهضمي من زجاجات وأنابيب وأكياس، تمثل كل قطعة جزءاً منه.","student":"يشارك في صنع النموذج وتسمية أجزائه.","eval":"دليل ص 35."}]},{"id":"sci6~1_5_o3","code":"6Bh4","text":"يشرح أهمية الهضم لتزويد الجسم بالطاقة والنمو والتخلص من الطعام غير المهضوم.","selected":true,"suffix":"","activities":[{"time45":"10 د","time90":"20 د","teacher":"يطرح الأسئلة 1-5 ص 26: لماذا نحتاج إلى الطعام؟ ولماذا يجب هضمه؟ وكيف يصل الطعام المهضوم إلى أجزاء الجسم؟","student":"يجيب كتابياً مستخدماً مفردات الدرس.","eval":"الأسئلة 1-5 ص 26."}]},{"id":"sci6~1_5_o4","code":"6Eo1","text":"يقوم بملاحظات متنوعة ذات صلة باستخدام أدوات بسيطة بشكل صحيح (اختبار النشا بمحلول اليود).","selected":true,"suffix":"","activities":[{"time45":"15 د","time90":"30 د","teacher":"يشرف على ورقة العمل 1-5 (مجموعات من 4-5): قطرة يود على الخبز ثم على الخبز الممضوغ ثلاث دقائق، مع احتياطات السلامة.","student":"يضيف اليود بالقطارة ويسجل تغير اللون ويتذوق التغير في طعم الخبز.","eval":"ورقة العمل 1-5."}]},{"id":"sci6~1_5_o5","code":"6Eo7","text":"يستخدم النتائج لاستخلاص الاستنتاجات (هضم النشا يبدأ في الفم).","selected":true,"suffix":"","activities":[{"time45":"8 د","time90":"16 د","teacher":"يوجه سؤال ورقة العمل (5): كيف تغير الخبز في فمك؟ ويربط عدم تغير لون اليود بتحول النشا إلى سكر.","student":"يكتب استنتاجه من النتيجتين ويفسره.","eval":"ورقة العمل 1-5 (3)."}]},{"id":"sci6~1_5_o6","code":"6Ep4","text":"يتنبأ بما سيحدث للخبز مع اليود قبل وبعد المضغ بناءً على المعرفة العلمية.","selected":true,"suffix":"","activities":[{"time45":"5 د","time90":"10 د","teacher":"يطلب كتابة تنبؤ قبل الاستقصاء: ماذا سيحدث لمحلول اليود مع الخبز غير الممضوغ ومع الممضوغ؟","student":"يكتب تنبؤه ويقارنه بالنتيجة.","eval":"ورقة العمل 1-5."}]}],"prior":"الأعضاء وأجهزة الجسم (الدرس 1-1)؛ الفرق بين المريء والقصبة الهوائية؛ أن الطعام مصدر الطاقة والنمو","warmup":"لماذا يحتاج الجسم إلى الطعام؟","resources":"كتاب الطالب (ص 26-27)، الأسئلة 1-5، تمرين 1-5 وورقة المصادر 1-5 وورقة العمل 1-5 في كتاب النشاط، محلول اليود، خبز، أطباق، قطارات (ماصات)، زجاجات وأنابيب وأكياس، بكرة خيط، ملصق الجهاز الهضمي.","strategies":["الأسئلة السابرة","الحوار والمناقشة","المحاكاة البصرية","المقارنة والتصنيف","النمذجة العلمية","حل المشكلات","الاستقصاء الموجه"],"lab":"ورقة العمل 1-5: اختبار النشا بمحلول اليود في الخبز قبل المضغ وبعده، في مجموعات من 4-5 طلبة. السلامة: لا يسقط اليود على الملابس لأنه يسبب بقعاً، ولا يتذوق ولا يبتلع لأنه ضار، وتستعمل قطع خبز جديدة ونظيفة لكل طالب وتلقى بعد الاستقصاء. يمكن للمعلم تجربة مصدر معروف للنشا مثل نشا الذرة لإظهار نتيجة الاختبار.","misconception":"يخلط بعض الطلبة بين المريء والقصبة الهوائية. التشخيص: يطلب المعلم من الطالب تتبع مسار الطعام ومسار الهواء على الرسم. المعالجة: القصبة الهوائية ترتبط بالرئتين، أما المريء فيرتبط بالمعدة، ويبين الرسم ص 27 كل مسار بلون مختلف.","exitTicket":"لماذا لا يتحول لون اليود إلى الأزرق الداكن مع الخبز الممضوغ جيداً؟","homework":"تمرين 1-5 في كتاب النشاط (تسمية الجهاز الهضمي ووظائفه) مع مناقشة الإجابات في الصف.","guideAnswers":"<b>الأسئلة ص 26:</b> (1) من أجل النمو ولتوفير الطاقة لأجسامنا حتى تعمل بشكل صحيح. (2) يجب هضم الطعام جيداً ليسهل على الجسم استخدامه. (3) تمزج المعدة الطعام الممضوغ مع العصارة الهضمية. (4) يهضم الطعام أكثر فيصير جزيئات صغيرة تدخل مجرى الدم ويُتخلص من غير المهضوم. (5) عن طريق الدم.<br><b>تمرين 1-5:</b> المريء: دفع الطعام إلى المعدة؛ المعدة: مزج الطعام مع العصارة الهضمية؛ الفم: مضغ الطعام وبدء الهضم؛ الأمعاء الدقيقة: تفتيت الطعام إلى أجزاء صغيرة جداً. الترتيب: مضغ، دفع إلى المعدة، مزج بالعصارة، تفتيت.<br><b>ورقة العمل 1-5:</b> (1) يتغير لون محلول اليود إلى الأزرق الداكن، فالخبز يحتوي على النشا. (2) نعم، يبدأ طعم الخبز يتحول إلى الحلو. (3) أ- لا يتغير لون اليود. ب- لا نشا في الخبز أو تحول النشا إلى سكر. ج- النشا الموجود في الخبز هُضم في الفم."},"sci6~1_6":{"course":"sci6","sem":1,"unitNum":1,"unitTitle":"الوحدة الأولى: جسم الإنسان","unitShort":"جسم الإنسان","code":"1-6","title":"ما وظيفة الكليتين؟","defaultDuration":45,"objectives":[{"id":"sci6~1_6_o0","code":"6Bh1","text":"يستخدم الأسماء العلمية المتعلقة بالجهاز الإخراجي (الكليتان، الإخراج، البول).","selected":true,"suffix":"","activities":[{"time45":"8 د","time90":"16 د","teacher":"يعرض رسم الجهاز الإخراجي ويسمي الكليتين والبول ويعرّف الإخراج بأنه التخلص من فضلات الجسم.","student":"يكمل جملاً بالكلمات: الإخراج، البول، الفضلات.","eval":"تمرين 1-6."}]},{"id":"sci6~1_6_o1","code":"6Bh2","text":"يحدّد موضع الكليتين في الجسم.","selected":true,"suffix":"","activities":[{"time45":"10 د","time90":"20 د","teacher":"يوضح أنهما في الجزء الخلفي من الجسم أسفل القفص الصدري، ويطلب وضع اليدين على الوركين والإبهامين على الظهر ثم رفعهما حتى تلامس الضلوع لتحديدهما.","student":"يحدد موضع كليتيه على جسمه ويصف شكلهما وحجمهما.","eval":"ص 28."}]},{"id":"sci6~1_6_o2","code":"6Bh3","text":"يصف وظيفة الكليتين الأساسية.","selected":true,"suffix":"","activities":[{"time45":"12 د","time90":"24 د","teacher":"يشرح أن الكليتين تنقيان الدم من فضلات الطعام وتطردان الماء الزائد على شكل بول، ويمر الدم بهما نحو 40 مرة يومياً.","student":"يكتب بكلماته وظيفة الكليتين ويفسر لماذا يقل البول في الطقس الحار.","eval":"الأسئلة 1-3 ص 29."}]},{"id":"sci6~1_6_o3","code":"6Bh4","text":"يشرح أهمية الكليتين وما يحدث عند توقفهما عن العمل.","selected":true,"suffix":"","activities":[{"time45":"12 د","time90":"24 د","teacher":"يناقش توقف الكليتين عن العمل: إمكان إزالة كلية مريضة، وغسيل الكلى بجهاز خاص، وزرع كلية من متبرع.","student":"يذكر ثلاثة أمور يفعلها الأطباء عند توقف الكليتين.","eval":"السؤال (4) ص 29."}]},{"id":"sci6~1_6_o4","code":"6Eo1","text":"يقوم بقياسات ذات صلة باستخدام أدوات بسيطة بشكل صحيح (قياس حجم لتر من الماء).","selected":true,"suffix":"","activities":[{"time45":"15 د","time90":"30 د","teacher":"يشرف على نشاط 1-6: يقدّر الطلبة لتراً واحداً بسكب الماء في وعاء ثم يقيسونه بالمخبار المدرج ويجمعون الأحجام.","student":"يقيس حجم الماء بالمخبار المدرج ويسجل الحجم كل مرة.","eval":"نشاط 1-6 ص 28."}]},{"id":"sci6~1_6_o5","code":"6Ep2","text":"يجمع الأدلة والبيانات لاختبار الأفكار بما فيها التنبؤات (هل التقدير يساوي لتراً).","selected":true,"suffix":"","activities":[{"time45":"5 د","time90":"10 د","teacher":"يطلب مقارنة التقدير بالقياس الفعلي وتحديد مدى قرب التنبؤ من الحجم الصحيح.","student":"يقارن تقديره بالقياس ويقرر هل يدعم الدليل تنبؤه.","eval":"نشاط 1-6."}]},{"id":"sci6~1_6_o6","code":"6Eo3","text":"يستخدم الجداول لعرض النتائج (السوائل التي يتناولها خلال 24 ساعة).","selected":true,"suffix":"","activities":[{"time45":"8 د","time90":"16 د","teacher":"يوزع ورقة العمل 1-6 ويطلب جدولاً بالسوائل وعدد الأكواب التي شربها الطالب خلال 24 ساعة.","student":"يكمل الجدول ويحسب مجموع الأكواب ويقارنه باللتر الواحد.","eval":"ورقة العمل 1-6."}]}],"prior":"الأعضاء وأجهزة الجسم (الدرس 1-1)؛ الدم ينقل الفضلات (الدرس 1-2)؛ القياس بالمخبار المدرج","warmup":"ماذا يحدث لجسمك بعد أن تشرب كمية كبيرة من الماء؟","resources":"كتاب الطالب (ص 28-29)، نشاط 1-6 والأسئلة 1-4، تمرين 1-6 وورقة العمل 1-6 في كتاب النشاط، وعاء كبير، مخبار مدرج، ماء، رسم أو نموذج للجهاز الإخراجي.","strategies":["الأسئلة السابرة","الاستقصاء الموجه","الحوار والمناقشة","حل المشكلات","التنبؤ والملاحظة والتفسير (POE)","التعلم التعاوني","العصف الذهني"],"lab":"نشاط 1-6: تعمل المجموعات (5-6 طلبة) بوعاء بلاستيكي يتسع للترين، وتصب لتراً مقدراً في المخبار المدرج وتسجل الحجم (وعند صغر المخبار تصب على مراحل وتجمع). يجفف الماء المنسكب فوراً لتفادي الانزلاق.","misconception":"يعتقد بعض الطلبة أن الماء في البول يأتي مباشرة مما نشربه لا من الدم. التشخيص: يسأل المعلم: من أين يأتي ماء البول؟ المعالجة: يوضح أن الماء ينتقل من الجهاز الهضمي إلى الدم، وعندما يمر الدم بالكليتين يؤخذ الماء الزائد منه ويشكل الجزء السائل من البول.","exitTicket":"لماذا يجب أن نشرب كمية كافية من الماء؟","homework":"ورقة العمل 1-6 (من أين تحصل على السوائل في جسمك؟) وتمرين 1-6 في كتاب النشاط.","guideAnswers":"<b>الأسئلة ص 29:</b> (1) في الجزء الخلفي من الجسم قليلاً أسفل الضلوع. (2) تقريباً بحجم فأرة الحاسوب. (3) أ- الإخراج. ب- ترشح الكليتان الدم للتخلص من الفضلات التي تخرج على هيئة بول. (4) إزالة كلية (إذا عملت الأخرى جيداً)، أو غسيل الكلى، أو زرع كلية.<br><b>تمرين 1-6:</b> الكليتان زوج من الأعضاء على شكل حبة فاصولياء، وظيفتهما الأساسية الإخراج، وتنقيان الدم من الفضلات وتتحكمان في كمية الماء؛ يتخلص الجسم من فضلات الكلى على هيئة بول؛ يجب شرب كمية كافية من الماء؛ لا تعمل الكليتان بشكل سليم عند المرض؛ جهاز غسيل الكلى يقوم بوظيفتهما.<br><b>ورقة العمل 1-6:</b> (1) قائمة شخصية بالسوائل؛ الأطعمة الرطبة تحتوي سوائل كالفاكهة والخضار والأرز المطبوخ واللحوم والأسماك. (2) أ- الكليتان. ب- معظم الطلبة يشربون أكثر من لتر. ج- يستهلكها الجسم."},"sci6~1_7":{"course":"sci6","sem":1,"unitNum":1,"unitTitle":"الوحدة الأولى: جسم الإنسان","unitShort":"جسم الإنسان","code":"1-7","title":"ما وظيفة الدماغ؟","defaultDuration":45,"objectives":[{"id":"sci6~1_7_o0","code":"6Bh1","text":"يستخدم الأسماء العلمية للدماغ وأجزائه (المخ، المخيخ، جذع الدماغ) والجهاز العصبي والأعصاب.","selected":true,"suffix":"","activities":[{"time45":"12 د","time90":"24 د","teacher":"يعرض نموذجاً أو ملصقاً للدماغ ويشير إلى نصفي الكرة والأجزاء الثلاثة: المخ والمخيخ وجذع الدماغ، ويطلب تسميتها وتلوينها (أصفر، أحمر، أزرق).","student":"يسمي الأجزاء على الرسم ويلونها.","eval":"الشكل ص 30."}]},{"id":"sci6~1_7_o1","code":"6Bh2","text":"يحدّد موضع الدماغ في الجسم (داخل الجمجمة) وموضع أجزائه.","selected":true,"suffix":"","activities":[{"time45":"8 د","time90":"16 د","teacher":"يبين أن الدماغ داخل الجمجمة، ويطلب ضم القبضتين لتمثيل نصفي الكرة بحجم الدماغ تقريباً، والمخيخ في الخلف والجذع في القاعدة.","student":"يضم قبضتيه ويحدد مواضع الأجزاء على الرسم.","eval":"ص 30."}]},{"id":"sci6~1_7_o2","code":"6Bh3","text":"يصف وظائف الدماغ وأجزائه.","selected":true,"suffix":"","activities":[{"time45":"12 د","time90":"24 د","teacher":"يشرح وظائف المخ (التفكير والحواس والذاكرة واللغة والحركة الإرادية) والمخيخ (التوازن) وجذع الدماغ (التنفس ودقات القلب وطرفة العين).","student":"يكتب وظيفتين لكل جزء بجانب اسمه.","eval":"الشكل ص 30."}]},{"id":"sci6~1_7_o3","code":"6Bh4","text":"يشرح أهمية الدماغ وحمايته وما يحدث عند تضرره.","selected":true,"suffix":"","activities":[{"time45":"12 د","time90":"24 د","teacher":"يناقش: كيف يحمى الدماغ؟ ولماذا حمايته بالغة الأهمية؟ وأن الدماغ لا يصلح نفسه عادة، ويذكر أسباب تضرره.","student":"يجيب عن السؤال (1) و(3) ص 31 كتابياً.","eval":"الأسئلة ص 31."}]},{"id":"sci6~1_7_o4","code":"6Eo4","text":"يعقد مقارنات (بين كتل أجسام الكائنات الحية وكتل أدمغتها).","selected":true,"suffix":"","activities":[{"time45":"8 د","time90":"16 د","teacher":"يوزع ورقة العمل 1-7 ويطلب ترتيب الكائنات تنازلياً حسب كتلة الجسم ثم حسب كتلة الدماغ ومقارنة القائمتين.","student":"يرتب القائمتين ويقارن بينهما.","eval":"ورقة العمل 1-7 (1-3)."}]},{"id":"sci6~1_7_o5","code":"6Eo6","text":"يحدّد الأنماط في النتائج والنتائج التي لا تبدو ملائمة للنمط.","selected":true,"suffix":"","activities":[{"time45":"8 د","time90":"16 د","teacher":"يسأل عن النمط العام وعن الكائن الذي لا يتبعه، ثم يطرح التحدي: أي كائن له أكبر دماغ نسبة إلى جسمه؟","student":"يصف النمط ويحدد الشاذ ويحسب النسبة.","eval":"ورقة العمل 1-7 (3) والتحدي."}]}],"prior":"الجمجمة تحمي الدماغ (الصف الرابع والدرس 1-1)؛ الأعضاء وأجهزة الجسم؛ الدماغ يتحكم في التنفس ودقات القلب (الدروس السابقة)","warmup":"أي عضو في الجسم يشبه ملمسه العصيدة؟","resources":"كتاب الطالب (ص 30-31)، الأسئلة 1-3 والتحدي، تمرين 1-7 وورقة العمل 1-7 في كتاب النشاط، أكياس عصيدة باردة ذاتية الإغلاق، رسومات بخطوط بسيطة للدماغ، أقلام تلوين، نموذج أو ملصق للدماغ، ورق مقوى.","strategies":["الأسئلة السابرة","الحوار والمناقشة","المحاكاة البصرية","حل المشكلات","العصف الذهني","المقارنة والتصنيف"],"lab":"أكياس العصيدة: تعد قبل الحصة بيوم من دقيق الشوفان في ثلاثة أو أربعة أكياس ذاتية الإغلاق باردة، ويتأكد المعلم من إحكام إغلاقها قبل تمريرها. ويطبق نشاط ورقة الصحيفة بطيها أو كرمشتها داخل مربع صغير بحجم علبة القرص.","misconception":"يظن بعض الطلبة أن الدماغ الأكبر يعني ذكاءً أكبر. التشخيص: يسأل المعلم: هل الفيل أذكى من الإنسان لأن دماغه أكبر؟ المعالجة: يوضح أن حجم الدماغ لا علاقة له بالذكاء، فدماغ أينشتاين كان أصغر قليلاً من المعتاد وأدمغة البشر البدائيين أكبر من دماغنا.","exitTicket":"ما الذي يحمي الدماغ، وما الذي يتحكم فيه جذع الدماغ؟","homework":"تمرين 1-7 في كتاب النشاط مع مراجعة الأقران لإجابات بعضهم البعض (توجيه الدليل).","guideAnswers":"<b>الأسئلة ص 31:</b> (1) أ- بواسطة الجمجمة. ب- لأنه يتحكم في كل ما نقوم به وإن أصيب لم تعمل أجسادنا بصورة سليمة. (2) أ- يرسل الدماغ رسائل ويتلقاها عن طريق الأعصاب. ب- ليستجيب الجسم بسرعة حفاظاً على سلامتك. (3) يسمح لك بالحركة والتقاط الهاتف وتحديد الرقم ورؤية ما تفعل وسماع الرنين وصوت صديقك والتحدث إليه. <b>التحدي:</b> الارتجاج تلف يلحق بالدماغ بسبب ضربة قوية على الرأس فيفقد الوعي أو يشعر بصداع شديد.<br><b>تمرين 1-7:</b> الجهاز العصبي، والأعصاب؛ التنفس ودقات القلب؛ الدماغ لا يصلح نفسه إذا أصيب إصابة خطيرة فقد يفقد القدرة على الكلام.<br><b>ورقة العمل 1-7:</b> ترتيب الكتل: (الجسم) الفيل، الدولفين، الإنسان، الكنغر، البابون، الراكون، القطة، البومة؛ (الدماغ) الفيل، الدولفين، الإنسان، البابون، الكنغر، الراكون، القطة، البومة؛ النمط: كلما زادت كتلة الجسم زادت كتلة الدماغ؛ الكائن الذي لا يتبعه: البابون. التحدي: الإنسان (كتلة الدماغ ÷ كتلة الجسم)."},"sci6~1_8":{"course":"sci6","sem":1,"unitNum":1,"unitTitle":"الوحدة الأولى: جسم الإنسان","unitShort":"جسم الإنسان","code":"1-8","title":"تحقق من تقدمك","defaultDuration":45,"objectives":[{"id":"sci6~1_8_o0","code":"6Bh1-2","text":"يسمّي أعضاء الجسم الرئيسية ويحدّد مواضعها (الدماغ، القلب، الرئتان، الكليتان، المعدة، الأمعاء، الكبد).","selected":true,"suffix":"","activities":[{"time45":"12 د","time90":"24 د","teacher":"يعرض رسومات الأعضاء في السؤال (5) ص 33 ويطلب تسميتها وتحديد موضع كل منها ومن يحميها.","student":"يسمي الأعضاء ويحدد مواضعها ويذكر ما يحمي كل عضو.","eval":"السؤال (5) ص 33."}]},{"id":"sci6~1_8_o1","code":"6Bh3","text":"يصف الوظائف الأساسية لأعضاء الجسم الرئيسية.","selected":true,"suffix":"","activities":[{"time45":"20 د","time90":"40 د","teacher":"يوجه الأسئلة 1-4 ص 32-33: مطابقة الأعضاء بوظائفها، وصح أم خطأ، وإكمال جمل الهضم، وترتيب مراحل الهضم.","student":"يجيب عن الأسئلة ويصحح العبارات الخاطئة.","eval":"الأسئلة 1-4 ص 32-33."},{"time45":"10 د","time90":"20 د","teacher":"يطرح السؤال (6) عن غازي التنفس ويوجه المراجعة اللغوية في كتاب النشاط.","student":"يكمل جمل المراجعة اللغوية بالمصطلحات.","eval":"المراجعة اللغوية."}]},{"id":"sci6~1_8_o2","code":"6Bh4","text":"يشرح أهمية وظائف الأعضاء الرئيسية وترابط أجهزة الجسم.","selected":true,"suffix":"","activities":[{"time45":"8 د","time90":"16 د","teacher":"يوزع ورقة العمل 1-8 لمراجعة الأعضاء والأجهزة، ويناقش كيف تعمل الأجهزة معاً: الدوري والتنفسي والهضمي والإخراجي والعصبي.","student":"يكمل جمل ورقة العمل ويربط كل جهاز بعمله.","eval":"ورقة العمل 1-8."}]}],"prior":"وظائف الأعضاء الرئيسية (الدروس 1-1 إلى 1-7)؛ مراحل الهضم؛ مصطلحات الجهاز الدوري والتنفسي والإخراجي والعصبي","warmup":"أي عضو يضخ الدم إلى جميع أجزاء الجسم؟","resources":"كتاب الطالب (ص 32-33)، أسئلة تحقق من تقدمك، المراجعة اللغوية وورقة العمل 1-8 في كتاب النشاط، بطاقات الأعضاء، رسومات الأعضاء.","strategies":["الأسئلة السابرة","المقارنة والتصنيف","الحوار والمناقشة","حل المشكلات","التعلم التعاوني"],"lab":"لا توجد تجربة عملية في هذا الموضوع، وتنفذ الأنشطة بالأسئلة وبطاقات الأعضاء وأوراق العمل.","misconception":"يخلط بعض الطلبة بين النبض ودقات القلب وبين الدم المؤكسج وغير المؤكسج. التشخيص: يظهر في تصحيح العبارات الخاطئة في السؤال (2). المعالجة: تراجع مفاهيم الدروس 1-2 و1-3 مع الرسم، ويؤكد أن القلب يضخ الدم لا الهواء.","exitTicket":"اذكر وظيفة كل من الكليتين والدماغ والرئتين.","homework":"إكمال المراجعة اللغوية وورقة العمل 1-8 في كتاب النشاط، ومراجعة أسئلة «تحقق من تقدمك» ص 32-33.","guideAnswers":"<b>(1)</b> المعدة والأمعاء - الهضم، الرئتان - التنفس، الكليتان - الإخراج، الدماغ - التحكم، القلب - ضخ الدم. <b>(2)</b> أ- خطأ، يضخ القلب الدم إلى جميع أجزاء الجسم. ب- صحيح. ج- خطأ، يوضح معدل نبضك مدى سرعة دقات قلبك. د- صحيح. ه- خطأ، يحمل الدم ثاني أكسيد الكربون إلى الرئتين. <b>(3)</b> أ- المريء. ب- الأمعاء. ج- المعدة. د- الأمعاء. ه- الفم. <b>(4)</b> التسلسل: ه، أ، ج، ب، د. <b>(5)</b> أ- الرئتان والدماغ والكليتان. ب- الكليتان. ج- البول. د- الدماغ. ه- يتحكم في التنفس. و- لعب كرة القدم يزيد من معدل التنفس. ز- بالضلوع. ح- بالجمجمة. <b>(6)</b> أ- ثاني أكسيد الكربون. ب- الأكسجين."},"sci6~2_1":{"course":"sci6","sem":1,"unitNum":2,"unitTitle":"الوحدة الثانية: الكائنات الحية في البيئة","unitShort":"الكائنات الحية في البيئة","code":"2-1","title":"السلاسل الغذائية في الموطن الطبيعي المحلي","defaultDuration":45,"objectives":[{"id":"sci6~2_1_o0","code":"6Be3","text":"يعرف أنه يمكن استخدام السلاسل الغذائية لتمثيل العلاقات الغذائية في المواطن الطبيعية، ويعرض ذلك بالنص والمخططات.","selected":true,"suffix":"","activities":[{"time45":"12 د","time90":"24 د","teacher":"يعرض مزرعة محمد ص 34 ويقدم مفردات الموطن الطبيعي والعلاقة الغذائية والسلسلة الغذائية، ويوضح أن السهم يعني «تتغذى عليها».","student":"يقرأ المفردات ويصف العلاقات الغذائية في المزرعة بجمل قصيرة.","eval":"الشكل والنص ص 34."},{"time45":"10 د","time90":"20 د","teacher":"يكتب سلسلة السبانخ واليرقة على السبورة، ويطلب التعبير عن السلسلتين 1 و2 بكلمتين يفصل بينهما سهم.","student":"يكتب السلسلتين مستعملاً السهم ويقرؤهما بصيغة «تتغذى عليه».","eval":"الشكلان 1 و2 ص 34."}]},{"id":"sci6~2_1_o1","code":"6Be6","text":"يستكشف ويكوّن سلاسل غذائية في مواطن طبيعية محلية.","selected":true,"suffix":"","activities":[{"time45":"10 د","time90":"20 د","teacher":"يوزع بطاقات صور لنباتات وحيوانات المزرعة ويطلب تكوين سلسلتين غذائيتين من نبات وحيوان (السؤال 4).","student":"يرتب البطاقات بسهم ويكتب السلسلة في دفتره.","eval":"السؤال 4 ص 35."},{"time45":"14 د","time90":"28 د","teacher":"يشرف على نشاط 2-1 في الموطن المختار ويوجه رسم ثلاث سلاسل غذائية مما لاحظوه.","student":"يسجل نباتات الموطن وحيواناته ويرسم ثلاث سلاسل غذائية.","eval":"نشاط 2-1 ص 35."}]},{"id":"sci6~2_1_o2","code":"6Eo1","text":"يقوم بملاحظات متنوعة ذات صلة باستخدام أدوات بسيطة بشكل صحيح.","selected":true,"suffix":"","activities":[{"time45":"14 د","time90":"28 د","teacher":"يوجه الطلبة إلى البحث تحت أوراق الشجيرات وبين الأوراق الميتة، وإلى النظر في الأشجار بحثاً عن الطيور.","student":"يلاحظ ويسجل في قائمة أسماء النباتات والحيوانات التي يراها.","eval":"نشاط 2-1 ص 35."}]}],"prior":"الموطن الطبيعي والكائنات التي تعيش فيه (الصف الرابع)؛ السلسلة الغذائية البسيطة (الوحدة 2 للصف الرابع)؛ الحيوانات تحتاج إلى الغذاء","warmup":"ما الأطعمة التي ذكرتها ومصدرها نبات؟","resources":"كتاب الطالب (ص 34-35)، نشاط 2-1، تمرين 2-1 في كتاب النشاط، بطاقات صور لنباتات وحيوانات، كتب مرجعية عن الحيوانات والنباتات، دفتر ملاحظات وقلم.","strategies":["العصف الذهني","الحوار والمناقشة","التعلم بالنمذجة","التعلم التعاوني"],"lab":"نشاط 2-1: دراسة موطن طبيعي محلي. يختار المعلم مسبقاً موطناً مناسباً في فناء المدرسة أو قربها (أشجار وأعشاب ونباتات أخرى)، ويتأكد من قدرته على تسمية أنواعه. يرافق الطلبة شخص بالغ عند الابتعاد عن فناء المدرسة، ويبقى الطلبة ضمن المنطقة المحددة. إن لم يتوفر موطن قريب يُستعمل موطن من بيئتهم أو صور بديلة.","misconception":"يظن بعض الطلبة أن النباتات تعتمد على الإنسان لأنه يزرعها. التشخيص: يسأل المعلم من يعتمد على من في المزرعة؟ المعالجة: يتتبع مع الطلبة غذاء الإنسان والحيوان ويبين أن الإنسان والحيوانات يعتمدون على النباتات وأن النباتات تصنع غذاءها بنفسها، وهو مدخل الدرس 2-2.","exitTicket":"ارسم سلسلة غذائية من موطن درسته: نبات ثم حيوانان.","homework":"إكمال تمرين 2-1 في كتاب النشاط (تحديد الموطن في الصورة ورسم خمس سلاسل غذائية)، ويتبادل الطلبة الكتب في الحصة التالية للتحقق من الإجابات.","guideAnswers":"<b>نشاط 2-1:</b> (1-3) تعتمد على الموطن الذي يدرسه الطلبة. (4) ذرة ← الحشرة ثاقبة الذرة ← سحلية؛ ورقة ← يرقة ← طائر.<br><b>تمرين 2-1:</b> (1) حديقة. (2) مانجو ← طائر؛ مانجو ← يرقة أو دودة؛ أزهار ← حشرات؛ أزهار ← نحلة؛ العشب ← نملة. (3) توفر شجرة المانجو مكاناً للطيور لبناء أعشاشها، وتوفر الأزهار حبوب اللقاح للنحل.<br><b>تحدث عن:</b> لو لم توجد نباتات لماتت الحيوانات جميعها في النهاية."},"sci6~2_2":{"course":"sci6","sem":1,"unitNum":2,"unitTitle":"الوحدة الثانية: الكائنات الحية في البيئة","unitShort":"الكائنات الحية في البيئة","code":"2-2","title":"السلاسل الغذائية تبدأ بالنباتات: أ. المنتجة والمستهلكة","defaultDuration":45,"objectives":[{"id":"sci6~2_2_o0","code":"6Be4","text":"يعرف أن السلاسل الغذائية تبدأ بالنباتات (الكائنات المنتجة) التي تستخدم الطاقة من الشمس.","selected":true,"suffix":"","activities":[{"time45":"12 د","time90":"24 د","teacher":"يربط حاجة الإنسان والحيوان إلى الطاقة بالغذاء، ويتتبع مصدر الأطعمة التي ذكرها الطلبة إلى أن يصل إلى النبات.","student":"يتتبع مصدر طعامه خطوة خطوة: خبز ← قمح، لحم ← حيوان ← نبات.","eval":"قائمة الطعام والشكل ص 36."},{"time45":"8 د","time90":"16 د","teacher":"يطلب ترتيب سلسلتي السؤال 1 ص 36 ويؤكد أن كل سلسلة تبدأ بنبات مهما كان الموطن.","student":"يرتب الكائنات في كل سلسلة ويبدأ بالنبات.","eval":"السؤال 1 ص 36."}]},{"id":"sci6~2_2_o1","code":"6Be5","text":"يعرف ويفهم المصطلحين «كائن منتج» و«كائن مستهلك».","selected":true,"suffix":"","activities":[{"time45":"12 د","time90":"24 د","teacher":"يشرح أن النبات ينتج غذاءه بنفسه فيسمى منتجاً، وأن الإنسان والحيوان يعتمدان على النباتات فيسميان مستهلكين.","student":"يميز المنتج من المستهلك في السلسلتين 1 و2 ويفسر سبب التسمية.","eval":"السلسلتان 1 و2 ص 36."},{"time45":"10 د","time90":"20 د","teacher":"يوزع تمرين 2-2 ويوجه الطلبة إلى تحديد المنتج والمستهلكين في الصورة ورسم سلسلة غذائية منها.","student":"يحدد المنتج والمستهلكين ويرسم السلسلة.","eval":"تمرين 2-2 (4 و5)."}]},{"id":"sci6~2_2_o2","code":"6Eo6","text":"يحدّد الأنماط في النتائج والنتائج التي لا تبدو ملائمة للنمط.","selected":true,"suffix":"","activities":[{"time45":"8 د","time90":"16 د","teacher":"يطلب مقارنة السلاسل التي كوّنوها في الدرس السابق وفي هذا الدرس وتحديد ما يتشابه فيها.","student":"يلاحظ أن كل سلسلة تبدأ بنبات ثم مستهلك.","eval":"السلاسل المرسومة."}]}],"prior":"الموطن الطبيعي والسلسلة الغذائية (الدرس 2-1)؛ السهم يعني «تتغذى عليه»؛ ما تعلمه الطلبة عن غذاء النباتات والحيوانات في الصف الرابع","warmup":"من أين نحصل على الطاقة لنتحرك ونتنفس؟","resources":"كتاب الطالب (ص 36)، تمرين 2-2 في كتاب النشاط، بطاقات أسماء الكائنات وأسهم، سبورة وأقلام ملونة.","strategies":["العصف الذهني","الحوار والمناقشة","التعلم بالنمذجة","التعلم التعاوني","التعلم الفردي"],"lab":"لا يوجد نشاط عملي في هذه الورقة. تُجهّز الشتلات المطلوبة لنشاط 2-2 مسبقاً قبل ورقة (ب) بأسبوع على الأقل لتظهر النتائج.","misconception":"يظن بعض الطلبة أن النباتات تعتمد على الإنسان لأنه يزرعها ويسقيها. التشخيص: يسأل المعلم من يصنع الغذاء، النبات أم الإنسان؟ المعالجة: يوضح أن الإنسان والحيوان يعتمدان على النباتات في غذائهما، وأن النبات يصنع غذاءه بنفسه.","exitTicket":"لماذا تبدأ كل سلسلة غذائية بنبات؟","homework":"إكمال السؤالين 4 و5 من تمرين 2-2 في كتاب النشاط (إن لم يكتملا) وكتابة سلسلتين غذائيتين من أطعمة وجبة اليوم، ثم تبادل الدفاتر لتصحيحها في الحصة التالية.","guideAnswers":"<b>السؤال 1 ص 36:</b> (أ) سبانخ ← يرقة ← طائر. (ب) عشب ← خروف ← إنسان.<br><b>تمرين 2-2:</b> (4) أ: 3 كائن منتج، ب: 4 كائن مستهلك، ج: 5 كائن مستهلك. (5) شجرة ← حمار وحشي ← أسد."},"sci6~2_2b":{"course":"sci6","sem":1,"unitNum":2,"unitTitle":"الوحدة الثانية: الكائنات الحية في البيئة","unitShort":"الكائنات الحية في البيئة","code":"2-2","title":"السلاسل الغذائية تبدأ بالنباتات: ب. كيف تصنع النباتات الغذاء؟","defaultDuration":45,"objectives":[{"id":"sci6~2_2b_o0","code":"6Be4","text":"يعرف أن النباتات تصنع غذاءها في أوراقها مستخدمة الطاقة من الشمس والماء وثاني أكسيد الكربون وتطلق الأكسجين.","selected":true,"suffix":"","activities":[{"time45":"12 د","time90":"24 د","teacher":"يعرض الشكل ص 37 ويشرح أن الورقة تصنع الغذاء من ضوء الشمس والماء وثاني أكسيد الكربون، وأن الأكسجين يطلقه النبات إلى الهواء.","student":"يصف بكلماته ما يدخل النبات وما يخرج منه ويقرأ الشكل.","eval":"الشكل ص 37."},{"time45":"10 د","time90":"20 د","teacher":"يناقش «تحدث عن»: ماذا يحدث للأكسجين الذي تنتجه النباتات؟ ويربطه بتنفس الإنسان والحيوان وبإخراج ثاني أكسيد الكربون.","student":"يفسر أن الإنسان والحيوان يتنفسان الأكسجين ويخرجان ثاني أكسيد الكربون.","eval":"تحدث عن ص 37."}]},{"id":"sci6~2_2b_o1","code":"6Ep6","text":"يحدّد العوامل المرتبطة بموقف محدد (الماء وضوء الشمس).","selected":true,"suffix":"","activities":[{"time45":"13 د","time90":"26 د","teacher":"يوجه تخطيط الاستقصاءين: تغيير عامل واحد فقط (الماء أو ضوء الشمس) وإبقاء بقية العوامل ثابتة.","student":"يحدد العامل المؤثر في كل استقصاء وما يبقى ثابتاً.","eval":"نشاط 2-2 السؤال 1 ص 37."},{"time45":"10 د","time90":"20 د","teacher":"يوجه تمرين 2-2 (الأسئلة 1-3): ماذا يمثل السهمان في الصورة؟ وما العامل الثالث الذي تحتاجه الشجرة؟","student":"يجيب عن الأسئلة كتابياً.","eval":"تمرين 2-2 (1-3)."}]},{"id":"sci6~2_2b_o2","code":"6Ep5","text":"يقترح ويقيّم تفسيرات للتنبؤات باستخدام المعرفة العلمية والفهم، ويوصلها للآخرين بوضوح.","selected":true,"suffix":"","activities":[{"time45":"5 د","time90":"10 د","teacher":"يطلب كتابة تنبؤ لكل استقصاء مع تفسير مبني على ما يعرفونه عن حاجة النبات للماء والضوء.","student":"يكتب تنبؤه وتفسيره ويعرضه على المجموعة.","eval":"السؤالان 2 و3 ص 37."},{"time45":"10 د","time90":"20 د","teacher":"يطلب مقارنة النتائج بالتنبؤات وتقييم الدليل: هل يدعم تنبؤاتهم؟ ولماذا؟","student":"يقارن نتائج النباتات بتنبؤه ويفسر.","eval":"السؤال 3 ص 37."}]}],"prior":"الكائن المنتج والكائن المستهلك (الورقة السابقة)؛ الاستقصاء العادل: تغيير عامل واحد في كل مرة (الصف الرابع)؛ حاجة النباتات إلى الماء والضوء","warmup":"ما الأشياء التي تحتاجها النبتة لتنمو؟","resources":"كتاب الطالب (ص 37)، نشاط 2-2، تمرين 2-2 في كتاب النشاط، أربعة أصص زرع لكل مجموعة، بذور صالحة سريعة النمو (فاصوليا أو خردل)، تربة، ماء، ملصقات.","strategies":["العصف الذهني","الحوار والمناقشة","التعلم التعاوني","الأسئلة السابرة"],"lab":"نشاط 2-2: استقصاء ما تحتاجه النباتات. يحضّر المعلم الشتلات مسبقاً لأن النتائج تحتاج أسبوعاً أو اثنين، ويفضّل أن تضم المجموعة أربعة طلبة. أربعة أصص لكل مجموعة: اثنان للماء (يُروى أحدهما فقط)، واثنان للضوء (أحدهما في الشمس والآخر في الظلام). تبقى التربة رطبة دون إغراقها بالماء، وتُترك الأصص أسبوعاً على الأقل ليظهر الفرق.","misconception":"يظن بعض الطلبة أن النباتات تتغذى بالتربة وحدها أو أنها تعتمد على من يزرعها. التشخيص: يسأل المعلم من أين تحصل النبتة على غذائها؟ المعالجة: يبين الشكل ص 37 أن الورقة تصنع الغذاء من الضوء والماء وثاني أكسيد الكربون، وأن الجذور تمتص الماء والمغذيات فقط.","exitTicket":"ماذا تستنتج من اصفرار أوراق النبتة التي بقيت في الظلام؟","homework":"كتابة فقرة قصيرة تشرح ما يحتاجه النبات لصنع غذائه، وإكمال الأسئلة 1-3 من تمرين 2-2 في كتاب النشاط إن لم تكتمل.","guideAnswers":"<b>نشاط 2-2:</b> (1) العامل المؤثر هو الماء في الاستقصاء الأول وضوء الشمس في الاستقصاء الثاني. (2) إجابات الطلبة. (3) ذبلت وماتت الشتلة التي لم تُروَ واستمرت المرواة في النمو؛ والشتلة في الظلام لم تنمُ واصفرّت أوراقها، والتي في الشمس استمرت في النمو وظلت خضراء، لأن النبات يحتاج إلى الماء والضوء.<br><b>تحدث عن:</b> نتنفس الأكسجين وكذلك كل الحيوانات.<br><b>تمرين 2-2:</b> (1) ضوء الشمس. (2) ثاني أكسيد الكربون من الهواء. (3) الماء."},"sci6~2_3":{"course":"sci6","sem":1,"unitNum":2,"unitTitle":"الوحدة الثانية: الكائنات الحية في البيئة","unitShort":"الكائنات الحية في البيئة","code":"2-3","title":"الكائنات الحية المستهلكة في السلاسل الغذائية","defaultDuration":45,"objectives":[{"id":"sci6~2_3_o0","code":"6Be5","text":"يعرف ويفهم المصطلحات «كائن منتج» و«كائن مستهلك» و«مفترس» و«فريسة».","selected":true,"suffix":"","activities":[{"time45":"12 د","time90":"24 د","teacher":"يعرض صور الضفدع والبومة والعنكبوت ص 38 ويعرّف المفترس بأنه الحيوان الذي يتغذى على حيوانات أخرى، والفريسة بأنها ما يصطاده.","student":"يحدد المفترس والفريسة في كل صورة ويذكر الفرق بينهما.","eval":"الصور ص 38."},{"time45":"7 د","time90":"14 د","teacher":"يوزع بطاقات المفترسات والفرائس الخمسة ويطلب وصل كل مفترس بفريسته (السؤال 1 ص 39).","student":"يصل كل مفترس بفريسته ويقرأ الزوج بجملة.","eval":"السؤال 1 ص 39."}]},{"id":"sci6~2_3_o1","code":"6Be3","text":"يعرف أنه يمكن استخدام السلاسل الغذائية لتمثيل العلاقات الغذائية في المواطن الطبيعية.","selected":true,"suffix":"","activities":[{"time45":"10 د","time90":"20 د","teacher":"يعرض سلسلة الجراد والسحلية والصقر ص 38 ويوضح أن السحلية مفترس وفريسة معاً.","student":"يقرأ السلسلة ويحدد المفترسين وفريسة كل منهما.","eval":"السلسلة ص 38."},{"time45":"10 د","time90":"20 د","teacher":"يوجه تمرين 2-3: تحديد المنتجات وآكلات النبات والمفترسات من مخطط السافانا ورسم سلاسل منه.","student":"يحدد الكائنات ويرسم السلاسل من المخطط.","eval":"تمرين 2-3."}]},{"id":"sci6~2_3_o2","code":"6Be6","text":"يستكشف ويكوّن سلاسل غذائية في مواطن طبيعية.","selected":true,"suffix":"","activities":[{"time45":"8 د","time90":"16 د","teacher":"يطلب تذكر الموطن المحلي وذكر مفترسين وفريسة كل منهما، ثم رسم سلسلة تبدأ بكائن منتج (السؤالان 2 و3).","student":"يذكر مفترسين من موطنه ويرسم سلسلة من منتج وفريسة ومفترس.","eval":"السؤالان 2 و3 ص 39."}]},{"id":"sci6~2_3_o3","code":"6Eo6","text":"يحدّد الأنماط في النتائج والنتائج التي لا تبدو ملائمة للنمط.","selected":true,"suffix":"","activities":[{"time45":"12 د","time90":"24 د","teacher":"يطلب المقارنة بين السلاسل المرسومة وتحديد النمط المشترك (السؤال 4)، ثم يطرح سؤال التحدي عن النبات آكل الحشرات بوصفه حالة غير ملائمة للنمط.","student":"يحدد النمط ويفسر لماذا يصطاد النبات آكل الحشرات الذباب.","eval":"السؤال 4 والتحدي ص 39."}]}],"prior":"الكائن المنتج والكائن المستهلك (الدرس 2-2)؛ رسم السلسلة الغذائية بالأسهم (الدرس 2-1)؛ الحيوانات تتغذى على النباتات أو على حيوانات أخرى","warmup":"اذكر حيواناً يأكل حيواناً آخر، وما يأكله.","resources":"كتاب الطالب (ص 38-39)، تمرين 2-3 وورقة العمل 2-3 في كتاب النشاط، صور للحيوانات والنباتات والمواطن، بطاقات المفترسات والفرائس.","strategies":["العصف الذهني","الحوار والمناقشة","التعلم بالنمذجة","التعلم التعاوني","التعلم الفردي"],"lab":"لا يوجد نشاط عملي. تُحضر صور الحيوانات والنباتات مسبقاً من كتب المكتبة.","misconception":"يظن بعض الطلبة أن الحيوان الأعلى في السلسلة يأكل كل ما دونه وأن أعداد المفترسات تساوي أعداد فرائسها. التشخيص: يسأل المعلم هل يأكل الأسد كل الحمير الوحشية؟ المعالجة: يبين أن المفترس يأكل بعضاً منها فقط، وأن الفرائس أكثر عدداً بكثير، وأن كل سلسلة تبدأ بالمنتج وإن غاب ذكره في الحديث.","exitTicket":"عرّف المفترس وأعطِ مثالاً عليه وعلى فريسته.","homework":"إكمال تمرين 2-3 في كتاب النشاط، ويتبادل الطلبة الكتب في الحصة التالية لتقييم الواجب المنزلي ثم تُستعرض الإجابات في الصف.","guideAnswers":"<b>الأسئلة ص 39:</b> (1) فهد وظبي؛ دب قطبي وفقمة؛ عنكبوت وذبابة؛ نورس وسمكة؛ ضفدع وذبابة. (2) تعتمد على إجابات الطلبة. (3) مثال: عوالق ← سمكة ← نورس. (4) تبدأ جميعها بكائن منتج ثم مستهلك. <b>التحدي:</b> يحصل على المغذيات من الحشرات بدلاً من التربة الفقيرة، مثل نبات الإبريق والدروسيرا.<br><b>تمرين 2-3:</b> (1) شجرة الأكاسيا والحشائش. (2) أربعة من: النمل الأبيض وقرد البابون والحمار الوحشي وغزال الإمبالا. (3) الأسد والضبع والنمر. (4) حشائش ← غزال الإمبالا ← أسد. (5) حشائش ← حمار وحشي ← ضبع ← أسد.<br><b>ورقة العمل 2-3:</b> النباتات تصنع الغذاء بنفسها فهي منتجة، والغاز الناتج الأكسجين، والحيوانات مستهلكة، والأسد مفترس والحمار الوحشي فريسة."},"sci6~2_4":{"course":"sci6","sem":1,"unitNum":2,"unitTitle":"الوحدة الثانية: الكائنات الحية في البيئة","unitShort":"الكائنات الحية في البيئة","code":"2-4","title":"السلاسل الغذائية في المواطن الطبيعية المختلفة","defaultDuration":45,"objectives":[{"id":"sci6~2_4_o0","code":"6Be3","text":"يعرف أنه يمكن استخدام السلاسل الغذائية لتمثيل العلاقات الغذائية في المواطن الطبيعية المختلفة.","selected":true,"suffix":"","activities":[{"time45":"12 د","time90":"24 د","teacher":"يعرض سلاسل السافانا ص 40 ويناقش: من المنتج؟ ومن المستهلك؟ ومن المفترس وفريسته؟ وماذا يأكل كل حيوان؟","student":"يجيب عن الأسئلة ويكتب سلسلتين من السافانا.","eval":"السلاسل ص 40."},{"time45":"10 د","time90":"20 د","teacher":"يوجه رسم سلسلتين من المحيط (مفترس واحد ثم مفترسان) ويصحح اتجاه الأسهم.","student":"يرسم سلاسل المحيط ويقرؤها.","eval":"السؤال 3 ص 41."}]},{"id":"sci6~2_4_o1","code":"6Be5","text":"يعرف ويفهم المصطلحات «كائن منتج» و«كائن مستهلك» و«مفترس» و«فريسة» في مواطن مختلفة.","selected":true,"suffix":"","activities":[{"time45":"10 د","time90":"20 د","teacher":"يطلب من الطلبة تصنيف كائنات السافانا والمحيط والصحراء إلى منتجات ومستهلكات ومفترسات وفرائس.","student":"يصنف الكائنات في جدول من أربعة أعمدة.","eval":"جدول التصنيف."}]},{"id":"sci6~2_4_o2","code":"6Be6","text":"يستكشف ويكوّن سلاسل غذائية في مواطن طبيعية مختلفة.","selected":true,"suffix":"","activities":[{"time45":"12 د","time90":"24 د","teacher":"يعرض صور الصحراء وتحت سطح الماء والتندرا والغابة ويسأل: هل تنمو النباتات نفسها وتعيش الحيوانات نفسها في كل موطن؟","student":"يقارن بين المواطن ويربط المناخ بنوع النباتات والحيوانات.","eval":"الصور ص 40-41."},{"time45":"10 د","time90":"20 د","teacher":"يوجه تمرين 2-4: موطن الصحراء في سلطنة عمان، وتحديد المنتجات وآكلات النبات والمفترسات ورسم سلسلة.","student":"يكمل التمرين ويرسم سلسلة بمنتج وثلاثة مستهلكين.","eval":"تمرين 2-4."}]},{"id":"sci6~2_4_o3","code":"6Eo1","text":"يقوم بملاحظات متنوعة ذات صلة باستخدام أدوات بسيطة بشكل صحيح.","selected":true,"suffix":"","activities":[{"time45":"8 د","time90":"16 د","teacher":"يوجه ملاحظة صور المواطن المختلفة وتسجيل ما يظهر فيها من نباتات وحيوانات.","student":"يدوّن نباتات وحيوانات كل موطن من الصورة.","eval":"صور المواطن."}]},{"id":"sci6~2_4_o4","code":"6Eo4","text":"يعقد مقارنات (بين الكائنات المنتجة في موطني السافانا والمحيط).","selected":true,"suffix":"","activities":[{"time45":"7 د","time90":"14 د","teacher":"يطرح السؤال 1 ص 41: قارن الكائنات المنتجة في السافانا والمحيط، ويدوّن المقارنة في جدول.","student":"يقارن في جدول من عمودين.","eval":"السؤال 1 ص 41."}]}],"prior":"الموطن الطبيعي (الصف الرابع والدرس 2-1)؛ المفترس والفريسة (الدرس 2-3)؛ كل سلسلة غذائية تبدأ بكائن منتج","warmup":"هل تعيش الحيوانات نفسها في كل موطن؟","resources":"كتاب الطالب (ص 40-41)، تمرين 2-4 في كتاب النشاط، صور مواطن (صحراء، تحت الماء، تندرا، غابة، سافانا)، مجسم الكرة الأرضية، كتب مكتبة.","strategies":["العصف الذهني","الحوار والمناقشة","الأسئلة السابرة","التعلم التعاوني","التعلم الفردي"],"lab":"لا يوجد نشاط عملي. تُعرض صور المواطن المختلفة، ويفضّل إحضار صور من الصحراء العمانية.","misconception":"يعتقد الطلبة أن السلاسل الغذائية في المواطن المختلفة تتبع نمطاً واحداً ثابتاً. التشخيص: يسأل المعلم هل تبقى السلاسل كما هي دائماً؟ المعالجة: يبين أن التغيرات تحدث بسبب الكوارث الطبيعية كالحرائق والتدخل البشري كإزالة الغابات (الدرس 2-5)، وأن أعداد آكلات الأعشاب البرية أكبر مما يظن الطلبة.","exitTicket":"ما أوجه الاختلاف بين سلسلة المحيط وسلسلة الصحراء؟","homework":"إكمال تمرين 2-4 في كتاب النشاط، ثم رسم سلسلتين غذائيتين لموطن تعيش قربه (من نبات إلى مفترس)، وتبادل الدفاتر لتصحيحها في الحصة التالية.","guideAnswers":"<b>الأسئلة ص 41:</b> (1) منتجات السافانا العشب والأشجار، ومنتجات المحيط العوالق والطحالب. (2) (أ) الزرافة تأكل أوراق الأشجار، والثور البري والحمار الوحشي يأكلان العشب. (ب) العشب ← الحمار الوحشي ← الأسد؛ أوراق الأشجار ← الزرافة ← الأسد. (3) (أ) عوالق ← أسماك صغيرة ← النورس؛ عوالق ← قشريات ← الإنسان. (ب) عوالق ← سردين ← القرش؛ عوالق ← أسماك صغيرة ← أسماك كبيرة ← الإنسان.<br><b>تمرين 2-4:</b> (1) (أ) الأعشاب والنباتات الصحراوية. (ب) الأمطار القليلة والضباب الموسمي وقطرات الندى. (2) ثلاثة من: الظبي والنملة والخنفساء واليرقة. (3) القط الرملي يأكل الفأر؛ السحالي تأكل العنكبوت؛ الصقر يأكل السحالي. (4) نباتات صحراوية ← الخنفساء ← الفأر ← البومة."},"sci6~2_5":{"course":"sci6","sem":1,"unitNum":2,"unitTitle":"الوحدة الثانية: الكائنات الحية في البيئة","unitShort":"الكائنات الحية في البيئة","code":"2-5","title":"إزالة الغابات","defaultDuration":45,"objectives":[{"id":"sci6~2_5_o0","code":"6Be1","text":"يستكشف الآثار السلبية للإنسان على البيئة، مثل فقدان الأنواع وفقدان المواطن الطبيعية (إزالة الغابات والاحتباس الحراري).","selected":true,"suffix":"","activities":[{"time45":"10 د","time90":"20 د","teacher":"يشرح أسباب إزالة الغابات وآثارها: بطء نمو الأشجار (نحو 100 عام)، وفقر التربة، واختفاء النباتات والحيوانات، وزيادة ثاني أكسيد الكربون.","student":"يسجل أسباب الإزالة وآثارها في جدول من عمودين.","eval":"النص ص 42."},{"time45":"10 د","time90":"20 د","teacher":"يعرض أهمية الغابات (موطن، أدوية، التخلص من ثاني أكسيد الكربون وإنتاج الأكسجين) ويشرح الغازات الدفيئة والاحتباس الحراري.","student":"يلخص ثلاث فوائد للغابات ويفسر الاحتباس الحراري.","eval":"الصناديق الثلاثة ص 43."}]},{"id":"sci6~2_5_o1","code":"6Be2","text":"يستكشف عدداً من طرق العناية بالبيئة، مثل زراعة الأشجار وتشجيع الآخرين على العناية بالبيئة.","selected":true,"suffix":"","activities":[{"time45":"6 د","time90":"12 د","teacher":"يناقش السؤال 3 ص 43: لماذا يعد شراء الأثاث الخشبي المستعمل طريقة جيدة للحفاظ على الغابات؟","student":"يفسر أن إعادة الاستخدام تقلل قطع أشجار جديدة.","eval":"السؤال 3 ص 43."},{"time45":"8 د","time90":"16 د","teacher":"يوجه نشاط 2-5 (ازرع شجرة): طلب شتلة وسؤال الأكبر سناً عن طريقة الزراعة والمكان وعدد مرات السقي، ويتحدث عن فوائد الأشجار.","student":"يخطط لزراعة شجرة ويدوّن الخطوات.","eval":"نشاط 2-5 ص 43."}]},{"id":"sci6~2_5_o2","code":"6Ep6","text":"يحدّد العوامل المرتبطة بموقف محدد (أسباب إزالة الغابات وآراء المؤيدين والمعارضين).","selected":true,"suffix":"","activities":[{"time45":"10 د","time90":"20 د","teacher":"يطلب تحديد أسباب إزالة الغابات ثم يوزع تمرين 2-5 لتصنيف آراء عشرة أشخاص إلى مؤيدين ومعارضين.","student":"يصنف الآراء في جدول ويبرر كل تصنيف.","eval":"تمرين 2-5."}]},{"id":"sci6~2_5_o3","code":"6Eo4","text":"يعقد مقارنات (بين تربة الغابة قبل الإزالة وبعدها).","selected":true,"suffix":"","activities":[{"time45":"5 د","time90":"10 د","teacher":"يطرح السؤال 2 ص 43: قارن بين التربة في منطقة الغابة قبل الإزالة وبعدها.","student":"يقارن في جدول من عمودين.","eval":"السؤال 2 ص 43."}]},{"id":"sci6~2_5_o4","code":"6Ep4","text":"يتنبأ بما سيحدث بناءً على المعرفة العلمية والفهم (ثاني أكسيد الكربون والأكسجين عند تدمير كل الغابات).","selected":true,"suffix":"","activities":[{"time45":"5 د","time90":"10 د","teacher":"يطرح السؤال 4 ص 43: ماذا سيحدث لثاني أكسيد الكربون والأكسجين لو دُمرت كل الغابات؟","student":"يتنبأ ويفسر تنبؤه.","eval":"السؤال 4 ص 43."}]}],"prior":"الغابات موطن للنباتات والحيوانات؛ الأشجار تصنع غذاءها وتطلق الأكسجين (الدرس 2-2)؛ الأنشطة التي يقوم بها الإنسان وتؤثر في البيئة","warmup":"ما الأشياء التي يصنعها الإنسان من خشب الغابات؟","resources":"كتاب الطالب (ص 42-43)، نشاط 2-5، تمرين 2-5 وأوراق العمل 2-5أ و2-5ب و2-5ج في كتاب النشاط، مجسم الكرة الأرضية، شتلة وماء ومكان للزراعة.","strategies":["العصف الذهني","الحوار والمناقشة","الأسئلة السابرة","التعلم التعاوني","التعلم الفردي"],"lab":"نشاط 2-5: ازرع شجرة. تحتاج كل مجموعة إلى مكان لزراعة شتلة وماء. لا يُلزم الطلبة بتنفيذه لاعتماده على الإمكانات ووجود مشاتل قريبة؛ ويمكن ترتيب زراعة أشجار في المدرسة بالتزامن مع يوم الشجرة في سلطنة عمان.","misconception":"يظن الطلبة أن الأنماط الغذائية في المواطن ثابتة لا تتغير. التشخيص: يسأل المعلم ماذا يحدث للسلاسل الغذائية بعد قطع الغابة؟ المعالجة: يبين أن الكوارث الطبيعية (كالحرائق) والتدخل البشري (كإزالة الغابات) يغيّران المواطن وسلاسلها باستمرار.","exitTicket":"كيف تساعد أنت في حماية الغابات؟","homework":"إكمال تمرين 2-5 في كتاب النشاط (مؤيدو إزالة الغابات ومعارضوها)، وكتابة تقرير مختصر عن «مشروع مليون نخلة» في سلطنة عمان وعرضه في الحصة التالية.","guideAnswers":"<b>الأسئلة ص 43:</b> (1) ثلاثة من: تزيد نسبة ثاني أكسيد الكربون؛ تقل نسبة الأكسجين؛ تختفي أنواع من الأشجار وقد تنقرض؛ تختفي مواطن الحيوانات؛ تُدمر الأشجار التي توفر الأدوية. (2) قبل الإزالة كانت تتحلل أوراق الأشجار وتكوّن سماداً يبقي التربة خصبة، وبعدها لا يوجد سماد وتصبح التربة غير خصبة. (3) إعادة استخدام الأثاث تغني عن قطع أشجار أكثر لصنع أثاث جديد. (4) يزداد ثاني أكسيد الكربون ويقل الأكسجين.<br><b>تمرين 2-5:</b> المؤيدون: مزارع القمح، ومخطط المدن، والنجار، والحطاب، والرجل الذي يحمل الخشب. المعارضون: عالمة الأحياء، وعالم البيئة، والمعالج الشعبي، والطبيبة، والرجل المسن.<br><b>ورقة العمل 2-5أ:</b> قطعت الغابات لزراعة البن والشاي، وانجرفت التربة إلى الأنهار، وزرعت النساء 40 مليون شجرة تمتص ثاني أكسيد الكربون. <b>ورقة العمل 2-5ج:</b> أسباب: التعدين والبناء وصناعة الأثاث وخشب التدفئة وزراعة المحاصيل؛ آثار: تربة غير خصبة، فقدان المواطن، انقراض أنواع، فقدان أشجار الأدوية، زيادة الاحتباس الحراري."},"sci6~2_6":{"course":"sci6","sem":1,"unitNum":2,"unitTitle":"الوحدة الثانية: الكائنات الحية في البيئة","unitShort":"الكائنات الحية في البيئة","code":"2-6","title":"تلوث الهواء: أ. مصادر التلوث وآثاره","defaultDuration":45,"objectives":[{"id":"sci6~2_6_o0","code":"6Be1","text":"يستكشف الآثار السلبية للإنسان على البيئة: مصادر تلوث الهواء (عوادم السيارات، وحرق الفحم والنفط في المصانع ومحطات الطاقة).","selected":true,"suffix":"","activities":[{"time45":"8 د","time90":"16 د","teacher":"يعرض تركيب الغلاف الجوي (النيتروجين والأكسجين وكميات قليلة من ثاني أكسيد الكربون وبخار الماء)، ويبين أن البشر يلوثونه بغازات أخرى.","student":"يسجل مكونات الهواء النقي ويذكر ما يضيفه الإنسان.","eval":"النص ص 44."},{"time45":"10 د","time90":"20 د","teacher":"يشرح أن أول أكسيد الكربون غاز سام ينبعث من عوادم السيارات والدراجات النارية والشاحنات، وأن السيارات الجديدة أقل تلويثاً.","student":"يربط كل غاز بمصدره في جدول.","eval":"الصورة والنص ص 44."},{"time45":"11 د","time90":"22 د","teacher":"يوضح أن ثاني أكسيد الكبريت وأكسيد النيتروجين ينبعثان من الفحم والنفط المحترقين في المصانع، وأن الطاقة الشمسية والرياح والطاقة المائية لا تلوث لكنها أكثر تكلفة.","student":"يقارن بين مصادر الطاقة الملوثة وغير الملوثة.","eval":"النص ص 44."}]},{"id":"sci6~2_6_o1","code":"6Be1","text":"يستكشف آثار تلوث الهواء السلبية في النباتات والحيوانات وصحة الإنسان (الالتهاب الشعبي والربو).","selected":true,"suffix":"","activities":[{"time45":"10 د","time90":"20 د","teacher":"يبين أن الرياح قد تنشر الملوثات لكن الهواء الملوث يظل عادة فوق المدن، وأنه يضر بالنباتات والحيوانات ويسبب الالتهاب الشعبي والربو.","student":"يسجل آثار التلوث في ثلاثة محاور: نباتات، وحيوانات، وإنسان.","eval":"النص ص 44."},{"time45":"15 د","time90":"30 د","teacher":"يوزع تمرين 2-6 ويوجه الإجابة عن الأسئلة 1-3 (الغازات الملوثة، ومصادرها، وسبب كثرة التلوث في المدن الكبيرة).","student":"يجيب كتابياً عن الأسئلة ويراجع مع زميله.","eval":"تمرين 2-6."},{"time45":"5 د","time90":"10 د","teacher":"يطرح تحدياً: اقترح كيف يمكن تقليل تلوث الهواء في المدن.","student":"يقترح حلاً مبنياً على ما تعلمه.","eval":"تحدي الدليل ص 58."}]}],"prior":"الغازات في الغلاف الجوي (الوحدة 3 للصف الرابع)؛ غازا الأكسجين وثاني أكسيد الكربون ودورهما في حياة الكائنات؛ الوقود الأحفوري مصدر للطاقة","warmup":"ما الأشياء التي تخرج دخاناً إلى الهواء حولنا؟","resources":"كتاب الطالب (ص 44)، تمرين 2-6 في كتاب النشاط، صور لعوادم السيارات والمصانع، سبورة وأقلام ملونة.","strategies":["العصف الذهني","الحوار والمناقشة","التعلم بالنمذجة","التعلم الفردي"],"lab":"لا يوجد نشاط عملي في هذه الورقة. يُحضّر نشاط 2-6 (قياس جزيئات الغبار) في ورقة (ب).","misconception":"يظن بعض الطلبة أن كل غازات الهواء ملوثات. التشخيص: يسأل المعلم هل الأكسجين ملوث؟ المعالجة: يوضح أن النيتروجين والأكسجين وثاني أكسيد الكربون وبخار الماء مكونات طبيعية للهواء، وأن الملوثات غازات أخرى يضيفها الإنسان أو تزيد نسبتها عن الطبيعي.","exitTicket":"ما الغازات الثلاثة التي تلوث هواء المدن؟","homework":"إكمال تمرين 2-6 في كتاب النشاط، وكتابة فقرة قصيرة عن طريقة تقلل بها أسرتك تلوث الهواء، تُقيَّم في الحصة التالية.","guideAnswers":"<b>تمرين 2-6:</b> (1) أول أكسيد الكربون وثاني أكسيد الكبريت وأكسيد النيتروجين. (2) عوادم السيارات: أول أكسيد الكربون وأكسيد النيتروجين؛ المصانع ومحطات الكهرباء: الغازات الثلاثة إذا كانت تحرق الفحم والنفط. (3) ينتج الفحم عند احتراقه ثاني أكسيد الكربون وثاني أكسيد الكبريت فتتكون طبقة هواء ملوث فوق المدينة، ويتنقل ملايين الناس بالحافلات والقطارات والسيارات وسيارات الأجرة فيتلوث الهواء بأول أكسيد الكربون."},"sci6~2_6b":{"course":"sci6","sem":1,"unitNum":2,"unitTitle":"الوحدة الثانية: الكائنات الحية في البيئة","unitShort":"الكائنات الحية في البيئة","code":"2-6","title":"تلوث الهواء: ب. نشاط قياس غبار الهواء","defaultDuration":45,"objectives":[{"id":"sci6~2_6b_o0","code":"6Ep4","text":"يتنبأ بما سيحدث بناءً على المعرفة العلمية والفهم (الشريحة الأكثر غباراً).","selected":true,"suffix":"","activities":[{"time45":"13 د","time90":"26 د","teacher":"يوجه اختيار خمسة مواقع لا تُحرّك فيها الشرائح أسبوعاً (أعمدة بوابات، إطارات نوافذ، جذوع أشجار) ويطلب التنبؤ بالشريحة الأكثر غباراً.","student":"يختار مواقعه ويتنبأ بالشريحة الأكثر غباراً.","eval":"نشاط 2-6 ص 45."}]},{"id":"sci6~2_6b_o1","code":"6Ep5","text":"يقترح ويقيّم تفسيرات للتنبؤات باستخدام المعرفة العلمية والفهم ويوصلها للآخرين بوضوح.","selected":true,"suffix":"","activities":[{"time45":"13 د","time90":"26 د","teacher":"يطلب أسباباً للتنبؤ: قرب المصانع أو المحاجر أو الطرق المزدحمة حيث الأتربة والدخان والأبخرة.","student":"يكتب تنبؤه وسببه ويناقشه مع مجموعته.","eval":"نشاط 2-6 ص 45."},{"time45":"5 د","time90":"10 د","teacher":"يوجه تقييم الأدلة وتفسير نتيجة كل موقع بالمعرفة العلمية.","student":"يفسر النتائج ويعرضها على المجموعة.","eval":"السؤال 3 ص 45."}]},{"id":"sci6~2_6b_o2","code":"6Eo1","text":"يقوم بملاحظات متنوعة ذات صلة باستخدام أدوات بسيطة بشكل صحيح (العدسة المكبرة).","selected":true,"suffix":"","activities":[{"time45":"12 د","time90":"24 د","teacher":"يوزع الشرائح والأدوات: يحدد على كل شريحة مستطيلاً (1 × 4 سم) بقلم التخطيط ويرقمها من 1 إلى 5 ثم يغطي الجانب الآخر بطبقة رقيقة من الهلام النفطي.","student":"يجهز الشرائح ويلصقها بحيث يواجه الهلام الخارج.","eval":"نشاط 2-6 ص 45."},{"time45":"5 د","time90":"10 د","teacher":"يوجه فحص كل شريحة بالعدسة المكبرة وعدّ الجزيئات في المنطقة المحددة (التقدير عند الصعوبة).","student":"يفحص بالعدسة ويعد الجزيئات.","eval":"نشاط 2-6 ص 45."}]},{"id":"sci6~2_6b_o3","code":"6Eo3","text":"يستخدم الجداول والتمثيل البياني بالأعمدة لعرض النتائج.","selected":true,"suffix":"","activities":[{"time45":"5 د","time90":"10 د","teacher":"يرسم جدول النتائج (موقع الشريحة وعدد الجزيئات) ويوزع ورقة العمل 2-6أ.","student":"يكمل جدول النتائج.","eval":"ورقة العمل 2-6أ."},{"time45":"8 د","time90":"16 د","teacher":"يوزع ورقة العمل 2-6ب: يحدد المقياس بين أصغر وأكبر عدد ويرسم أعمدة متساوية العرض ويضع عنواناً ومحورين مسمّين.","student":"يرسم التمثيل البياني بالأعمدة ويضع العنوان.","eval":"ورقة العمل 2-6ب."}]},{"id":"sci6~2_6b_o4","code":"6Eo4","text":"يعقد مقارنات (بين نتائج المجموعات في مواقع مختلفة).","selected":true,"suffix":"","activities":[{"time45":"7 د","time90":"14 د","teacher":"يطرح السؤال 1 ص 45: قارن نتائجك بنتائج المجموعات الأخرى، ما الموقع الأكثر تلوثاً ولماذا؟","student":"يقارن النتائج في جدول الصف.","eval":"السؤال 1 ص 45."}]},{"id":"sci6~2_6b_o5","code":"6Eo6","text":"يحدّد الأنماط في النتائج والنتائج التي لا تبدو ملائمة للنمط.","selected":true,"suffix":"","activities":[{"time45":"7 د","time90":"14 د","teacher":"يوجه تحديد النمط (أين يزداد الغبار؟) والمواقع التي لم تطابق التنبؤ (السؤال 2).","student":"يحدد النمط والنتيجة غير الملائمة له.","eval":"السؤال 2 ص 45."}]},{"id":"sci6~2_6b_o6","code":"6Eo9","text":"يحدد ما إذا كانت الأدلة تدعم تنبؤاً ما، مبيناً كيف.","selected":true,"suffix":"","activities":[{"time45":"5 د","time90":"10 د","teacher":"يطرح السؤال 3 ص 45: هل الأدلة التي جمعتها تدعم تنبؤاتك؟","student":"يحدد هل دعمت النتائج تنبؤه ويوضح.","eval":"السؤال 3 ص 45."}]}],"prior":"مصادر تلوث الهواء وآثاره (الورقة السابقة)؛ الاستقصاء العادل وتسجيل النتائج في جدول (الصف الخامس)؛ التمثيل البياني بالأعمدة (الوحدة 1)","warmup":"كيف نعرف أن في الهواء أتربة لا نراها؟","resources":"كتاب الطالب (ص 45)، نشاط 2-6، ورقتا العمل 2-6أ و2-6ب في كتاب النشاط، خمس شرائح زجاجية (أو بلاستيكية شفافة) لكل مجموعة، قلم تخطيط، هلام نفطي (فازلين)، شريط لاصق، عدسة مكبرة.","strategies":["العصف الذهني","التعلم التعاوني","الأسئلة السابرة","التعلم الفردي"],"lab":"نشاط 2-6: قياس جزيئات الغبار في الهواء. تحتاج كل مجموعة إلى خمس شرائح، وقلم تخطيط، وهلاماً نفطياً، وشريطاً لاصقاً، وعدسة مكبرة. يُراعى ضم طلبة من مستويات مختلفة في المجموعة. تُرسم على كل شريحة مساحة (1 × 4 سم) ويُغطى الجانب الآخر بالهلام ثم تُلصق في مواقع لا تتحرك منها لمدة أسبوع، ويواجه الهلام الخارج. تُنقل الشرائح بعناية بحيث لا يلمس الهلام شيئاً. يرافق الطلبة شخص بالغ عند الابتعاد عن فناء المدرسة. الغبار نوع واحد من التلوث، أما الغازات فجزيئاتها أصغر من أن تُعدّ.","misconception":"قد يظن الطلبة أن الهواء الذي يبدو صافياً خالٍ من الملوثات. التشخيص: يسأل المعلم هل نرى الغبار في الهواء؟ المعالجة: يبين أن الشرائح تجمع جزيئات لا تُرى بالعين المجردة، وأن الغازات الملوثة أصغر من أن تُعد.","exitTicket":"اذكر أثرين سلبيين لتلوث الهواء في البيئة.","homework":"اختيار نوع آخر من التلوث (تلوث التربة أو الماء) والعمل في مجموعة على نشرة بحجم ورقة A4 تضم صور ومعلومات (السؤال 4 ص 45)، وتُعرض في الصف وتُقيَّم بسلم الدرجات في الدليل.","guideAnswers":"<b>نشاط 2-6:</b> تعتمد الإجابات على نتائج استقصاءات الطلبة (الأسئلة 1-3). (4) نشرة عن تلوث التربة أو الماء.<br><b>تحدث عن:</b> الآثار السلبية: الأمراض (كالالتهاب الشعبي والربو)، وضرر النباتات والحيوانات، وطبقة الهواء الملوث فوق المدن.<br><b>ورقتا العمل 2-6أ و2-6ب:</b> جدول تسجيل عدد الجزيئات في كل موقع وتمثيل بياني بالأعمدة بعنوان مناسب."},"sci6~2_7":{"course":"sci6","sem":1,"unitNum":2,"unitTitle":"الوحدة الثانية: الكائنات الحية في البيئة","unitShort":"الكائنات الحية في البيئة","code":"2-7","title":"الأمطار الحمضية: أ. تكوّنها وآثارها في البيئة","defaultDuration":45,"objectives":[{"id":"sci6~2_7_o0","code":"6Be1","text":"يستكشف الآثار السلبية للإنسان على البيئة: تكوّن الأمطار الحمضية من الغازات الناتجة عن حرق الوقود الأحفوري.","selected":true,"suffix":"","activities":[{"time45":"12 د","time90":"24 د","teacher":"يوضح أن حرق الفحم والنفط والغاز ينتج ثاني أكسيد الكبريت وأكسيد النيتروجين، وأنهما يتفاعلان مع بخار الماء فيكوّنان حمضي الكبريتيك والنيتريك.","student":"يكمل مخطط تكوّن الأمطار الحمضية بالأسهم.","eval":"الصورة ص 46."},{"time45":"10 د","time90":"20 د","teacher":"يطمئن الطلبة بأن الأمطار الحمضية لا تؤذي الجلد وأن حمضيتها أقل من عصير الليمون.","student":"يفرق بين الحمض الضعيف والخطر.","eval":"النص ص 46."}]},{"id":"sci6~2_7_o1","code":"6Be1","text":"يستكشف آثار الأمطار الحمضية في التربة والنباتات والبحيرات والكائنات الحية.","selected":true,"suffix":"","activities":[{"time45":"12 د","time90":"24 د","teacher":"يشرح أن الأمطار الحمضية تجرد التربة من مغذياتها فتضعف النباتات وتتساقط أوراقها وتموت أغصان الأشجار الكبيرة.","student":"يسجل أثر الأمطار الحمضية على التربة والجذور والأوراق.","eval":"النص ص 47."},{"time45":"10 د","time90":"20 د","teacher":"يعرض أثرها في بحيرات الماء العذب: تلف بيض الضفادع والأسماك وذوبان قشرة الروبيان الكلسية.","student":"يصف أثر الأمطار الحمضية في حيوانات البحيرة.","eval":"تمرين 2-7."}]},{"id":"sci6~2_7_o2","code":"6Be3","text":"يبين أثر موت كائن في سلسلة غذائية واحدة في بقية كائناتها (موطن الماء العذب).","selected":true,"suffix":"","activities":[{"time45":"8 د","time90":"16 د","teacher":"يوجه تمرين 2-7: رسم سلسلة روبيان ← سمك ← طائر مالك الحزين وتوضيح أثر موت الروبيان فيها.","student":"يرسم السلسلة ويفسر أثر موت الروبيان.","eval":"تمرين 2-7 (3 و4)."},{"time45":"8 د","time90":"16 د","teacher":"يربط ضعف النباتات بنقص غذاء آكلات الأعشاب وبقية السلسلة.","student":"يتتبع أثر ضعف النبات في السلسلة.","eval":"نقاش الصف."}]}],"prior":"الأمطار والغلاف الجوي (الصفوف السابقة)؛ تلوث الهواء ومصادره (الدرس 2-6)؛ السلاسل الغذائية (الدروس 2-1 إلى 2-4)","warmup":"ما رأيك في سبب تآكل سطح هذا التمثال الحجري؟","resources":"كتاب الطالب (ص 46-47)، تمرين 2-7 وورقة العمل 2-7 في كتاب النشاط، صور مبانٍ وتماثيل متضررة، سبورة وأقلام ملونة.","strategies":["العصف الذهني","الحوار والمناقشة","التعلم التعاوني","التعلم الفردي"],"lab":"لا يوجد نشاط عملي في هذه الورقة. يُحضّر المعلم الشتلات لنشاط 2-7 مسبقاً (تحتاج أسبوعاً أو اثنين لتنمو) قبل ورقة (ب).","misconception":"يعتقد بعض الطلبة أن الأمطار الحمضية تؤذي الجلد فتنفخه أو تمزقه. التشخيص: يسأل المعلم هل يؤذينا المطر الحمضي إذا سقط على الجلد؟ المعالجة: يطمئنهم بأن حمضيته أقل من عصير الليمون ولا يؤذي الجلد، لكن أثره يظهر على النباتات والحيوانات والمباني بمرور الوقت.","exitTicket":"اذكر ثلاثة أضرار للأمطار الحمضية في البيئة.","homework":"إكمال تمرين 2-7 في كتاب النشاط، وكتابة فقرة تشرح كيف تتكون الأمطار الحمضية، ثم التحضير لنشاط 2-7 بإحضار شتلتين سليمتين وعصير ليمون.","guideAnswers":"<b>تمرين 2-7:</b> (1) الأمطار الحمضية أمطار تفاعل فيها ثاني أكسيد الكبريت أو أكسيد النيتروجين لينتج حمضاً ضعيفاً. (2) يتلف بيض الضفادع بفعل الحمض فلا يفقس مما يقلل أعدادها. (3) روبيان ← سمك ← طائر مالك الحزين. (4) يموت الروبيان فلا يتوفر غذاء للسمك ولا لطائر مالك الحزين.<br><b>ورقة العمل 2-7:</b> (1) الأمطار الحمضية مياه أمطار تفاعل فيها ثاني أكسيد الكبريت أو أكسيد النيتروجين. (2) تتفاعل الملوثات الكبريتية مع معادن الحجر الجيري والرملي فتكوّن مسحوقاً تجرفه الأمطار فتتآكل المباني."},"sci6~2_7b":{"course":"sci6","sem":1,"unitNum":2,"unitTitle":"الوحدة الثانية: الكائنات الحية في البيئة","unitShort":"الكائنات الحية في البيئة","code":"2-7","title":"الأمطار الحمضية: ب. نشاط 2-7 وأثرها في المباني","defaultDuration":45,"objectives":[{"id":"sci6~2_7b_o0","code":"6Ep4","text":"يتنبأ بما سيحدث بناءً على المعرفة العلمية والفهم (أثر عصير الليمون في الشتلة والخل في الطباشير).","selected":true,"suffix":"","activities":[{"time45":"12 د","time90":"24 د","teacher":"يوزع الشتلتين السليمتين ويوجه رياً إحداهما بماء الصنبور والأخرى بالمقدار نفسه (نحو 125 مل) من عصير الليمون لمدة ثلاثة أيام مع تثبيت بقية الظروف.","student":"ينفذ الاستقصاء مع مجموعته ويدوّن ما يغيّره وما يثبّته.","eval":"نشاط 2-7 ص 46."},{"time45":"8 د","time90":"16 د","teacher":"يطلب كتابة تنبؤ لما سيحدث لكل شتلة بناءً على ما تعلموه عن الأمطار الحمضية.","student":"يكتب تنبؤه ويعلنه للمجموعة.","eval":"نشاط 2-7 ص 46."},{"time45":"5 د","time90":"10 د","teacher":"يعرض قطعة طباشير أو حجراً جيرياً ويطلب التنبؤ بما سيحدث عند سكب الخل عليها.","student":"يتنبأ بما سيحدث.","eval":"تجربة العرض."}]},{"id":"sci6~2_7b_o1","code":"6Ep5","text":"يقترح ويقيّم تفسيرات للتنبؤات باستخدام المعرفة العلمية والفهم ويوصلها للآخرين بوضوح.","selected":true,"suffix":"","activities":[{"time45":"8 د","time90":"16 د","teacher":"يطلب تفسير التغيرات التي ظهرت على الشتلتين بما تعلموه عن الأمطار الحمضية (السؤال 3).","student":"يفسر أن الحمض جرد التربة من مغذياتها فضعفت النبتة.","eval":"السؤال 3 ص 47."}]},{"id":"sci6~2_7b_o2","code":"6Eo4","text":"يعقد مقارنات (بين شتلة الأمطار الحمضية وشتلة ماء الصنبور).","selected":true,"suffix":"","activities":[{"time45":"10 د","time90":"20 د","teacher":"يطلب مقارنة الشتلتين بعد خمسة أيام من حيث الأوراق والسيقان (السؤال 1).","student":"يقارن في جدول من عمودين.","eval":"السؤال 1 ص 47."}]},{"id":"sci6~2_7b_o3","code":"6Eo6","text":"يحدّد الأنماط في النتائج والنتائج التي لا تبدو ملائمة للنمط.","selected":true,"suffix":"","activities":[{"time45":"5 د","time90":"10 د","teacher":"يطلب تحديد النمط العام في نتائج المجموعات (ما يحدث للنبتة الحمضية في كل مجموعة).","student":"يقارن نتائج المجموعات ويحدد النمط.","eval":"نتائج الصف."}]},{"id":"sci6~2_7b_o4","code":"6Eo9","text":"يحدد ما إذا كانت الأدلة تدعم تنبؤاً ما، مبيناً كيف.","selected":true,"suffix":"","activities":[{"time45":"5 د","time90":"10 د","teacher":"يطرح السؤال 2 ص 47: هل تدعم هذه النتائج تنبؤاتك؟ كيف؟","student":"يحدد هل دعمت النتائج تنبؤه ويوضح.","eval":"السؤال 2 ص 47."}]},{"id":"sci6~2_7b_o5","code":"6Be1","text":"يستكشف الآثار السلبية للإنسان على البيئة: أثر الأمطار الحمضية في المباني والأعمال الحجرية.","selected":true,"suffix":"","activities":[{"time45":"10 د","time90":"20 د","teacher":"يسكب الخل على الطباشير أو الحجر الجيري، ويوضح أن الخل حمض ضعيف مثل الأمطار الحمضية، ثم يوجه كتابة التقرير (السؤال 4).","student":"يلاحظ الرغوة ويكتب تقريراً عن ضرر الأمطار الحمضية للمباني.","eval":"السؤال 4 وتحدث عن ص 47."}]}],"prior":"تكوّن الأمطار الحمضية وأثرها في التربة والنباتات (الورقة السابقة)؛ الاستقصاء العادل: تغيير عامل واحد وتثبيت البقية؛ التنبؤ وتفسيره","warmup":"لماذا طعم عصير الليمون حامض؟","resources":"كتاب الطالب (ص 46-47)، نشاط 2-7، ورقة العمل 2-7 في كتاب النشاط، شتلتان سليمتان لكل مجموعة، ماء صنبور، عصير ليمون (نحو 125 مل)، خل، طباشير أو حجر جيري.","strategies":["العصف الذهني","التعلم التعاوني","الأسئلة السابرة","التعلم بالنمذجة"],"lab":"نشاط 2-7: ملاحظة تأثير الأمطار الحمضية. تحتاج كل مجموعة إلى شتلتين سليمتين تنموان في التربة، وماء صنبور، ونحو 125 مل من عصير الليمون. تُروى إحداهما بماء الصنبور والأخرى بالمقدار نفسه من العصير لمدة ثلاثة أيام (اختبار ضابط). يُحضّر المعلم الشتلات مسبقاً لأنها تحتاج أسبوعاً أو اثنين. تجربة العرض: خل وطباشير أو حجر جيري، فتظهر رغوة ويتحلل جزء منه لأن الخل حمض ضعيف، ويُحذر من ملامسة الخل للعينين.","misconception":"يظن الطلبة أن نمط السلاسل الغذائية في المواطن ثابت لا يتأثر بالتلوث. التشخيص: يسأل المعلم ماذا يحدث للسلسلة إذا ضعفت النباتات؟ المعالجة: يبين أن الأمطار الحمضية تغير السلاسل الغذائية بإضعاف النباتات وإتلاف بيض الحيوانات.","exitTicket":"كيف توضّح أن الأمطار الحمضية تدمر الحجر؟","homework":"إكمال تقرير الصفحة الواحدة عن ضرر الأمطار الحمضية للمباني (السؤال 4 ص 47) وتسليمه في الحصة التالية.","guideAnswers":"<b>نشاط 2-7:</b> (1) (أ) تبدأ أوراق النبات المروي بالأمطار الحمضية في السقوط. (ب) تصبح سيقانه ضعيفة وذابلة. (2) تدعم النتائج التنبؤات لأن الأمطار الحمضية تُسقط أوراق الأشجار وتميت أغصانها. (3) تمتص النباتات المغذيات من التربة والأمطار الحمضية تجردها منها فتضعف النباتات وتسقط أوراقها ويذبل ساقها. (4) للأمطار الحمضية تأثير ضار في المباني والتماثيل والآثار والسيارات؛ تقشّر الدهان وتجعل التماثيل تبدو قديمة ومتهالكة، وتتآكل المباني من الحجر الجيري والرخام والحجر الرملي.<br><b>تحدث عن:</b> سكب الخل على الحجر الجيري أو الطباشير فتظهر رغوة ويتحلل جزء منه لأن الخل حمض ضعيف مثل الأمطار الحمضية."},"sci6~2_8":{"course":"sci6","sem":1,"unitNum":2,"unitTitle":"الوحدة الثانية: الكائنات الحية في البيئة","unitShort":"الكائنات الحية في البيئة","code":"2-8","title":"إعادة التدوير: أ. النفايات وإعادة الاستخدام والتدوير","defaultDuration":45,"objectives":[{"id":"sci6~2_8_o0","code":"6Be2","text":"يستكشف عدداً من طرق العناية بالبيئة: يعرف التخلص من النفايات ومرادم النفايات وإعادة التدوير والتقليل من النفايات.","selected":true,"suffix":"","activities":[{"time45":"10 د","time90":"20 د","teacher":"يعرض مشكلة التخلص من النفايات ومرادم النفايات (أكوام ضخمة بعيدة عن السكان تُغطى بالتربة)، ويتحدث عن «مدينة المخلفات» في القاهرة.","student":"يصف مردم النفايات ومشكلاتها بكلماته.","eval":"الصورة والنص ص 48."},{"time45":"10 د","time90":"20 د","teacher":"يعرّف إعادة التدوير بأنها معالجة الأشياء لتصبح منتجاً جديداً ويفرق بينها وبين إعادة الاستخدام والتقليل.","student":"يصنف أمثلة إلى تقليل أو إعادة استخدام أو إعادة تدوير.","eval":"النص ص 48."},{"time45":"9 د","time90":"18 د","teacher":"يفرغ قمامة على جريدة ويرفع كل عنصر ويسأل: هل يمكن تقليله أو إعادة استخدامه أو إعادة تدويره؟","student":"يفرز القمامة المعروضة إلى مجموعات.","eval":"قمامة معروضة."}]},{"id":"sci6~2_8_o1","code":"6Be2","text":"يفسر كيف تساعد إعادة الاستخدام وإعادة التدوير على حماية البيئة والموارد الطبيعية (الورق، الزجاج، الألومنيوم، البلاستيك).","selected":true,"suffix":"","activities":[{"time45":"12 د","time90":"24 د","teacher":"يعرض الصناديق الأربعة ص 48: الورق يقلل قطع الأشجار، والزجاج يُصهر ويُعاد تشكيله، والألومنيوم تدويره يستهلك طاقة أقل، والبلاستيك لا يتحلل.","student":"يلخص في جدول فائدة تدوير كل مادة.","eval":"الصور ص 48."},{"time45":"10 د","time90":"20 د","teacher":"يوزع تمرين 2-8: تحديد كل عنصر من القمامة وكيفية إعادة استخدامه أو تدويره.","student":"يملأ جدول القمامة وكيفية إعادة تدويرها.","eval":"تمرين 2-8."},{"time45":"8 د","time90":"16 د","teacher":"يوزع ورقة العمل 2-8أ (أفكار لإعادة استخدام العلب) ويطلب فكرة جديدة.","student":"يقترح فكرة لإعادة استخدام علبة.","eval":"ورقة العمل 2-8أ."}]}],"prior":"إعادة التدوير في الوحدة 2 للصف الرابع؛ إزالة الغابات وأثرها (الدرس 2-5)؛ أمثلة المواد: الورق والزجاج والمعدن والبلاستيك","warmup":"ماذا نفعل بزجاجة بلاستيكية فارغة بدل رميها؟","resources":"كتاب الطالب (ص 48)، تمرين 2-8 وورقة العمل 2-8أ في كتاب النشاط، قمامة (ورق، كرتون، كيس بلاستيك، زجاجة بلاستيكية، علبة زجاجية، علبة مشروبات، قشور خضروات)، جرائد.","strategies":["العصف الذهني","الحوار والمناقشة","التعلم التعاوني","التعلم الفردي"],"lab":"لا يوجد نشاط عملي مستقل في هذه الورقة. تُجهَّز القمامة المعروضة نظيفة وآمنة (دون زجاج مكسور)، ويرتدي الطلبة القفازات عند فرزها.","misconception":"يظن بعض الطلبة أن كل ما نرميه يتحلل وأن المردم يحل المشكلة. التشخيص: يسأل المعلم ماذا يحدث لعلبة معدنية دُفنت في الأرض؟ المعالجة: يبين أن كثيراً من الأشياء كالبلاستيك والمعادن لا تتحلل لسنوات طويلة، فالحل التقليل وإعادة الاستخدام وإعادة التدوير.","exitTicket":"كيف تحمي إعادة تدوير الورق الغابات؟","homework":"إكمال تمرين 2-8 في كتاب النشاط، وإحضار قشور خضروات وفاكهة ومخلفات حديقة (لا بقايا طعام مطبوخ ولا لحوم) لنشاط صنع السماد في الورقة التالية.","guideAnswers":"<b>تمرين 2-8 (أمثلة):</b> قنينة زجاجية: أعيد استخدامها أو أضعها في حاوية الزجاج؛ علبة المشروبات المعدنية: أستخدمها لحفظ فرش الرسم أو أضعها في حاوية التدوير؛ جريدة: أستخدمها لتغليف شيء أو أضعها في حاوية الورق؛ لب التفاح وقشر الخضروات: أضعها في السماد العضوي؛ حاوية بلاستيكية: أغسلها وأستخدمها لتخزين الأشياء أو أضعها في حاوية التدوير؛ مجلة: أعطيها شخصاً آخر أو آخذها إلى مستشفى أو عيادة؛ صندوق كرتوني: أستخدمه لحفظ الأشياء أو أضعه في حاوية التدوير؛ علب الطعام: أستخدمها لوضع فرش الرسم أو أضعها في حاوية التدوير."},"sci6~2_8b":{"course":"sci6","sem":1,"unitNum":2,"unitTitle":"الوحدة الثانية: الكائنات الحية في البيئة","unitShort":"الكائنات الحية في البيئة","code":"2-8","title":"إعادة التدوير: ب. صنع السماد ومردم النفايات","defaultDuration":45,"objectives":[{"id":"sci6~2_8b_o0","code":"6Be2","text":"يستكشف عدداً من طرق العناية بالبيئة: صنع السماد العضوي من مخلفات الطعام والحدائق وتقليل استخدام الورق وإعادة استخدام الأوعية البلاستيكية.","selected":true,"suffix":"","activities":[{"time45":"15 د","time90":"30 د","teacher":"ينفذ عرض نشاط 2-8 (صنع السماد): يجمع القشور والحشائش والأوراق في كيس، ويضيف قليلاً من الماء ويتركه في مكان دافئ أسابيع.","student":"يشارك في جمع المخلفات ووضعها في الكيس وإضافة الماء.","eval":"نشاط 2-8 ص 49."},{"time45":"8 د","time90":"16 د","teacher":"يطرح السؤالين 1 و2 ص 49: طرق لاستخدام ورق أقل، وطرق لإعادة استخدام الأوعية البلاستيكية، ثم السؤال 3 عن أهمية السماد.","student":"يقترح طرقاً لتقليل الورق وإعادة استخدام الأوعية ويفسر أهمية السماد.","eval":"الأسئلة 1-3 ص 49."}]},{"id":"sci6~2_8b_o1","code":"6Be2","text":"يشجع الآخرين على العناية بالبيئة بصنع ملصق عن إعادة التدوير وإعادة الاستخدام في المنزل.","selected":true,"suffix":"","activities":[{"time45":"10 د","time90":"20 د","teacher":"يوجه صنع ملصق لتشجيع الأفراد على إعادة التدوير ويعرض معايير تقويمه: لفت النظر ووضوح الرسالة (السؤال 4).","student":"يصمم ملصقاً بشعار ورسم ورسالة واضحة.","eval":"السؤال 4 ص 49."},{"time45":"8 د","time90":"16 د","teacher":"يناقش «تحدث عن»: كيف يمكنك أنت وأسرتك إعادة التدوير وإعادة الاستخدام في المنزل؟ ويصحح الأفكار الخاطئة.","student":"يذكر أفكاراً لأسرته ويصحح الخاطئ منها.","eval":"تحدث عن ص 49."}]},{"id":"sci6~2_8b_o2","code":"6Ep4","text":"يتنبأ بما سيحدث بناءً على المعرفة العلمية والفهم (ما يحدث للقمامة المدفونة).","selected":true,"suffix":"","activities":[{"time45":"12 د","time90":"24 د","teacher":"يوزع ورقة العمل 2-8ب: حفرتان بعمق 50 سم، في إحداهما قشور وورقة وفي الأخرى علبة معدنية وعبوة بلاستيكية، ويطلب التنبؤ بالنتيجة بعد أسبوعين وشهرين.","student":"يتنبأ بما سيحدث لكل نوع من القمامة المدفونة.","eval":"ورقة العمل 2-8ب."}]},{"id":"sci6~2_8b_o3","code":"6Eo1","text":"يقوم بملاحظات متنوعة ذات صلة باستخدام أدوات بسيطة بشكل صحيح (ملاحظة السماد وتحلل المواد).","selected":true,"suffix":"","activities":[{"time45":"7 د","time90":"14 د","teacher":"يبين أي المواد تضاف إلى السماد (قشور وحشائش وأوراق) وأيها لا تضاف (أكياس البلاستيك والطعام المطبوخ).","student":"يلاحظ ويصنف المواد القابلة للإضافة.","eval":"المواد المعروضة."}]}],"prior":"معنى إعادة التدوير وإعادة الاستخدام والتقليل (الورقة السابقة)؛ المخلفات العضوية تتحلل (الصف الرابع)؛ ماذا تفعل بقشور الخضروات في المنزل","warmup":"ما الذي يمكن فعله بقشور الخضروات غير رميها؟","resources":"كتاب الطالب (ص 49)، نشاط 2-8، ورقة العمل 2-8ب في كتاب النشاط، بقايا طعام نباتية (لا مطبوخة ولا لحوم)، مخلفات حدائق، كيس بلاستيكي كبير أو دلو بغطاء، ماء، مجرفة، علبة مشروبات معدنية، عبوة بلاستيكية، ورق، أقلام وألوان.","strategies":["العصف الذهني","التعلم بالنمذجة","الأسئلة السابرة","التعلم التعاوني","الحوار والمناقشة"],"lab":"نشاط 2-8: صنع السماد (يفضّل أن يعرضه المعلم تجربة عرض ويشجع الطلبة على تكراره في المنزل). تُجمع أعشاب مقطوعة وأوراق شجر وبقايا نباتية (لا بقايا مطبوخة ولا لحوم ولا أسماك) لتملأ نصف كيس كبير أو دلواً، ويُضاف الماء ويُربط الكيس أو يُغطى الدلو ويُترك في مكان دافئ أسابيع. ورقة العمل 2-8ب: حفرتان بعمق 50 سم في مكان آمن لا يُفتح، يُحذر الطلبة من ملامسة الزجاج المكسور، ويُغسل الجميع أيديهم بعد النشاط.","misconception":"يظن بعض الطلبة أن كل المخلفات تصلح للسماد. التشخيص: يعرض المعلم مواد متنوعة ويسأل أيها تتحلل. المعالجة: يوضح أن المخلفات النباتية وحدها تُحوّل إلى سماد، وأن البلاستيك والمعادن لا تتحلل وتُعاد استخدامها أو تدويرها، وتُزال الأغطية المعدنية من الزجاجات قبل التدوير.","exitTicket":"اذكر طريقتين تساعد بهما أسرتك على إعادة التدوير في المنزل.","homework":"إكمال الملصق (السؤال 4 ص 49) إن لم يكتمل وعرضه على لوحة المدرسة، وتنفيذ نشاط صنع السماد أو مردم النفايات الصغير في المنزل بمساعدة أحد البالغين وتسجيل الملاحظات.","guideAnswers":"<b>نشاط 2-8:</b> (1) استخدام ورق أقل بالرسم أو الكتابة على جانبي الورقة، أو استخدام ورق المخلفات المكتوب على جانب واحد للرسم على الجانب الآخر. (2) استخدام الأوعية البلاستيكية لتخزين بقايا الطعام أو لوضع أقلام الرصاص والدبابيس وأدوات الخياطة. (3) يوفر السماد العضوي العناصر الغذائية للنباتات لتنمو أسرع وبصورة سليمة. (4) استجابة الطلبة.<br><b>ورقة العمل 2-8ب:</b> بعد أسبوعين ثم شهرين تتحلل القشور والورق وتبقى علبة المشروبات المعدنية والعبوة البلاستيكية لسنوات طويلة؛ فإعادة التدوير تقلل ما يُرسل إلى المرادم."},"sci6~2_9":{"course":"sci6","sem":1,"unitNum":2,"unitTitle":"الوحدة الثانية: الكائنات الحية في البيئة","unitShort":"الكائنات الحية في البيئة","code":"2-9","title":"الاعتناء بالبيئة","defaultDuration":45,"objectives":[{"id":"sci6~2_9_o0","code":"6Be2","text":"يستكشف عدداً من طرق العناية بالبيئة: الحفاظ على الماء والطاقة.","selected":true,"suffix":"","activities":[{"time45":"10 د","time90":"20 د","teacher":"يشرح أن نسبة الماء العذب ثابتة بينما يزداد التلوث، ويعرض طرق الحفاظ على الماء ص 50: الاستحمام بالرشاش، وإصلاح التسرب، وجمع مياه الأمطار.","student":"يختار طرقاً للحفاظ على الماء ويقترح طريقة أخرى.","eval":"النص ص 50."},{"time45":"10 د","time90":"20 د","teacher":"يعرض طرق الحفاظ على الطاقة ص 50: إطفاء الكهرباء، والمصابيح الموفرة، والمشي أو ركوب الدراجة، ومصابيح الطاقة الشمسية في الحدائق.","student":"يختار طرقاً لتوفير الطاقة ويقترح طريقة أخرى.","eval":"النص ص 50."}]},{"id":"sci6~2_9_o1","code":"6Be2","text":"يستكشف عدداً من طرق العناية بالبيئة: عدم رمي المخلفات وتشجيع الآخرين على العناية بالبيئة.","selected":true,"suffix":"","activities":[{"time45":"18 د","time90":"36 د","teacher":"ينفذ نشاط 2-9 (فرز القمامة): تجمع الثنائيات القمامة بقفازات وكمامات وتصنفها وتسجل أنواعها في جدول.","student":"يجمع القمامة ويسجل بالعلامات نوع كل قطعة.","eval":"نشاط 2-9 ص 51."},{"time45":"5 د","time90":"10 د","teacher":"يناقش «تحدث عن»: ماذا يمكنك أن تفعل في مجتمعك للتقليل من إلقاء القمامة؟ ويطرح فكرة حملة توعية وملصقات.","student":"يقترح حملة توعية ويصمم ملصقاً.","eval":"تحدث عن ص 51."}]},{"id":"sci6~2_9_o2","code":"6Ep4","text":"يتنبأ بما سيحدث بناءً على المعرفة العلمية والفهم (أكثر أنواع القمامة شيوعاً).","selected":true,"suffix":"","activities":[{"time45":"9 د","time90":"18 د","teacher":"يوجه اختيار موقع آمن وكتابة تنبؤ بأكثر أنواع القمامة شيوعاً مع السبب قبل الجمع.","student":"يكتب تنبؤه وسببه.","eval":"نشاط 2-9 ص 51."}]},{"id":"sci6~2_9_o3","code":"6Eo3","text":"يستخدم الجداول والتمثيل البياني بالأعمدة لعرض النتائج.","selected":true,"suffix":"","activities":[{"time45":"11 د","time90":"22 د","teacher":"يوجه رسم جدول بعمود لكل نوع (بلاستيك، ورق، معدن، زجاج، خشب، طعام، مخلفات حدائق) وتمثيل النتائج بالأعمدة بمقياس مناسب.","student":"يسجل في جدول ويرسم التمثيل البياني بالأعمدة.","eval":"نشاط 2-9 ص 51."}]},{"id":"sci6~2_9_o4","code":"6Eo4","text":"يعقد مقارنات (بين أنماط نتائج طلبة الصف).","selected":true,"suffix":"","activities":[{"time45":"5 د","time90":"10 د","teacher":"يطرح السؤال 2 ص 51: قارن الأنماط في نتائج الطلبة جميعاً وفسر الاختلاف.","student":"يقارن نتائجه بنتائج غيره.","eval":"السؤال 2 ص 51."}]},{"id":"sci6~2_9_o5","code":"6Eo6","text":"يحدّد الأنماط في النتائج والنتائج التي لا تبدو ملائمة للنمط.","selected":true,"suffix":"","activities":[{"time45":"5 د","time90":"10 د","teacher":"يوجه تحديد النمط في أنواع القمامة والنتائج التي لا تطابقه.","student":"يحدد النمط والاستثناء.","eval":"نتائج الصف."}]},{"id":"sci6~2_9_o6","code":"6Eo9","text":"يحدد ما إذا كانت الأدلة تدعم تنبؤاً ما، مبيناً كيف.","selected":true,"suffix":"","activities":[{"time45":"5 د","time90":"10 د","teacher":"يطرح السؤال 1 ص 51: هل الأدلة التي جمعتها تدعم تنبؤاتك؟","student":"يحدد هل دعمت النتائج تنبؤه ويوضح.","eval":"السؤال 1 ص 51."}]}],"prior":"إعادة التدوير والسماد (الدرس 2-8)؛ إزالة الغابات وتلوث الهواء (الدرسان 2-5 و2-6)؛ التمثيل البياني بالأعمدة","warmup":"في أي أعمالك اليومية تستهلك ماءً وكهرباء؟","resources":"كتاب الطالب (ص 50-51)، نشاط 2-9، تمرين 2-9 في كتاب النشاط، كيس قمامة كبير، دفتر ملاحظات وقلم رصاص، قفازات مطاطية، كمامات، ورق ملصقات وألوان.","strategies":["العصف الذهني","الحوار والمناقشة","التعلم التعاوني","التعلم الفردي"],"lab":"نشاط 2-9: فرز القمامة. تحتاج كل ثنائي إلى كيس قمامة كبير، ودفتر ملاحظات وقلم رصاص، وقفازات مطاطية، وكمامات. يحتاج النشاط حصة كاملة (وقتاً أطول إذا بعد الموقع). يُختار مكان فيه قدر معقول من القمامة وآمن (قرب شاطئ أو فلج أو ضفة وادٍ)، ويرتدي الطلبة القفازات والكمامات، ولا يُسمح بملامسة مخلفات الحقن أو الإبر، ويحذرون من الزجاج المكسور، ويرافقهم شخص بالغ. يُنبّه إلى أن القمامة البلاستيكية تخنق الحيوانات. يُسمح بنحو 30 دقيقة للتنظيف، وتُترك الأكياس السوداء في نقطة تجميع.","misconception":"يظن بعض الطلبة أن القمامة مشكلة الآخرين وأن تأثير الفرد ضئيل. التشخيص: يسأل المعلم هل نشارك في التلوث؟ المعالجة: يوضح تمرين 2-9 أن الجميع يشاركون في التلوث حتى دون أن يدركوا، وأن تغيير سلوك كل فرد يقلل التلوث.","exitTicket":"ماذا يمكنك أن تفعل في مجتمعك للتقليل من رمي القمامة؟","homework":"إكمال التمثيل البياني بالأعمدة لنتائج نشاط 2-9 وتبادل الدفاتر لتقييمه بالمعايير (المقياس، الرسم الدقيق، التسمية الدقيقة، عرض الأعمدة، العنوان)، وتنفيذ تمرين 2-9 في كتاب النشاط (استخدام موارد البيئة في الأسبوع الماضي).","guideAnswers":"<b>نشاط 2-9:</b> تعتمد الإجابات على استجابات الطلبة (التنبؤ، والأدلة، ومقارنة الأنماط).<br><b>تمرين 2-9:</b> يملأ الطلبة الجدول بدقة؛ وقد يجيب كثير منهم بـ «نعم» عن كل سؤال، والهدف التأكيد على أننا نشارك جميعاً في التلوث حتى دون أن ندرك، ثم يُناقش السؤالان 2 و3 في الصف."},"sci6~2_10":{"course":"sci6","sem":1,"unitNum":2,"unitTitle":"الوحدة الثانية: الكائنات الحية في البيئة","unitShort":"الكائنات الحية في البيئة","code":"2-10","title":"تحقق من تقدمك","defaultDuration":45,"objectives":[{"id":"sci6~2_10_o0","code":"6Be3-6","text":"يراجع السلاسل الغذائية: الكائن المنتج والمستهلك والمفترس والفريسة، ويرتب السلاسل في مواطن مختلفة.","selected":true,"suffix":"","activities":[{"time45":"12 د","time90":"24 د","teacher":"يعرض صورة الحديقة (السؤال 2 ص 52-53) ويطلب تحديد مصدر الطاقة والمنتجين والمستهلكين والمفترس وفريسته.","student":"يحدد الكائنات في الصورة ويكتب علاقاتها.","eval":"السؤال 2 ص 53."},{"time45":"13 د","time90":"26 د","teacher":"يطلب ترتيب الكائنات في السلاسل (السؤال 4) واختيار ثلاثة مفترسات وفرائسها (السؤال 5).","student":"يرتب السلاسل بأسهم صحيحة ويحدد المفترس والفريسة.","eval":"الأسئلة 4 و5 ص 53."}]},{"id":"sci6~2_10_o1","code":"6Be4","text":"يراجع أن السلاسل الغذائية تبدأ بالنباتات التي تستخدم الطاقة من الشمس، وأثر غياب الشمس أو الحشرات في بقية الكائنات.","selected":true,"suffix":"","activities":[{"time45":"10 د","time90":"20 د","teacher":"يطرح السؤال 3: ماذا يحدث إذا اختفت كل الحشرات؟ وإذا توقفت الشمس عن السطوع مدة طويلة؟","student":"يتنبأ ويفسر أثر غياب كائن أو الشمس في السلسلة.","eval":"السؤال 3 ص 53."}]},{"id":"sci6~2_10_o2","code":"6Be1","text":"يراجع الآثار السلبية للإنسان في البيئة: إزالة الغابات والاحتباس الحراري والأمطار الحمضية وتلوث الهواء.","selected":true,"suffix":"","activities":[{"time45":"8 د","time90":"16 د","teacher":"يوجه السؤال 6: لماذا تسهم إزالة الغابات في الاحتباس الحراري؟ وكيف تقتل الأمطار الحمضية الضفادع؟","student":"يفسر العلاقة بين السبب والأثر بجمل كاملة.","eval":"السؤال 6 ص 53."}]},{"id":"sci6~2_10_o3","code":"6Be2","text":"يراجع طرق العناية بالبيئة: إعادة الاستخدام وإعادة التدوير وصنع السماد وتوفير الماء والطاقة.","selected":true,"suffix":"","activities":[{"time45":"5 د","time90":"10 د","teacher":"يطرح السؤال 7: وصف كيفية إعادة استخدام أو تدوير علبة طعام من الألومنيوم وعلبة زجاجية وعلبة بلاستيكية وصندوق كرتوني.","student":"يصف طريقة إعادة استخدام كل مادة أو تدويرها.","eval":"السؤال 7 ص 53."},{"time45":"9 د","time90":"18 د","teacher":"يوجه المراجعة اللغوية في كتاب النشاط: ترتيب كلمات انتقال الطاقة، والفرق بين المفترس والفريسة، وإكمال الخرائط المفاهيمية.","student":"يكمل المراجعة اللغوية.","eval":"المراجعة اللغوية."}]}],"prior":"السلاسل الغذائية والمنتج والمستهلك والمفترس (الدروس 2-1 إلى 2-4)؛ إزالة الغابات وتلوث الهواء والأمطار الحمضية (الدروس 2-5 إلى 2-7)؛ إعادة التدوير والاعتناء بالبيئة (الدرسان 2-8 و2-9)","warmup":"ما الذي يتغذى عليه المفترس؟","resources":"كتاب الطالب (ص 52-53: تحقق من تقدمك)، المراجعة اللغوية في كتاب النشاط، بطاقات المصطلحات، سبورة وأقلام ملونة.","strategies":["الأسئلة السابرة","المقارنة والتصنيف","الحوار والمناقشة","التعلم التعاوني","التعلم الفردي"],"lab":"لا يوجد نشاط عملي. تُجهّز بطاقات المصطلحات وصورة الحديقة مسبقاً.","misconception":"يظن بعض الطلبة أن الحيوان الأعلى في السلسلة لا يعتمد على النباتات. التشخيص: يسأل المعلم ماذا يحدث للأسد إذا اختفى العشب؟ المعالجة: يتتبع الطلبة السلسلة ليتبين أن كل الكائنات تعتمد على المنتج وعلى الطاقة من الشمس.","exitTicket":"اذكر طريقة تحمي بها البيئة وسبب فعاليتها.","homework":"إكمال المراجعة اللغوية في كتاب النشاط (الخرائط المفاهيمية) ومراجعة مفردات الوحدة استعداداً للتقويم.","guideAnswers":"<b>تحقق من تقدمك:</b> (1) أ-3، ب-1، ج-4، د-5، هـ-2. (2) أ. الشمس. ب. نبات الملفوف والطماطم. ج. القطة والطائر والديدان والجراد. د. القطة (مفترس) ← الطائر (فريسة)؛ الطائر (مفترس) ← الديدان والجرادة (فريسة). (3) أ. تموت الطيور لعدم توفر الغذاء وبالتالي تموت القطط. ب. تختفي النباتات وتموت كل الكائنات. (4) أ. عشب ← ثور بري ← أسد. ب. عوالق ← سمكة ← نورس. ج. بذور ← خنفساء ← سحلية ← صقر. د. عوالق ← سمك صغير ← فقمة ← قرش. (5) مثال: الأسد (مفترس) والثور البري (فريسة)؛ النورس والسمكة؛ الفقمة والسمك الصغير؛ القرش والفقمة. (6) أ. ثاني أكسيد الكربون من الغازات الدفيئة المسببة للاحتباس الحراري، والأشجار تستهلكه فتقلل كميته في الهواء. ب. تتلف الأمطار الحمضية بيض الضفادع فلا يفقس. (7) علبة الألومنيوم: تُعاد للطهي أو تُوضع في حاوية التدوير؛ العلبة الزجاجية: توضع فيها الأزهار أو في حاوية التدوير؛ العلبة البلاستيكية: تُستخدم للتخزين أو للتدوير؛ الصندوق الكرتوني: يُستخدم للتخزين أو للتدوير.<br><b>المراجعة اللغوية:</b> (1) الشمس، كائن منتج، كائن مستهلك. (2) المفترس حيوان يتغذى على حيوان آخر يسمى فريسة. (3) الهواء: الربو، التهاب الشعب الهوائية، ضعف الرؤية، الأمطار الحمضية. إزالة الغابات: أنواع أقل من الأشجار، فقدان الحيوانات موطنها، الاحتباس الحراري، جفاف التربة. الحفاظ على البيئة: إعادة التدوير، إعادة الاستخدام، صنع السماد العضوي، تقليل الاستخدام."},"sci6~3_1":{"course":"sci6","sem":1,"unitNum":3,"unitTitle":"الوحدة الثالثة: تغيّرات المادة","unitShort":"تغيّرات المادة","code":"3-1","title":"التغيّرات القابلة للعكس والتغيّرات غير القابلة للعكس: أ. التغيّرات القابلة للعكس","defaultDuration":45,"objectives":[{"id":"sci6~3_1_o0","code":"6Cc1","text":"يميز بين التغيرات القابلة للعكس والتغيرات غير القابلة للعكس (التغير القابل للعكس: الانصهار والتجمد).","selected":true,"suffix":"","activities":[{"time45":"12 د","time90":"24 د","teacher":"يعرض مخطط ص 54: الثلج (صلب) ⇄ الماء (سائل) بالتسخين والتبريد ويكتب «قابل للعكس» على السبورة ويشرح معناه.","student":"يصف انصهار الثلج وتجمده ويفسر لماذا هو تغير قابل للعكس.","eval":"مخطط ص 54."},{"time45":"10 د","time90":"20 د","teacher":"يمزق ورقة ثم يلصقها، ويطلب تصنيف تغيرات الثلج والورقة وتمرين 3-1 (2).","student":"يصنف التغيرات ويقترح طريقة عكسها.","eval":"تمرين 3-1 (2)."}]},{"id":"sci6~3_1_o1","code":"6Ep6","text":"يحدّد العوامل المرتبطة بموقف محدد (الحرارة سبب تغير حالة الثلج).","selected":true,"suffix":"","activities":[{"time45":"8 د","time90":"16 د","teacher":"يسأل عن العامل الذي سبّب تغير الثلج ويقود الطلبة إلى أن الحرارة هي السبب.","student":"يحدد العامل المسبب للتغير.","eval":"نشاط 3-1."}]},{"id":"sci6~3_1_o2","code":"6Ep4","text":"يتنبأ بما سيحدث بناءً على المعرفة العلمية والفهم (هل يتجمد الماء الناتج في الثلاجة؟).","selected":true,"suffix":"","activities":[{"time45":"8 د","time90":"16 د","teacher":"يطلب كتابة تنبؤ: ماذا سيحدث للماء إذا وضع في الثلاجة ولماذا؟ ثم يناقش الملاحظات.","student":"يتنبأ ويفسر تنبؤه.","eval":"نشاط 3-1 ص 54."}]},{"id":"sci6~3_1_o3","code":"6Eo1","text":"يقوم بملاحظات متنوعة ذات صلة باستخدام أدوات بسيطة (ملاحظة تغيرات الثلج).","selected":true,"suffix":"","activities":[{"time45":"12 د","time90":"24 د","teacher":"يوجه ملاحظة الثلج في مكان دافئ لمدة خمس دقائق وتسجيل ما يحدث.","student":"يلاحظ الثلج ويسجل ما يحدث.","eval":"نشاط 3-1 (ملاحظة الأداء)."}]}],"prior":"حالات المادة: صلب وسائل وغاز (الصفان الرابع والخامس)؛ الانصهار والتجمد","warmup":"ماذا يحدث لمكعب ثلج تركناه في مكان دافئ؟","resources":"كتاب الطالب (ص 54)، نشاط 3-1، تمرين 3-1 في كتاب النشاط، مكعبات ثلج، صحون، ورقة ولاصق، سبورة.","strategies":["العصف الذهني","التعلم التعاوني","الأسئلة السابرة","الحوار والمناقشة","التعلم الفردي"],"lab":"نشاط 3-1: تحتاج كل مجموعة (4–5 طلاب) إلى مكعبات ثلج وصحن. يوضع الثلج في الشمس أو مكان دافئ فيبدأ بالانصهار خلال بضع دقائق، وقد ينصهر كله بعد خمس دقائق بحسب الحرارة. يتوقع الطلبة بحسب خبرتهم أن الحرارة تذيب الثلج وأن إعادته إلى الثلاجة تجمده.","misconception":"قد يعتقد بعض الطلبة أن الماء والثلج مادتان مختلفتان. التشخيص: يسأل المعلم: هل الثلج مادة جديدة؟ المعالجة: يذكّرهم بأن الثلج والماء حالتان مختلفتان للمادة نفسها، وأن الانصهار والتجمد تغيران في الحالة لا في نوع المادة.","exitTicket":"اذكر مثالاً على تغير قابل للعكس مع طريقة عكسه.","homework":"حل أسئلة 3-1 في كتاب الطالب ص 55 بعد استكمال الجزء الثاني من الدرس (في الحصتين التاليتين).","guideAnswers":"<b>تمرين 3-1 (2):</b> أ. قم بفك طي الورقة. ب. ضعها في مكان بارد. ج. ضعه في مكان دافئ.<br><b>نشاط 3-1:</b> يلاحظ الطلبة أن الثلج ينصهر بالحرارة ويعود صلباً بالتبريد."},"sci6~3_1b":{"course":"sci6","sem":1,"unitNum":3,"unitTitle":"الوحدة الثالثة: تغيّرات المادة","unitShort":"تغيّرات المادة","code":"3-1","title":"التغيّرات القابلة للعكس والتغيّرات غير القابلة للعكس: ب. التغيّرات غير القابلة للعكس","defaultDuration":45,"objectives":[{"id":"sci6~3_1b_o0","code":"6Cc1","text":"يميز بين التغيرات القابلة للعكس والتغيرات غير القابلة للعكس (الاحتراق وسلق البيض وخلط الخل ببيكربونات الصوديوم والجبس بالماء).","selected":true,"suffix":"","activities":[{"time45":"14 د","time90":"28 د","teacher":"يعرض احتراق عود الثقاب وورقة في صندوق الرمل ويشرح التغير غير القابل للعكس: لا يمكن إرجاع المادة إلى حالتها الأصلية، ويعرض خلط الجبس بالماء.","student":"يصنف التغيرات ويعلل بتكوّن مادة جديدة.","eval":"ص 55، ورقة العمل 3-1."},{"time45":"12 د","time90":"24 د","teacher":"يوجه الأسئلة 1–3 ص 55 وتمرين 3-1 (1): تصنيف خمسة تغيرات إلى قابل للعكس وغير قابل.","student":"يجيب عن الأسئلة ويصنف التغيرات.","eval":"الأسئلة 1–3 ص 55."}]},{"id":"sci6~3_1b_o1","code":"6Eo1","text":"يقوم بملاحظات متنوعة ذات صلة باستخدام أدوات بسيطة (الشمعة، الخل وبيكربونات الصوديوم).","selected":true,"suffix":"","activities":[{"time45":"15 د","time90":"30 د","teacher":"يشعل الشمعة ويضع ملعقة فوق اللهب ثم يوجه خلط الخل ببيكربونات الصوديوم وتسجيل الملاحظات.","student":"يلاحظ ويسجل ما يحدث.","eval":"ورقة العمل 3-1."}]},{"id":"sci6~3_1b_o2","code":"6Ep4","text":"يتنبأ بما سيحدث بناءً على المعرفة العلمية والفهم (ما المادة الجديدة الناتجة عن خلط الصودا بالخل؟).","selected":true,"suffix":"","activities":[{"time45":"5 د","time90":"10 د","teacher":"يطرح سؤال التحدي: ما المادة الجديدة؟ ويطلب اقتراح طريقة للتأكد.","student":"يتنبأ ويقترح طريقة اختبار.","eval":"سؤال التحدي ورقة العمل 3-1."}]}],"prior":"التغيرات القابلة للعكس: الانصهار والتجمد (الجزء أ)؛ حالات المادة","warmup":"هل يمكن إرجاع عود الثقاب المحترق إلى خشب؟","resources":"كتاب الطالب (ص 55)، ورقة العمل 3-1 وتمرين 3-1 في كتاب النشاط، شمعة وملعقة معدنية وأعواد ثقاب (للمعلم)، صندوق رمل، بيكربونات الصوديوم وخل وملعقة وكأس، جبس وماء وأعواد تحريك وأكواب.","strategies":["العصف الذهني","الحوار والمناقشة","التعلم التعاوني","الأسئلة السابرة","التعلم الفردي"],"lab":"ورقة العمل 3-1: المعلم وحده يشعل الشمعة وعود الثقاب، ويحرق الورقة في صندوق رمل، ويعرض الشمعة في حامل أو على طبق. يعمل الطلبة في مجموعات (4–5): يضعون ملعقتين صغيرتين من بيكربونات الصوديوم مع الكمية نفسها من الخل في كأس، فتخرج فقاعات ورغوة ويتكون ثاني أكسيد الكربون (لا يُذكر مسبقاً لأنه سؤال التحدي). عرض الجبس: مقداران من الجبس لمقدار من الماء؛ يُقاس الماء أولاً ثم يُضاف الجبس إلى الماء لا العكس؛ لا يُصب الجبس في البالوعة لأنه يتماسك ويسدها. يجوز تنفيذ نموذج بركان بالجبس وبيكربونات الصوديوم والخل للتكامل مع الفنون والمهارات الحياتية.","misconception":"قد يظن الطلبة أن تسخين أي مادة يحرقها. التشخيص: يسأل المعلم هل يحترق كل ما نسخنه؟ المعالجة: كثير من المواد ينصهر عند تسخينه كالمعادن، والاحتراق تغير كيميائي يحتاج إلى الأكسجين؛ فالورق يحترق بسهولة والرمل لا يحترق.","exitTicket":"اذكر مثالاً على تغير غير قابل للعكس ينتج مادة جديدة.","homework":"حل أسئلة 3-1 كاملة في كتاب الطالب ص 55، وتمرين 3-1 السؤال 1 في كتاب النشاط (تصنيف خمسة تغيرات).","guideAnswers":"<b>أسئلة 3-1 (كتاب الطالب):</b> (1) نجعل الجيلي الصلب سائلاً بالتسخين (والتبريد يعيده صلباً). (2) أ. تغير غير قابل للعكس، لأن بياض البيض وصفاره يتحولان من سائل إلى صلب ولا يعودان سائلين. ب. نعم، تنتج مادة جديدة. (3) إجابات الطلبة، كحرق الخشب أو خلط الإسمنت.<br><b>تمرين 3-1 (1):</b> أ. قابل للعكس. ب. غير قابل. ج. قابل. د. غير قابل. هـ. غير قابل.<br><b>ورقة العمل 3-1:</b> (1) أ. انصهار الشمع. ب. احتراق الفتيل. (2) أ. فقاعات ورغوة. ب. نعم. ج. نعم. د. لا، لأن المادتين تغيرتا وتشكلت مادة جديدة. التحدي: ثاني أكسيد الكربون، ويُختبر بماء الجير الذي يتعكر."},"sci6~3_2":{"course":"sci6","sem":1,"unitNum":3,"unitTitle":"الوحدة الثالثة: تغيّرات المادة","unitShort":"تغيّرات المادة","code":"3-2","title":"خلط المواد الصلبة وفصلها: أ. المخاليط","defaultDuration":45,"objectives":[{"id":"sci6~3_2_o0","code":"6Cc2","text":"يستكشف كيف يمكن خلط المواد الصلبة (المخلوط مادتان أو أكثر تمتزجان دون تفاعل كيميائي ويسهل فصلهما).","selected":true,"suffix":"","activities":[{"time45":"10 د","time90":"20 د","teacher":"يعرض كيس فاصوليا متنوعة ويشرح ص 56 أن المخلوط يتكون من مادتين أو أكثر غير مرتبطتين كيميائياً، ومنه الهواء.","student":"يشرح معنى المخلوط ويذكر أمثلة.","eval":"ص 56."},{"time45":"15 د","time90":"30 د","teacher":"ينفذ نشاط 3-2أ: تصنع المجموعات أربعة مخاليط وتحرك كل مخلوط وتلاحظ.","student":"يصنع المخاليط ويلاحظ حالة المواد.","eval":"نشاط 3-2أ ص 56."},{"time45":"8 د","time90":"16 د","teacher":"يوضح أن الهواء مخلوط من غازات لا تُرى ويمكن إثبات وجودها.","student":"يعلل لماذا الهواء مخلوط.","eval":"ص 56."},{"time45":"5 د","time90":"10 د","teacher":"يوجه تمرين 3-2 (1): صح أم خطأ عن المخاليط.","student":"يحدد الصحيح والخطأ.","eval":"تمرين 3-2 (1)."}]},{"id":"sci6~3_2_o1","code":"6Eo4","text":"يعقد مقارنات (بين المخاليط الأربعة: هل تُرى المواد؟ وهل تغيرت حالتها؟).","selected":true,"suffix":"","activities":[{"time45":"5 د","time90":"10 د","teacher":"يطلب مقارنة المخاليط الأربعة وتحديد ما يمكن رؤيته في كل منها.","student":"يقارن بين المخاليط.","eval":"نشاط 3-2أ."}]},{"id":"sci6~3_2_o2","code":"6Ep4","text":"يتنبأ بما سيحدث بناءً على المعرفة العلمية والفهم (أنسب طريقة لفصل مخلوط).","selected":true,"suffix":"","activities":[{"time45":"5 د","time90":"10 د","teacher":"يسأل كيف نفصل الحصى عن التربة ولماذا ويطلب تعليل الاختيار.","student":"يتنبأ بطريقة الفصل ويعلل.","eval":"ص 57."}]}],"prior":"التغيرات القابلة للعكس وغير القابلة للعكس (الدرس 3-1)؛ حالات المادة","warmup":"لماذا يُعد كيس الفاصوليا المتنوعة مخلوطاً؟","resources":"كتاب الطالب (ص 56-57)، نشاط 3-2أ، تمرين 3-2 في كتاب النشاط، ملاعق، أرز ودقيق وملح ورمل وسكر وأوراق شاي وفاصوليا وخرز ملون، كيس فاصوليا متنوعة، غربال.","strategies":["العصف الذهني","الحوار والمناقشة","التعلم التعاوني","الأسئلة السابرة","التعلم الفردي"],"lab":"نشاط 3-2أ: تعمل كل مجموعة (4–5 طلاب). تُكوَّن المخاليط: الأرز مع الدقيق، الملح مع الرمل، أوراق الشاي مع السكر، الفاصوليا مع الخرز الملون. يُستخدم نحو 20 جم من كل مادة، وفي مخلوط الفاصوليا والخرز نحو 15 حبة من كل نوع. يُقلب كل مخلوط أو يُرج لخلط المواد.","misconception":"قد يجد بعض الطلبة صعوبة في تقبل أن الهواء مخلوط، فيظنون أن ما لا تُرى مكوناته ليس مخلوطاً. التشخيص: يسأل المعلم هل الهواء مادة واحدة؟ المعالجة: يذكّرهم بأننا لا نرى الهواء ولذلك لا نرى غازاته، ويمكن إثبات وجود الأكسجين (توهج شظية) وثاني أكسيد الكربون (تعكر ماء الجير).","exitTicket":"اذكر طريقتين لفصل مخلوط من مواد صلبة.","homework":"إكمال تمرين 3-2 (1) في كتاب النشاط، ثم التحضير للنشاط 3-2ب (اختيار طرق الفصل) في الحصة التالية.","guideAnswers":"<b>تمرين 3-2 (1):</b> أ. خطأ. ب. صح. ج. صح. د. خطأ. هـ. صح. و. خطأ.<br><b>نشاط 3-2أ:</b> لا تتغير حالة المواد عند تحريكها، فالمكونات لم تتفاعل مع بعضها."},"sci6~3_2b":{"course":"sci6","sem":1,"unitNum":3,"unitTitle":"الوحدة الثالثة: تغيّرات المادة","unitShort":"تغيّرات المادة","code":"3-2","title":"خلط المواد الصلبة وفصلها: ب. فصل المخاليط الصلبة","defaultDuration":45,"objectives":[{"id":"sci6~3_2b_o0","code":"6Cc2","text":"يستكشف كيف يمكن فصل مخاليط المواد الصلبة مرة أخرى (الفرز، الغربلة، المغناطيس، التبخر).","selected":true,"suffix":"","activities":[{"time45":"20 د","time90":"40 د","teacher":"ينفذ نشاط 3-2ب: تختار المجموعات طريقة فصل كل مخلوط وتفصله، ويقدم التبخر والمغناطيس.","student":"يفصل المخاليط بالطريقة المناسبة.","eval":"نشاط 3-2ب ص 57."},{"time45":"10 د","time90":"20 د","teacher":"يناقش فصل الملح والرمل بالتبخر وفصل الحديد عن الخردة بالمغناطيس (تحدث عن).","student":"يشرح طريقة فصل الملح والحديد.","eval":"ص 57."}]},{"id":"sci6~3_2b_o1","code":"6Ep7","text":"يختار الأدوات التي يجب استخدامها (الغربال، المغناطيس، الملعقة).","selected":true,"suffix":"","activities":[{"time45":"10 د","time90":"20 د","teacher":"يحدد الأدوات اللازمة لكل مجموعة ويراجع اختيارها قبل الفصل.","student":"يختار أداة مناسبة لكل مخلوط ويعلل.","eval":"نشاط 3-2ب وورقة العمل 3-2."}]},{"id":"sci6~3_2b_o2","code":"6Ep4","text":"يتنبأ بما سيحدث بناءً على المعرفة العلمية والفهم (أفضل طريقة لفصل مخاليط معينة).","selected":true,"suffix":"","activities":[{"time45":"6 د","time90":"12 د","teacher":"يوجه السؤال 3 ص 57: تنبؤ بأفضل طريقة لفصل ثلاثة مخاليط مع السبب.","student":"يتنبأ مع التعليل.","eval":"السؤال 3 ص 57."}]},{"id":"sci6~3_2b_o3","code":"6Eo4","text":"يعقد مقارنات (بين طرق فصل الجزيئات الكبيرة والصغيرة).","selected":true,"suffix":"","activities":[{"time45":"8 د","time90":"16 د","teacher":"يوجه السؤالين 1 و2 ص 57: مخلوط لم نستطع فصله، وأفضل الطرق لفصل الجزيئات الكبيرة والصغيرة.","student":"يقارن بين طرق الفصل.","eval":"السؤالان 1 و2 ص 57."}]},{"id":"sci6~3_2b_o4","code":"6Eo3","text":"يستخدم الجداول لعرض النتائج (جدول المخلوط وطريقة الفصل).","selected":true,"suffix":"","activities":[{"time45":"12 د","time90":"24 د","teacher":"يوجه تسجيل المخلوط وطريقة فصله في جدول ورقة العمل 3-2.","student":"يسجل في الجدول.","eval":"ورقة العمل 3-2."}]}],"prior":"معنى المخلوط وأمثلته (الجزء أ)؛ المواد المغناطيسية (الصف الرابع)","warmup":"كيف نفصل حبات الفول السوداني عن الزبيب؟","resources":"كتاب الطالب (ص 57)، نشاط 3-2ب، ورقة العمل 3-2، تمرين 3-2، رمل وبرادة حديد أو دبابيس، فول، دقيق، أرز، كؤوس زجاجية، غربال، مغناطيس، وعاء، مخبار مدرج أو ملعقة.","strategies":["العصف الذهني","الحوار والمناقشة","التعلم التعاوني","التعلم الفردي"],"lab":"نشاط 3-2ب: يحدد المعلم لكل مجموعة (4–5 طلاب) الأدوات اللازمة: كؤوس زجاجية، إناء عميق، غربال، مغناطيس. ورقة العمل 3-2: رمل مع برادة حديد أو دبابيس، فول مع دقيق، فول مع أرز، نحو 20 جم من كل مادة وعشر دبابيس. السلامة: عند استعمال برادة الحديد يتجنب الطلبة لمس الوجه والعينين قبل غسل اليدين لأن لها حواف حادة؛ وعند استعمال الدبابيس يحذرون من التقاطها باليد من المخلوط.","misconception":"قد يظن الطلبة أن جميع المعادن ينجذب إلى المغناطيس. التشخيص: يسأل المعلم هل يجذب المغناطيس النحاس أو الألمنيوم؟ المعالجة: الحديد والمواد التي تحتوي عليه فقط تنجذب إلى المغناطيس.","exitTicket":"اذكر مخلوطاً صلباً وطريقة مناسبة لفصله.","homework":"تمرين 3-2 في كتاب النشاط (السؤال 2) إن لم يكتمل، وفي الحصة التالية يناقش الصف الإجابات ويتحقق الطلبة من أعمال بعضهم.","guideAnswers":"<b>نشاط 3-2ب:</b> لا يمكن فصل الملح والرمل بالغربلة أو الفرز لأن حبيباتهما صغيرة وبحجم متقارب.<br><b>أسئلة 3-2:</b> (1) نعم، الملح والرمل. (2) أ. الفرز. ب. الغربلة. (3) أ. الفول السوداني والفاصوليا: الفرز لأن الحبيبات كبيرة ولن تمر من الغربال. ب. الملح وفتات الخبز: الغربلة لأن الملح يمر من الثقوب وفتات الخبز لا يمر. ج. البازلاء والدقيق: الغربلة لأن الدقيق يمر والبازلاء لا تمر.<br><b>تمرين 3-2 (2):</b> أ. رسم مخلوط الرمل والكرات الزجاجية مع البيانات. ب. بالفرز. ج. بالغربلة.<br><b>ورقة العمل 3-2:</b> رمل مع برادة الحديد أو دبابيس: مغناطيس. الفول مع الدقيق: الغربلة. الفول مع الأرز: الفرز."},"sci6~3_3":{"course":"sci6","sem":1,"unitNum":3,"unitTitle":"الوحدة الثالثة: تغيّرات المادة","unitShort":"تغيّرات المادة","code":"3-3","title":"المواد القابلة للذوبان والمواد غير القابلة للذوبان","defaultDuration":45,"objectives":[{"id":"sci6~3_3_o0","code":"6Cc3","text":"يصف ويبدأ بشرح التغيرات التي تحدث عند إضافة بعض المواد الصلبة إلى الماء.","selected":true,"suffix":"","activities":[{"time45":"10 د","time90":"20 د","teacher":"يقدم معنى الذوبان بمثال القهوة والماء الساخن ويشرح مصطلحي «قابل للذوبان» و«غير قابل للذوبان».","student":"يشرح بكلماته معنى الذوبان.","eval":"ص 58."},{"time45":"22 د","time90":"44 د","teacher":"ينفذ نشاط 3-3: تضاف ملعقة صغيرة من كل مادة صلبة إلى 100 مل ماء وتحرك ثم تلاحظ بعد خمس دقائق.","student":"يضيف المواد ويصف ما يحدث.","eval":"نشاط 3-3 ص 58."},{"time45":"10 د","time90":"20 د","teacher":"يناقش الأسئلة 1–4 ص 59 وورقة العمل 3-3.","student":"يجيب عن الأسئلة ويفسر.","eval":"الأسئلة 1–4 ص 59."}]},{"id":"sci6~3_3_o1","code":"6Cc5","text":"يستكشف كيفية ذوبان بعض المواد الصلبة في الماء لتشكل محاليل، وأنها لا تزال موجودة وإن لم تعد مرئية.","selected":true,"suffix":"","activities":[{"time45":"12 د","time90":"24 د","teacher":"يشرح المحلول المعلق (مادة غير قابلة للذوبان تظل مرئية وتستقر أو تطفو) ويوضح أن المادة الذائبة موجودة (طعم الملح).","student":"يفرق بين المحلول الصافي والمعلق.","eval":"ص 59."}]},{"id":"sci6~3_3_o2","code":"6Eo1","text":"يقوم بملاحظات متنوعة ذات صلة باستخدام أدوات بسيطة (شفاف أم ضبابي؟ هل تُرى المادة؟).","selected":true,"suffix":"","activities":[{"time45":"12 د","time90":"24 د","teacher":"يوجه ملاحظة المخاليط وقياس 100 مل من الماء بالمخبار المدرج.","student":"يلاحظ ويسجل ما يراه.","eval":"نشاط 3-3 وورقة العمل 3-3."}]},{"id":"sci6~3_3_o3","code":"6Eo3","text":"يستخدم الجداول والتمثيل لعرض النتائج (جدول التنبؤ والملاحظة والاستنتاج).","selected":true,"suffix":"","activities":[{"time45":"10 د","time90":"20 د","teacher":"يوجه رسم جدول فيه المادة والتنبؤ والملاحظة والاستنتاج وتسجيل النتائج.","student":"يسجل النتائج في الجدول.","eval":"جدول نشاط 3-3."}]}],"prior":"الذوبان (الصفان الثاني والخامس)؛ المخاليط وفصلها (الدرس 3-2)","warmup":"ماذا يحدث لملعقة سكر نضعها في كوب ماء ونحركها؟","resources":"كتاب الطالب (ص 58-59)، نشاط 3-3، تمرين 3-3 وورقة العمل 3-3 في كتاب النشاط، مخبار مدرج، كؤوس زجاجية، ملاعق صغيرة، ماء نظيف، ملح ودقيق ورمل وبرمنجنات البوتاسيوم، مسحوق شراب بارد، فلفل، طباشير أو بودرة تلك، ملاقط.","strategies":["العصف الذهني","الحوار والمناقشة","التعلم التعاوني","الأسئلة السابرة","التعلم الفردي"],"lab":"نشاط 3-3: تحتاج كل مجموعة (4–5 طلاب) إلى مخبار مدرج وكؤوس زجاجية وملاعق صغيرة وماء نظيف ومواد صلبة (ملح، دقيق، رمل، برمنجنات البوتاسيوم أو بلورات كبريتات النحاس). السلامة: برمنجنات البوتاسيوم ضارة؛ يُمنع تذوق المحلول أو ابتلاعه ولمس البلورات باليد، ويُستخدم الملقط، ومن لمس البلورات يغسل يديه فوراً ولا يلمس عينيه (وكذلك كبريتات النحاس). ورقة العمل 3-3: يجهز المعلم المخاليط ويخبر الطلبة بمحتوى كل منها، بملعقة صغيرة من كل مادة في 100 مل ماء. عرض اختياري: ملعقة صغيرة من حبيبات هيدروكسيد الصوديوم في 100 مل ماء يلمس الطلبة الكأس فيشعرون بالحرارة (المعلم وحده يتعامل مع المادة).","misconception":"يظن بعض الطلبة أن المادة الصلبة تختفي عند ذوبانها. التشخيص: يسأل المعلم أين ذهب السكر؟ المعالجة: يذيب ملحاً أو سكراً في الماء ويطلب تذوق المحلول فيكون مالحاً أو حلواً فيتبين أن المادة موجودة (لا يتذوق إلا الملح والسكر). وقد يخلطون بين التغير الفيزيائي والكيميائي: عند الذوبان لا تتكون مادة جديدة.","exitTicket":"اذكر مادة قابلة للذوبان في الماء وأخرى غير قابلة.","homework":"تمرين 3-3 في كتاب النشاط: إكمال العبارات (الذوبان، القابلة، غير القابلة) وتحليل نتائج المخاليط (أ) و(ب) و(ج).","guideAnswers":"<b>نشاط 3-3 (الأسئلة):</b> (1) أ. المواد الصلبة في المخاليط الضبابية لم تختلط بالماء ويمكن رؤيتها. ب. المواد الصلبة في المخاليط الشفافة اختلطت بالماء ولا يمكن رؤيتها. (2) أ. لم يحدث تغير في المخاليط الشفافة واستقرت المواد الصلبة في قاع المخاليط الضبابية. ب. المواد في المخاليط الشفافة ذابت، والمواد في الضبابية غير قابلة للذوبان فاستقرت جزيئاتها الكبيرة في القاع. (3) يذوب الملح وبلورات برمنجنات البوتاسيوم، والإجابة (نعم/لا) حسب تنبؤات الطلبة. (4) للتأكد من أن الاختبار عادل.<br><b>تمرين 3-3:</b> (1) تذوب؛ المادة القابلة للذوبان؛ المادة غير القابلة للذوبان. (2) أ. المخلوط (ب) يحتوي على مواد قابلة للذوبان لأن السائل شفاف ولم تترسب في القاع أية مواد صلبة. ب. المخلوطان (أ) و(ج) فيهما مواد غير قابلة للذوبان: السائل ضبابي وتوجد مواد صلبة مترسبة في القاع.<br><b>ورقة العمل 3-3:</b> أ. الملح ومسحوق الشراب البارد والبرمنجنات: ذابت ولم تُرَ المادة وتلوّن السائل بلونها. أ. غير القابلة: الفلفل والتلك أو الطباشير: الفلفل والتلك يطفوان والطباشير يستقر في القاع. ج. محلول معلق."},"sci6~3_4":{"course":"sci6","sem":1,"unitNum":3,"unitTitle":"الوحدة الثالثة: تغيّرات المادة","unitShort":"تغيّرات المادة","code":"3-4","title":"فصل المواد غير القابلة للذوبان: أ. الترشيح ونشاط القهوة","defaultDuration":45,"objectives":[{"id":"sci6~3_4_o0","code":"6Cc4","text":"يستكشف كيف يمكن فصل المواد الصلبة بالترشيح الذي يشبه الغربلة، حين لا تذوب المادة ولا تتفاعل مع الماء (أستطيع أن أصف كيف يمكن فصل المواد غير القابلة للذوبان في الماء).","selected":true,"suffix":"","activities":[{"time45":"10 د","time90":"20 د","teacher":"يعرض ورقة الترشيح ويعرّف الترشيح: طريقة لفصل المواد غير القابلة للذوبان عن المادة السائلة؛ ثقوبها أدق من ثقوب الغربال (ص 60).","student":"يعرّف الترشيح ويقارنه بالغربلة.","eval":"ص 60."},{"time45":"5 د","time90":"10 د","teacher":"يعيد عبارة «أستطيع أن» ويسأل هل تحققت بعد نشاط القهوة.","student":"يقيّم تحقق «أستطيع أن».","eval":"عبارة «أستطيع أن»."}]},{"id":"sci6~3_4_o1","code":"6Ep4","text":"يتنبأ بما سيحدث بناءً على المعرفة العلمية والفهم (ماذا لو كانت جزيئات القهوة أصغر من فتحات الغربال؟ ماذا يمر وماذا يبقى؟).","selected":true,"suffix":"","activities":[{"time45":"8 د","time90":"16 د","teacher":"يطرح سؤال «ماذا لو» عن جزيئات القهوة الصغيرة جداً ويطلب كتابة تنبؤ بما سينزل وما سيبقى قبل الترشيح.","student":"يتنبأ ويفسر تنبؤه.","eval":"سؤال «ماذا لو» + تنبؤ نشاط القهوة."}]},{"id":"sci6~3_4_o2","code":"6Eo1","text":"يقوم بملاحظات وقياسات ذات صلة باستخدام أدوات بسيطة (طي ورقة الترشيح، ملاحظة ما ينزل وما يبقى).","selected":true,"suffix":"","activities":[{"time45":"12 د","time90":"24 د","teacher":"يوضح طي ورقة الترشيح وتبليلها ووضعها في القمع، ويجهز المجموعات بالمواد.","student":"يطوي ورقة الترشيح ويضعها في القمع.","eval":"طي الورقة (دليل المعلم)."},{"time45":"10 د","time90":"20 د","teacher":"ينفذ الطلبة الترشيح ويسجلون الملاحظتين: الماء ينزل إلى الكأس، والقهوة تترسب في ورقة الترشيح.","student":"يرشح ويسجل ملاحظاته في كراس العلوم.","eval":"نشاط القهوة (ملاحظة الأداء)."}]},{"id":"sci6~3_4_o3","code":"6Ep5","text":"يقترح ويقيّم تفسيرات للتنبؤات باستخدام المعرفة العلمية والفهم ويوصلها للآخرين بوضوح.","selected":true,"suffix":"","activities":[{"time45":"5 د","time90":"10 د","teacher":"يطلب تفسير المجموعات: لماذا نزل الماء وبقيت القهوة؟ (حجم الجزيئات وثقوب الورقة).","student":"يفسر ويعرض تفسيره.","eval":"التفسير (السبب)."}]},{"id":"sci6~3_4_o4","code":"6Eo7","text":"يستخدم النتائج لاستخلاص الاستنتاجات (الترشيح يفصل المادة غير القابلة للذوبان عن السائل).","selected":true,"suffix":"","activities":[{"time45":"5 د","time90":"10 د","teacher":"يوجه كتابة الاستنتاج في كراس العلوم.","student":"يكتب استنتاجه.","eval":"الاستنتاج."}]}],"prior":"المحلول المعلق: مادة غير قابلة للذوبان + سائل (الدرس 3-3)؛ الغربلة وفصل المخاليط (الدرس 3-2)","warmup":"كيف نصفّي القهوة العُمانية بعد غليها؟","resources":"كتاب الطالب (ص 60)، ورقة عمل Science Coffee، غربال، ورقة ترشيح، قمع ترشيح، كؤوس زجاجية، مخبار مدرج، قهوة مطحونة، ماء، كراس العلوم.","strategies":["العصف الذهني","الأسئلة السابرة","الحوار والمناقشة","التعلم التعاوني"],"lab":"نشاط Science Coffee (نشاط المعلم الجماعي): تحتاج كل مجموعة (4–5 طلاب) إلى مخلوط معلق من الماء والقهوة المطحونة، وكؤوس، وأقماع، وأوراق ترشيح، وورقة عمل. تُطوى ورقة الترشيح نصفين ثم نصفين، ثم تُفتح مخروطاً فيه ثلاث طبقات من جانب وطبقة من الآخر، وتُبلَّل قبل وضعها في القمع لتلتصق به وتسرع الترشيح. يوضع القمع فوق كأس ويصب المخلوط بهدوء. الماء النازل قد يكون بنياً لأن جزءاً من القهوة يذوب.","misconception":"قد يظن الطلبة أن الترشيح يزيل كل ما في السائل. التشخيص: يسأل المعلم لماذا لون الماء النازل بني؟ المعالجة: المواد الذائبة تتفتت إلى أجزاء متناهية الصغر تمر من ثقوب ورقة الترشيح، فالترشيح يفصل المواد غير القابلة للذوبان فقط.","exitTicket":"ما الترشيح ولماذا تبقى القهوة على الورقة؟","homework":"كتابة تعريف الترشيح ورسم جهاز الترشيح مع البيانات في كراس العلوم، وكتابة تنبؤ: ماذا يحدث لو رشحنا ماءً مالحاً؟","guideAnswers":"<b>نشاط Science Coffee (خطة المعلم):</b> الملاحظات: (1) الماء ينزل إلى الكأس. (2) تترسب القهوة في ورقة الترشيح. التفسير: جزيئات الماء صغيرة تمر من ثقوب ورقة الترشيح، وحبيبات القهوة غير القابلة للذوبان أكبر فلا تمر. الاستنتاج: الترشيح طريقة لفصل المواد غير القابلة للذوبان عن المادة السائلة.<br><b>أجزاء الجهاز:</b> قمع، ورقة ترشيح، كأس."},"sci6~3_4b":{"course":"sci6","sem":1,"unitNum":3,"unitTitle":"الوحدة الثالثة: تغيّرات المادة","unitShort":"تغيّرات المادة","code":"3-4","title":"فصل المواد غير القابلة للذوبان: ب. نشاط الكتاب والتطبيقات","defaultDuration":45,"objectives":[{"id":"sci6~3_4b_o0","code":"6Cc4","text":"يستكشف كيف يمكن فصل المواد الصلبة عن السوائل بالترشيح حين لا تذوب.","selected":true,"suffix":"","activities":[{"time45":"12 د","time90":"24 د","teacher":"ينفذ نشاط 3-4: ترشيح مخاليط الملح والدقيق والطباشير مع الماء وملاحظة ما يبقى على الورقة وما يمر.","student":"يرشح المخاليط ويلاحظ الناتج.","eval":"نشاط 3-4 ص 61."},{"time45":"7 د","time90":"14 د","teacher":"يوضح المرشح الرملي (حصى ثم رمل خشن ثم ناعم) والأراضي الرطبة، وسبب عدم صلاحية الماء المرشح للشرب قبل الغلي أو التعقيم.","student":"يفسر طبقات المرشح الرملي.","eval":"ص 60."},{"time45":"5 د","time90":"10 د","teacher":"يوجه تمرين 3-4: رسم أدوات التنقية وتسمية الطريقة وتفسير فائدتها.","student":"يرسم ويكتب البيانات.","eval":"تمرين 3-4 ص 41."}]},{"id":"sci6~3_4b_o1","code":"6Cc3","text":"يصف ويبدأ بشرح التغيرات التي تحدث عند إضافة بعض المواد الصلبة إلى الماء (ذائبة أم معلقة).","selected":true,"suffix":"","activities":[{"time45":"8 د","time90":"16 د","teacher":"يجهز المخاليط ويطلب تنبؤاً مكتوباً بما سيمر وما سيبقى لكل مخلوط.","student":"يجهز المخاليط ويتنبأ.","eval":"جدول التنبؤات."},{"time45":"10 د","time90":"20 د","teacher":"يطرح الأسئلة 1–3 ص 61: ما بقي على الورقة، وما مر، وهل نفصل المحلول بالترشيح؟","student":"يصف ما بقي وما مر ويفسر.","eval":"الأسئلة 1–3 ص 61."}]},{"id":"sci6~3_4b_o2","code":"6Eo1","text":"يقوم بملاحظات وقياسات ذات صلة باستخدام أدوات بسيطة (الترشيح وقياس الماء).","selected":true,"suffix":"","activities":[{"time45":"10 د","time90":"20 د","teacher":"يوجه تسجيل ملاحظات ما بقي على الورقة وما مر إلى الكأس لكل مخلوط.","student":"يسجل الملاحظات في جدول.","eval":"جدول الملاحظات."}]},{"id":"sci6~3_4b_o3","code":"6Ep5","text":"يقترح ويقيّم تفسيرات للتنبؤات باستخدام المعرفة العلمية والفهم ويوصلها للآخرين بوضوح.","selected":true,"suffix":"","activities":[{"time45":"10 د","time90":"20 د","teacher":"يطرح السؤال 4 ص 61 (تنبؤ ترشيح الدقيق والماء) والتطبيقات الأربعة: الكمامة، القهوة المقطّرة، منقار الفلامنجو، أكياس الشاي.","student":"يفسر كل تطبيق بحجم الجزيئات وثقوب المرشح.","eval":"السؤال 4 + تحدث عن ص 61."}]},{"id":"sci6~3_4b_o4","code":"6Eo7","text":"يستخدم النتائج لاستخلاص الاستنتاجات وتقديم المزيد من التنبؤات (فصل الملح عن الرمل).","selected":true,"suffix":"","activities":[{"time45":"8 د","time90":"16 د","teacher":"يطرح النشاط الختامي الفردي (سؤال التحدي): كيف يمكن فصل مخلوط الملح والرمل؟ ويربطه بالتبخر.","student":"يخطط لفصل الملح عن الرمل ويكتب الخطوات.","eval":"النشاط الختامي + التحدي ص 61."}]}],"prior":"معنى الترشيح ونشاط القهوة (الجزء أ)؛ المواد القابلة للذوبان وغير القابلة (الدرس 3-3)","warmup":"هل يبقى الملح على ورقة الترشيح إذا رشحنا ماءً مالحاً؟","resources":"كتاب الطالب (ص 60–61)، نشاط 3-4، تمرين 3-4 في كتاب النشاط، ملح ودقيق وطباشير، ورقة ترشيح، قمع، كؤوس زجاجية، مخبار مدرج، ملعقة صغيرة، كيس شاي، صور الكمامة وماكينة القهوة ومنقار الفلامنجو.","strategies":["العصف الذهني","التعلم التعاوني","التعلم الفردي","الحوار والمناقشة","الأسئلة السابرة"],"lab":"نشاط 3-4: تكوّن كل مجموعة (4–5) المخاليط: ملح وماء، دقيق وماء، طباشير وماء، بملعقة صغيرة (نحو 5 جم) من المادة و100 مل ماء. توضع ورقة الترشيح المطوية والمبللة في القمع فوق كأس نظيف. يتأكد المعلم من أن المجموعات تطوي الورقة وتجهزها بشكل صحيح، فهي بلا طيات في الأصل ثم تُطوى نصفين مرتين وتفتح مخروطاً. يُغسل القمع بين مخلوط وآخر.","misconception":"قد يظن الطلبة أن الترشيح يفصل الملح عن الماء. التشخيص: يسأل المعلم هل يبقى الملح على الورقة؟ المعالجة: المواد الذائبة لا تنفصل بالغربلة أو الفرز أو الترشيح لأنها تتفتت إلى أجزاء متناهية الصغر تمر من الثقوب؛ ويستعاد الملح بتبخير الماء.","exitTicket":"اذكر مادة تبقى على ورقة الترشيح ومادة تمر منها.","homework":"التمرين 3-4 في كتاب النشاط (إن لم يكتمل)، وكتابة خطوات فصل الملح والرمل ومثالين على التطبيقات اليومية للترشيح في كراس العلوم.","guideAnswers":"<b>نشاط 3-4:</b> (1) المادة الصلبة. (2) الماء الذي مر من خلال ورقة الترشيح، لأن جزيئات الماء صغيرة بما يكفي لتمر من الثقوب. (3) لا، لأن جزيئات المادة الصلبة تذوب وتصبح جزءاً من السائل. (4) أ. يتبقى الدقيق على ورقة الترشيح. ب. الدقيق مادة غير قابلة للذوبان فلا تمر عبر الثقوب لأن جزيئاتها كبيرة.<br><b>التحدي (النشاط الختامي):</b> نضيف كمية كافية من الماء ونحرك الملح والرمل حتى يذوب الملح تماماً، ثم نرشح فيمر الماء والملح ويبقى الرمل في الأعلى، وأخيراً نسخن الماء فوق مصدر حرارة ليتبخر فيترسب الملح في قاع الإناء.<br><b>تحدث عن:</b> في أوراق الشاي مواد قابلة للذوبان تذوب عندما يوضع الكيس في الماء الساخن وتمنح الشاي اللون والنكهة، وأوراق الشاي غير قابلة للذوبان وكبيرة جداً على المرور عبر ثقوب الكيس الذي يعمل مرشحاً.<br><b>تمرين 3-4:</b> أ. الترشيح. ب. المواد غير القابلة للذوبان كالرمل تكون كبيرة فلا تمر عبر الثقوب وتظل على ورقة الترشيح بينما تمر المواد القابلة للذوبان.<br><b>ملاحظة:</b> الماء بعد الترشيح أنظف لكنه غير صالح للشرب قبل الغلي أو التعقيم."},"sci6~3_5":{"course":"sci6","sem":1,"unitNum":3,"unitTitle":"الوحدة الثالثة: تغيّرات المادة","unitShort":"تغيّرات المادة","code":"3-5","title":"المحاليل: أ. المذاب والمذيب والمخلوط","defaultDuration":45,"objectives":[{"id":"sci6~3_5_o0","code":"6Cc5","text":"يستكشف كيفية ذوبان بعض المواد الصلبة في الماء لتشكل محاليل، وأن المادة الصلبة وإن لم تعد مرئية فهي لا تزال موجودة (المحلول، المذاب، المذيب، المظهر المتجانس).","selected":true,"suffix":"","activities":[{"time45":"10 د","time90":"20 د","teacher":"يشرح ص 62: المحلول ناتج ذوبان مادة في سائل، المادة المذابة والمادة المذيبة (ملح وماء في ماء البحر).","student":"يحدد المذاب والمذيب في أمثلة.","eval":"ص 62."},{"time45":"5 د","time90":"10 د","teacher":"يوضح بنموذج الجزيئات أن جزيئات المذاب تتحرك بين جزيئات المذيب فيبدو المحلول متجانساً.","student":"يشرح معنى «متجانس».","eval":"ص 63."},{"time45":"12 د","time90":"24 د","teacher":"يشرح ص 63 الفرق بين المخلوط والمادة النقية ويعرض أمثلة (حديد/فولاذ، أكسجين/هواء، ملح/ماء البحر).","student":"يصنف أمثلة إلى مخاليط ومواد نقية.","eval":"ص 63."},{"time45":"8 د","time90":"16 د","teacher":"يوجه تمرين 3-5: مادة ملونة في الماء وهل هو محلول ولماذا.","student":"يحدد المحلول ويعلل.","eval":"تمرين 3-5 ص 42."}]},{"id":"sci6~3_5_o1","code":"6Cc3","text":"يلاحظ ويصف ويسجل ويبدأ شرح التغيرات التي تحدث عند إضافة بعض المواد الصلبة إلى الماء (نشاط 3-5).","selected":true,"suffix":"","activities":[{"time45":"15 د","time90":"30 د","teacher":"ينفذ نشاط 3-5: ملعقة من مسحوق شراب بارد في 100 مل ماء، ملاحظة ما يحدث ورسمه وبعد خمس دقائق.","student":"يلاحظ ويرسم ويحدد المذاب والمذيب.","eval":"نشاط 3-5 ص 62."}]}],"prior":"المواد القابلة للذوبان وغير القابلة (الدرس 3-3)؛ نموذج جزيئات المادة (الصف الرابع) وتجارب الذوبان (الصف الخامس)","warmup":"كيف تعرف أن ماء البحر يحتوي على ملح وأنت لا تراه؟","resources":"كتاب الطالب (ص 62-63)، نشاط 3-5، تمرين 3-5 في كتاب النشاط، مسحوق شراب بارد، ملاعق صغيرة، كؤوس زجاجية، مخبار مدرج، ساعة إيقاف، ماء.","strategies":["العصف الذهني","الحوار والمناقشة","التعلم التعاوني","الأسئلة السابرة","التعلم الفردي"],"lab":"نشاط 3-5: تحتاج كل مجموعة (4–5 طلاب) إلى مسحوق شراب بارد، وملعقة صغيرة، ومخبار مدرج، وساعة إيقاف، وكؤوس زجاجية، وماء. يوضع 100 مل ماء في الكأس ثم ملعقة المسحوق، ويراقب الطلبة ما يحدث حول المسحوق، ويرسمون، وينتظرون خمس دقائق، ثم يحددون المذاب والمذيب. يُحرَّك المخلوط حتى يصبح المحلول متجانساً. (برمنجنات البوتاسيوم بديل ملون لكنها ضارة؛ يمنع تذوقها ولمسها ويغسل الطلبة أيديهم عند ملامستها).","misconception":"يظن بعض الطلبة أن المادة الذائبة لم تعد موجودة. التشخيص: يسأل المعلم أين ذهب السكر؟ المعالجة: يذيب ملحاً أو سكراً ويطلب تذوق المحلول فيكون مالحاً أو حلواً (لا يُتذوق إلا الملح والسكر)، ويوضح أن المادة تتحلل إلى جزيئات صغيرة جداً لا ترى بالعين، وأن الذوبان تغير فيزيائي لا تتكون فيه مادة جديدة.","exitTicket":"ما المذاب وما المذيب عند إذابة السكر في الشاي؟","homework":"إكمال تمرين 3-5 في كتاب النشاط، وتحضير ورقة العمل 3-5أ (ما الذي تعرفه عن المحاليل؟) للحصتين التاليتين.","guideAnswers":"<b>نشاط 3-5:</b> تتوزع جزيئات المسحوق في الماء ويصبح المحلول متجانساً؛ المذاب هو المسحوق (السكر) والمذيب هو الماء.<br><b>تمرين 3-5:</b> (1) أ. نعم. ب. تختفي المادة الصلبة الملونة من القاع وينتشر اللون في كل السائل بالتساوي؛ المذاب هو المادة الملونة والمذيب هو الماء. (2) إذا تمكنت من فصل السائل إلى مواد مختلفة فهو مخلوط، وإن لم تتمكن فهو مادة نقية."},"sci6~3_5b":{"course":"sci6","sem":1,"unitNum":3,"unitTitle":"الوحدة الثالثة: تغيّرات المادة","unitShort":"تغيّرات المادة","code":"3-5","title":"المحاليل: ب. الأسئلة والتخطيط للاستقصاء","defaultDuration":45,"objectives":[{"id":"sci6~3_5b_o0","code":"6Cc5","text":"يستكشف كيفية ذوبان بعض المواد الصلبة في الماء لتشكل محاليل، وأن المادة الصلبة وإن لم تعد مرئية فهي لا تزال موجودة (المحلول مخلوط وليس مادة نقية).","selected":true,"suffix":"","activities":[{"time45":"8 د","time90":"16 د","teacher":"يطرح السؤال 1 ص 63: هل المحلول مخلوط أم مادة نقية؟ ويصل مع الطلبة إلى أن المحلول مخلوط من مادتين هما المذاب والمذيب.","student":"يناقش ويتنبأ ويعلل.","eval":"السؤال 1 ص 63."},{"time45":"5 د","time90":"10 د","teacher":"يطرح تحدث عن ص 63: هل عصير البرتقال مخلوط أم محلول أم مادة نقية؟ ويتركه ليهدأ فتظهر طبقتان.","student":"يفسر لماذا العصير مخلوط.","eval":"تحدث عن ص 63."},{"time45":"8 د","time90":"16 د","teacher":"يناقش إجابات ورقة العمل 3-5أ (المذاب والمذيب والمحلول، المخاليط والمواد النقية، فصل المخاليط) ويتيح تقييم الأقران.","student":"يراجع إجابات زميله ويصحح.","eval":"ورقة العمل 3-5أ."}]},{"id":"sci6~3_5b_o1","code":"6Ep4","text":"يتنبأ بما سيحدث بناءً على المعرفة العلمية والفهم (هل المحلول مخلوط؟ وكمية السكر التي تذوب في الشاي).","selected":true,"suffix":"","activities":[{"time45":"8 د","time90":"16 د","teacher":"يطلب تنبؤاً معللاً بالسؤال 1 ص 63، ثم تنبؤاً بكمية السكر التي تذوب في 100 مل من الشاي (ورقة 3-5ب، 1).","student":"يكتب تنبؤه ويعلله بما يعرفه عن المخاليط والذوبان.","eval":"السؤال 1 + ورقة 3-5ب (1)."}]},{"id":"sci6~3_5b_o2","code":"6Ep3","text":"يختار الأدلة التي عليه جمعها لاستقصاء سؤال، ويتأكد من جمع الأدلة الكافية.","selected":true,"suffix":"","activities":[{"time45":"9 د","time90":"18 د","teacher":"يطرح السؤالين 2 و3 ص 63: ما الأدلة التي تحتاجها ولماذا؟ وكيف تتأكد من أنها كافية؟","student":"يحدد الدليل (محاولة فصل المحلول إلى مادتين) ويقترح اختبار عدة محاليل.","eval":"السؤالان 2 و3 ص 63."}]},{"id":"sci6~3_5b_o3","code":"6Ep7","text":"يختار الأدوات التي يجب استخدامها (إناء مفتوح لكل محلول، ميزان، مخبار مدرج، ملعقة).","selected":true,"suffix":"","activities":[{"time45":"8 د","time90":"16 د","teacher":"يطرح السؤال 4 ص 63 ثم أسئلة ورقة 3-5ب (2، 3): ما الطريقة وما الأدوات وما الذي سيقيسه الطلبة؟","student":"يختار الأدوات ويصف الطريقة.","eval":"السؤال 4 + ورقة 3-5ب (2، 3)."}]},{"id":"sci6~3_5b_o4","code":"6Eo7","text":"يستخدم النتائج لاستخلاص الاستنتاجات وتقديم المزيد من التنبؤات (كمية السكر في 250 مل من الشاي).","selected":true,"suffix":"","activities":[{"time45":"5 د","time90":"10 د","teacher":"يوجه استخدام نتيجة 100 مل من الشاي للتنبؤ بكمية السكر التي تذوب في 250 مل بالتناسب.","student":"يحسب ويتنبأ.","eval":"ورقة 3-5ب (6 ب)."}]},{"id":"sci6~3_5b_o5","code":"6Eo9","text":"يحدد ما إذا كانت الأدلة تدعم تنبؤاً ما، مبيناً كيف.","selected":true,"suffix":"","activities":[{"time45":"4 د","time90":"8 د","teacher":"يسأل كل مجموعة: هل دعمت نتائجك تنبؤك؟ وكيف عرفت؟","student":"يقارن النتيجة بتنبؤه ويبرر.","eval":"ورقة 3-5ب (6 أ)."}]}],"prior":"المحلول والمذاب والمذيب والمظهر المتجانس (الجزء أ)؛ الفرق بين المخلوط والمادة النقية (الجزء أ)؛ الترشيح وفصل المخاليط (الدرس 3-4)","warmup":"هل ماء البحر مادة نقية أم مخلوط؟","resources":"كتاب الطالب (ص 63)، تحدث عن، ورقتا العمل 3-5أ و3-5ب، أكياس شاي، سكر، كؤوس زجاجية، ماء ساخن، إبريق كهربائي أو موقد بنزن، مخبار مدرج، ميزان إلكتروني، ساق تحريك أو ملعقة، ساعة إيقاف، أوانٍ مفتوحة لتبخير المحاليل.","strategies":["العصف الذهني","الحوار والمناقشة","الأسئلة السابرة","التعلم التعاوني","التعلم الفردي"],"lab":"ورقة العمل 3-5ب (الشاي والسكر): تحتاج كل مجموعة (4–5 طلاب) إلى أكياس شاي، وسكر، وكأس زجاجية، ومخبار مدرج، وميزان إلكتروني، وساق تحريك أو ملعقة، وساعة إيقاف. يسخّن المعلم الماء ويصب 100 مل في كأس كل مجموعة ولا يتعامل الطلبة مع الماء الساخن بأنفسهم، ويترك كيس الشاي في الكأس 30 ثانية. يجهّز المعلم نحو 125 جم من السكر لكل 100 مل من الماء الساخن، وتذوب منه عشر ملاعق بسهولة تقريباً. يُوصى بكمية صغيرة من الشاي: فمع 250 مل يلزم نحو 300 جم من السكر قبل أن يتشبع المحلول. يناقش المعلم تنبؤات الطلبة قبل أن يبدؤوا. (تبخير المحاليل في السؤال 4: إناء مفتوح لكل محلول في مكان دافئ).","misconception":"قد يخلط الطلبة بين التغير الفيزيائي والتغير الكيميائي عند الذوبان، فيظنون أن المادة الصلبة تمتزج بالماء وتكوّن مادة جديدة كما في التفاعلات الكيميائية. التشخيص: يسأل المعلم هل أصبح الملح والماء مادة جديدة؟ المعالجة: يبخر قليلاً من محلول الملح في إناء مفتوح فيعود الملح كما كان، ويوضح أن كل جزيء من المادة الصلبة يبقى دون تغير، وأن المحلول مخلوط من مادتين يمكن فصلهما.","exitTicket":"لماذا نعد المحلول مخلوطاً وليس مادة نقية؟","homework":"ورقة العمل 3-5أ (واجب الدليل للموضوع) إن لم تُحل، وإكمال ورقة العمل 3-5ب (الاستنتاج والتنبؤ بكمية السكر في 250 مل) إن لم تكتمل.","guideAnswers":"<b>أسئلة ص 63:</b> (1) المحلول عبارة عن مخلوط. (2) تحتاج إلى محاولة فصل المخلوط إلى مادتين مختلفتين؛ إن استطعت فهو مخلوط، وإن لم تستطع فهو مادة نقية. (3) نستخدم عدداً من المحاليل المختلفة لفصلها. (4) يقترح الطلبة طريقة: تبخير المذيب من المحلول يترك المادة المذابة فيتضح أن المحلول مخلوط وليس مادة نقية؛ يحتاجون إلى إناء مفتوح لكل محلول يوضع في مكان دافئ. (5) نستخدم المذيب نفسه مع محاليل مختلفة، ونفس الكميات من المذيب والمذاب في كل محلول، ونترك الأواني في المكان نفسه لنحصل على القدر نفسه من الدفء ومن ثم التبخر.<br><b>تحدث عن:</b> عصير البرتقال ينفصل عند تركه إلى سائل مائي في الأعلى فيه مواد ذائبة وطبقة داكنة في الأسفل من مواد صلبة معلقة؛ فهو مخلوط وليس مادة نقية.<br><b>ورقة العمل 3-5أ:</b> (1) الملح قابل للذوبان في الماء، والماء مادة مذيبة، والملح مادة مذابة، ويشكل مخلوط الملح والماء محلولاً له مظهر متجانس، ولفصل الملح عن الماء نبخر المخلوط. (2) أ. رمل، مسحوق الكبريت، طباشير. ب. كبريتات النحاس، سكر. ج. محلول. (3) الحبر قابل للذوبان في الكحول الميثيلي لكنه غير قابل للذوبان في الماء. (4) نخلط المواد الصلبة بالماء فيذوب السكر، وبترشيح المخلوط تبقى الطباشير فوق ورقة الترشيح ويمر محلول السكر عبر الثقوب، ثم نعرض محلول السكر للحرارة حتى يتبخر الماء ويبقى السكر. (5) مواد نقية: الماء والذهب؛ مخاليط: القهوة والهواء والطين.<br><b>ورقة العمل 3-5ب:</b> (1) تنبؤات الطلبة. (2) سكر، شاي، ماء، كأس، إبريق كهربائي أو موقد بنزن، مخبار مدرج، ملعقة، ساق أو ملعقة للتحريك. (3) كم جراماً من السكر يذوب في 100 مل من الشاي. (4) كمية الشاي. (5) كمية السكر المضافة. (6) أ. تعتمد الإجابة على التنبؤات؛ نحو 25 ملعقة صغيرة (125 جم) من السكر تذوب في 100 مل من الشاي. ب. يتنبأ الطلبة بأن نحو 300 جم من السكر تذوب في 250 مل من الشاي.<br><b>تمرين 3-5 (كتاب النشاط):</b> (1) أ. نعم. ب. تختفي المادة الصلبة الملونة من القاع وينتشر اللون في كل السائل بالتساوي؛ المذاب هو المادة الملونة والمذيب هو الماء. (2) إذا تمكنت من فصل السائل إلى مواد مختلفة فهو مخلوط، وإن لم تتمكن فهو مادة نقية."}});/*COURSE_DB_END*/



const KEYS = Object.keys(DB);
/* المواد والصفوف: كل درس يحمل مقرره (course) مثل sci5 أو sci6، والعلوم للصف السادس افتراضي.
   مفتاح الدرس في المقررات الجديدة: "<course>~<unit>_<lesson>" مثل "phys11~1_2" */
const SUBJECTS = {
  sci: { name: "العلوم", short: "علوم", icon: "i-flask" }
};
const GRADES = { 5: "الخامس", 6: "السادس" };
const COURSES = {};
Object.keys(SUBJECTS).forEach(s => Object.keys(GRADES).forEach(g => { COURSES[s + g] = { id: s + g, subject: s, grade: +g }; }));
KEYS.forEach(k => { if (!DB[k].course) DB[k].course = "sci6"; });
function courseOf(k){ return DB[k] ? DB[k].course || "sci6" : "sci6"; }
function courseKeys(c){ c = c || state.course; return KEYS.filter(k => courseOf(k) === c); }
function courseMeta(k){ const c = COURSES[courseOf(k)] || COURSES.sci6; return { id: c.id, subj: SUBJECTS[c.subject], subject: c.subject, grade: c.grade, gradeName: GRADES[c.grade] }; }
/* الفصول الدراسية: كل درس يحمل رقم فصله (sem)، والفصل الأول افتراضي */
const SEMESTERS = { 1: "الفصل الدراسي الأول", 2: "الفصل الدراسي الثاني" };
const SEM_SHORT = { 1: "الفصل الأول", 2: "الفصل الثاني" };
KEYS.forEach(k => { if (!DB[k].sem) DB[k].sem = 1; });
function semOf(k){ return DB[k] ? DB[k].sem || 1 : 1; }
function semList(){ return [...new Set(courseKeys().map(semOf))].sort((a, b) => a - b); }
function semKeys(s){ return courseKeys().filter(k => semOf(k) === s); }
function semName(s){ return SEMESTERS[s] || `الفصل الدراسي ${s}`; }
function uidOf(k){ return courseOf(k) + ":" + semOf(k) + ":" + DB[k].unitNum; }
function unitList(keys){ return [...new Set((keys || courseKeys()).map(uidOf))]; }
function unitKeys(uid, keys){ return (keys || KEYS).filter(k => uidOf(k) === uid); }
function keyHash(k){ return String(k).replace(/_/g, "-"); }
const EXTRA_OBJ = {};
Object.entries(EXTRA_OBJ).forEach(([k, list]) => list.forEach(([code, text]) => { const d = DB[k]; if (d && !d.objectives.some(o => o.code === code)) d.objectives.push({ id: `${k}_o${d.objectives.length}`, code, text, selected: true, activities: [] }); }));
