function stepsHTML(arr){ return arr.filter(Boolean).map((s, i) => `${i + 1}. ${s}`).join("<br>"); }
function evalHTML(e){
  return [`<strong>الأداة:</strong> ${e.tool}`, e.q ? `<strong>السؤال:</strong> ${e.q}` : "", e.ans ? `<strong>الإجابة المتوقعة:</strong> ${e.ans}` : "", e.book ? `<strong>سؤال الكتاب ${e.book.q ? "(" + e.book.q + ")" : ""}:</strong> الإجابة النموذجية: ${e.book.a}` : "", e.crit ? `<strong>معيار النجاح:</strong> ${e.crit}` : ""].filter(Boolean).join("<br>");
}
function endDot(s){ const t = cleanEnd(s); return /[؟!.)»]$/.test(t) ? t : t + "."; }
function cleanEnd(s){ return String(s || "").trim().replace(/[.،؛\s]+$/, ""); }
function parseGuide(html){
  return String(html || "").split(/<br\s*\/?>/i).map(s => s.trim()).filter(Boolean).map(it => {
    const m = /^<(?:b|strong)>\s*([^<]*?)\s*<\/(?:b|strong)>\s*/i.exec(it);
    const q = m ? m[1].replace(/:\s*$/, "").replace(/^السؤال\s*/, "") : "";
    return { q, a: cleanEnd(plainText(m ? it.slice(m[0].length) : it)) };
  }).filter(g => g.a);
}
function splitMis(mis){
  const s = cleanEnd(mis), i = s.search(/[؛;]/);
  const claim = cleanEnd(i > 0 ? s.slice(0, i) : s);
  let fix = cleanEnd(i > 0 ? s.slice(i + 1).trim().replace(/^و\s*/, "") : "");
  if (/^مما\s+يؤدي/.test(fix)) fix = "";
  const m = /^((الظن|الاعتقاد)\s+(بأن|أن)|(اعتقاد|يعتقد)\s+(بعض\s+)?(الطلاب|الطلبة)\s+(بأن|أن))\s+/.exec(claim);
  return { claim, fix, belief: !!m, statement: m ? cleanEnd(claim.slice(m[0].length)) : "" };
}
function misFixStep(c){
  if (!c.mis.claim) return "يؤطر المفهوم علمياً ويلخصه في خريطة مفاهيم على السبورة.";
  return c.mis.fix ? `يعالج التصور الخاطئ «${shortText(c.mis.claim, 110)}»: ${c.mis.fix}.` : `يعالج التصور الخاطئ «${shortText(c.mis.claim, 110)}» بمثال مضاد ومناقشة سبب الخطأ.`;
}
function misProbe(c){
  if (!c.mis.claim) return { step: `يطرح السؤال المحفز: «${c.hookQ}»`, q: c.hookQ };
  if (c.mis.belief) return { step: `يستطلع التصورات القبلية بعرض العبارة: «${c.mis.statement}» ويطلب رفع بطاقة (أوافق / لا أوافق) مع تبرير قصير.`, q: `هل توافق على أن ${c.mis.statement}؟ ولماذا؟` };
  return { step: `يعرض مثالاً لخطأ شائع: «${shortText(c.mis.claim, 110)}» ويسأل الطلاب: أين الخطأ؟ وكيف نتجنبه؟`, q: "أين الخطأ في المثال المعروض؟ وكيف نتجنبه؟" };
}
function labParts(lab){
  const s = cleanEnd(lab), m = /(الأمان|أمان(?:\s+(?:فائق|صارم))?|السلامة)\s*:\s*(.+)$/.exec(s);
  return { head: cleanEnd(m ? s.slice(0, m.index) : s), safety: m ? cleanEnd(m[2]) : "" };
}
function critOf(text){
  const t = cleanEnd(text), sp = t.indexOf(" ");
  return sp > 0 ? `أن ${t.slice(0, sp)} الطالب ${t.slice(sp + 1)}` : t;
}
function asQuestion(ev){
  const s = cleanEnd(plainText(ev)).replace(/^(سؤال(\s+شفهي)?|تقويم كتابي فوري|حل تدريب|حل مسألة|حل تمرين|تحديد|أداء عملي|مقارنة شفهية)\s*:\s*/, "");
  return s;
}
function hookQuestion(warm, acts){
  const w = cleanEnd(warm), qi = w.lastIndexOf("؟");
  if (qi > 0){ const head = w.slice(0, qi + 1), ci = head.lastIndexOf(":"); return cleanEnd(ci > 0 ? head.slice(ci + 1) : head); }
  return acts[0] ? asQuestion(acts[0].eval) : "ما الذي تتوقع أن نتعلمه اليوم من هذا الموقف؟";
}
function priorItems(prior){
  const items = cleanEnd(prior).split("،").map(cleanEnd).filter(x => x.length > 5).slice(0, 2);
  return items;
}
function shortText(s, n){ const t = cleanEnd(plainText(s)); return t.length > n ? t.slice(0, n).replace(/\s+\S*$/, "") + "…" : t; }

