    + (hiddenN > 0 ? `<button type="button" class="chip more" data-more="1">+ ${hiddenN} استراتيجيات أخرى</button>` : state.stratAll ? `<button type="button" class="chip more" data-more="0">عرض أقل</button>` : "");
  $("#optMis").checked = state.opts.mis; $("#optLab").checked = state.opts.lab;
