    const body = p(run(`تحضير ${courseMeta(pl.key).subj.short} ${courseMeta(pl.key).grade}، الدرس \u200E${pl.d.code}\u200E  |  ${pl.meta.teacher || ""}  |  صفحة `, o) + fld("PAGE") + run(" من ", o) + fld("NUMPAGES"), { center: true, after: 0, topBorder: "CBD5E1" });
