      pink:["FBD3D9","9F1239","FFF9FA","9F1239"], peach:["FDE0BC","9A4A08","FFFBF4","9A4A08"], mint:["C9EEDD","0F6E4D","F6FCF9","0F6E4D"], sky:["CFE2F7","1E4E8C","F7FAFE","1E4E8C"],
      lab:["FFFFFF","14213D","FFFFFF","14213D"], rnavy:["12456E","0B2447","F3F7FC","FFFFFF"], rpurple:["6A2AA8","4C1D95","FAF5FE","FFFFFF"],
