      cell(p(run(`الصف ${courseMeta(pl.key).gradeName}`, { bold: true, size: 18, color: "0B1D3A" }), { center: true, after: 0 }) + p(run(semName(semOf(pl.key)), { size: 16, color: "9C7020" }), { center: true, after: 0 }), 2000)
