    const acts = pl.flow.length ? pl.flow.map((r, i, arr) => ph(r, i, arr) + p(run(`${r.time}  `, { bold: true, size: 17, color: C.indigo[1] }) + run(r.code, { bold: true, size: 17, color: "6B7590" }) + (r.strat ? run(`  (${r.strat})`, { bold: true, size: 16, color: "B4231A" }) : ""), { after: 10, keepNext: true })
      + p(run("المعلم: ", { bold: true, size: 17 }) + rich(pl.def && !r.ed.teacher ? stripPhase(r.teacher) : r.teacher, xs), { after: 10 })
      + p(run("المتعلم: ", { bold: true, size: 17 }) + rich(r.student, xs), { after: 80 })).join("") : P("—");
    const res = P(pl.t.resources) + (pl.opts.lab ? lbl("النشاط العملي والسلامة:", pl.t.lab, "purple") : "");
    const chosen = new Set(pl.strategies);
    const list = (pl.def ? [pl.def.label] : []).concat(allStrategies(pl.key));
    const strat = list.map(s => p(run(chosen.has(s) ? "(✓) " : "(   ) ", { bold: true, size: 17, color: C.green[1] }) + run(s, { size: 17, bold: chosen.has(s) }), { after: 20 })).join("");
    const outc = pl.objs.length ? pl.objs.map(o => p(run(`المخرج (${objLabel(o)})`, { bold: true, size: 17, color: C.amber[1] }), { after: 0 }) + p(rich(o.text, xs), { after: 60 })).join("") : P("—");
    b += table(W3, [
      [H("01  المخرجات التعليمية", "amber", W3[0]), H("02  الاستراتيجيات / طرق التدريس", "green", W3[1]), H("03  الوسائل ومصادر التعلم", "purple", W3[2])],
      { split: true, cells: [B(outc, "amber", W3[0]), B(strat, "green", W3[1]), B(res, "purple", W3[2])] }
    ], { style: "grid", headerRow: true });
