function parseFlow(data){
  const arr = Array.isArray(data) ? data : (data && Array.isArray(data.rows) ? data.rows : null);
  if (!arr || arr.length < 2 || arr.length > 40) throw new Error("shape");
  return arr.map(r => {
    const row = { period: parseInt(r.period, 10) || 1, strat: String(r.strat || "").trim(), time: String(r.time || "").trim(), phase: String(r.phase || "").trim(), teacher: String(r.teacher || "").trim(), student: String(r.student || "").trim(), eval: String(r.eval || "").trim() };
    if (!row.teacher || !row.student || !row.eval || !/\d/.test(row.time)) throw new Error("shape");
    row.time = minutesOf(row.time) + " د";
    return row;
  });
}
let adaptCtl = null;
function brs(s){ return String(s || "").trim().replace(/\r/g, "").replace(/\n+/g, "<br>"); }
