    if (rb){
      if (resetArmed){ clearTimeout(resetArmed); resetArmed = null; const rec = getRec(state.key); rec.edits = {}; (rec.week || []).forEach(w => { if (w) delete w.codes; }); touch(); renderOutput(); toast("أُعيدت النصوص الأصلية"); }
      else { rb.textContent = "اضغط مرة أخرى للتأكيد"; resetArmed = setTimeout(() => { resetArmed = null; renderCrumbs(); }, 3500); }
      return;
    }
