      const col = el.closest(".diffcol"); if (col) col.classList.toggle("no-print", !rec.diff[el.dataset.diff]);
      const sec = el.closest(".diffsec"); if (sec) sec.classList.toggle("no-print", !(rec.diff.support || rec.diff.enrich));
